'use strict';
window.BD_BOOKS = [{"id": "old-a", "hall": "ot", "subject": "Archaeology", "editions": {"short": {"title": "Ten Things Found", "subtitle": "Ten real discoveries from Old Testament times, and what each one says", "blurb": "Ten things that came out of the ground. A broken stone, a black pillar, a clay barrel, a silver roll and a very long scroll. Every one of them is real, and you can go and see it.", "pages": [{"number": 1, "title": "What is a find?", "text": "Long ago people built towns of mud brick. When a town fell down, they built a new one on top. After a very long time there was a hill made of old towns.\n\nArchaeologists dig into these hills slowly, with small tools. Mostly they find broken pots. Sometimes they find writing.\n\nHere are ten things with writing or pictures on them. Each one meets the Bible somewhere."}, {"number": 2, "title": "The broken stone", "text": "**The Tel Dan Stele.** Found in Israel in 1993, in three pieces, in an old wall.\n\nAn enemy king had it carved about 840 BC. He brags that he beat a king from the “House of David.”[^tel-dan-stele]\n\nSome people used to say King David was only a story. This stone was made by David’s enemies. They knew his family by name.\n\n*Read 2 Kings 8:28–29.*", "sources": [{"id": "tel-dan-stele", "label": "The Tel Dan Stele · “House of David”, about 840 BC", "citation": "Avraham Biran and Joseph Naveh, “An Aramaic Stele Fragment from Tel Dan,” Israel Exploration Journal 43 (1993): 81–98; “The Tel Dan Inscription: A New Fragment,” IEJ 45 (1995): 1–18. Israel Museum, Jerusalem.", "trail": "Found by Gila Cook of Biran’s team, July 1993; fragments B1 and B2 in 1994 → Biran and Naveh → George Athas, The Tel Dan Inscription (Sheffield, 2003).", "note": "The phrase bytdwd is read “House of David” by nearly all specialists; a few early alternatives (a place name, “house of the kettle”) have not held. The speaker is most likely Hazael of Damascus, who claims the killings 2 Kings 9 credits to Jehu; perhaps Jehu acted in league with Hazael, or the king took credit. How the fragments join is still discussed.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 3, "title": "The black pillar", "text": "**The Black Obelisk.** Found in Iraq in 1846. It is as tall as a man.\n\nIt shows people bringing gifts to the king of Assyria. One man is bowing with his face on the ground. The writing says he is Jehu of Israel.[^black-obelisk]\n\nThe Bible tells us about King Jehu. This is the only picture of a king of Israel that we have.\n\n*Read 2 Kings 9:1–6.*", "sources": [{"id": "black-obelisk", "label": "The Black Obelisk · Jehu’s tribute, 841 BC", "citation": "Black Obelisk of Shalmaneser III, from Nimrud; British Museum, 1848,1104.1. Found by Austen Henry Layard in 1846; Nineveh and Its Remains (London, 1849). Edited in Grayson, Royal Inscriptions of Mesopotamia, Assyrian Periods 3 (1996).", "trail": "The obelisk → Edward Hincks and Henry Rawlinson read the name in 1851 → Grayson 1996.", "note": "The caption calls him “Jehu, son of Omri.” Jehu was not Omri’s son; he ended that family (2 Kings 9–10). Assyrians called Israel the House of Omri for a century, so “son of Omri” means “of the land of Omri.” The kneeling figure may be Jehu himself or his envoy.", "url": "https://www.britishmuseum.org/collection/object/W_1848-1104-1", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}]}, {"number": 4, "title": "The stone that was smashed", "text": "**The Mesha Stele.** Found in Jordan in 1868.\n\nPeople fought over it, and it was broken into pieces on purpose. Luckily someone had already pressed wet paper on it to copy the words.\n\nA king of Moab tells how he fought against Israel.[^mesha-stele] The Bible tells about the same war from the other side.\n\n*Read 2 Kings 3:4–5.*", "sources": [{"id": "mesha-stele", "label": "The Mesha Stele · Moab’s side of the story", "citation": "Basalt stele of Mesha, king of Moab, about 840 BC; Louvre, AO 5066. Seen at Dhiban by F. A. Klein in 1868; a paper squeeze was taken for Charles Clermont-Ganneau before the stone was broken. Translation by K. A. D. Smelik in The Context of Scripture, vol. 2 (2000), no. 2.23.", "trail": "The stone and squeeze → Clermont-Ganneau 1870 → Smelik → André Lemaire, “‘House of David’ Restored in Moabite Inscription,” Biblical Archaeology Review 20:3 (1994).", "note": "Mesha says Omri oppressed Moab “many days” and that he took vessels of Yahweh from Nebo. 2 Kings 3 tells the revolt from Israel’s side; the two differ on who won. Lemaire’s reading of “House of David” in line 31 is possible but damaged and still debated.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 5, "title": "The six-sided boast", "text": "**Sennacherib’s Prism.** Found in Iraq in 1830. It is made of clay and has six sides.\n\nThe king of Assyria says he trapped King Hezekiah in Jerusalem “like a bird in a cage.”[^sennacherib-prism]\n\nBut he never says he got in. The Bible tells us why. God saved the city in one night.\n\n*Read 2 Kings 19:32–36.*", "sources": [{"id": "sennacherib-prism", "label": "Sennacherib’s prisms · Hezekiah “like a bird in a cage”", "citation": "Taylor Prism, British Museum; Oriental Institute Prism, Chicago; Jerusalem Prism, Israel Museum. Daniel David Luckenbill, The Annals of Sennacherib (Oriental Institute Publications 2, Chicago, 1924); A. Kirk Grayson and Jamie Novotny, Royal Inscriptions of the Neo-Assyrian Period 3/1 (2012).", "trail": "Prisms from Nineveh → Luckenbill 1924 → Grayson and Novotny 2012; on the murder, Simo Parpola, “The Murderer of Sennacherib,” in Death in Mesopotamia (1980); Herodotus, Histories 2.141.", "note": "Sennacherib claims 46 towns and 30 talents of gold, the same figure as 2 Kings 18:14 (the silver differs, 800 talents to 300). He never claims Jerusalem. Herodotus heard in Egypt that mice gnawed the Assyrians’ bowstrings in one night; 2 Kings 19:35 says the angel of the LORD struck the camp. Babylonian Chronicle 1 and Esarhaddon’s own inscription confirm his murder by a son (2 Kings 19:37).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 6, "title": "The battle on the wall", "text": "**The Lachish Reliefs.** Found in Iraq in 1847. They are stone pictures, longer than a bus.\n\nThey show the Assyrian army attacking the town of Lachish in Judah.[^lachish-reliefs] You can see ramps, soldiers and families leaving.\n\nThe king put this on his palace wall because it was his biggest win. He had no picture of Jerusalem to put there.\n\n*Read 2 Kings 18:13–14.*", "sources": [{"id": "lachish-reliefs", "label": "The Lachish reliefs · Sennacherib’s showpiece", "citation": "Stone panels from Room XXXVI of the Southwest Palace, Nineveh, excavated by Layard 1847–51; British Museum. David Ussishkin, The Conquest of Lachish by Sennacherib (Tel Aviv University, 1982).", "trail": "The reliefs → Layard → Ussishkin 1982, with the excavated siege ramp at Lachish.", "note": "The Assyrian siege ramp at Lachish, the only one of its kind excavated, still lies against the city’s south-west corner, with a Judahite counter-ramp inside. Arrowheads, sling stones and the remains of the burned gate match the carving closely.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 7, "title": "The writing in the tunnel", "text": "**The Siloam Inscription.** Found in Jerusalem in 1880 by a boy.\n\nKing Hezekiah had a tunnel cut through rock to bring water into the city. Two teams dug from each end.[^siloam-tunnel] The writing tells how they heard each other through the rock, and then broke through.\n\nYou can still walk through that tunnel today.\n\n*Read 2 Kings 20:20.*", "sources": [{"id": "siloam-tunnel", "label": "The Siloam Tunnel and its inscription", "citation": "Inscription found in 1880; Istanbul Archaeology Museums. Amos Frumkin, Aryeh Shimron and Jeff Rosenbaum, “Radiometric dating of the Siloam Tunnel, Jerusalem,” Nature 425 (2003): 169–171.", "trail": "The tunnel → the inscription (Conrad Schick, Archibald Sayce, 1880–81) → Frumkin et al. 2003.", "note": "Radiocarbon from plant matter in the plaster and uranium-thorium dates from cave deposits place the tunnel about 700 BC, Hezekiah’s time (2 Kings 20:20; 2 Chronicles 32:30). A few scholars have proposed an earlier start; the inscription’s letter forms also fit about 700.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 8, "title": "The silver rolls", "text": "**The Ketef Hinnom Scrolls.** Found in Jerusalem in 1979. A boy your age broke through the floor that hid them.\n\nThey are two tiny rolls of silver. Inside is a blessing from the Bible: “The LORD bless you and keep you.”[^ketef-hinnom]\n\nThey are about 2,600 years old. No one has found older words from the Bible.\n\n*Read Numbers 6:24–26.*", "sources": [{"id": "ketef-hinnom", "label": "Ketef Hinnom · the silver scrolls", "citation": "Excavated by Gabriel Barkay, 1979; Israel Museum. Gabriel Barkay, Marilyn J. Lundberg, Andrew G. Vaughn and Bruce Zuckerman, “The Amulets from Ketef Hinnom: A New Edition and Evaluation,” Bulletin of the American Schools of Oriental Research 334 (2004): 41–71.", "trail": "Cave 25 at Ketef Hinnom → first edition by Barkay (1992) → the new imaging and edition of 2004.", "note": "The 2004 edition, using new imaging, confirms a late 7th- or early 6th-century date and reads a form of Numbers 6:24–26. A few scholars had argued for a later date; the new edition answers them on letter forms and archaeology.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 9, "title": "The city diary", "text": "**The Babylonian Chronicle.** A small clay tablet, now in London.\n\nThe Babylonians wrote down what their king did each year. This tablet says he captured “the city of Judah” and took away its king.\n\nIt even gives the day. In our calendar it was 16 March 597 BC.[^babylonian-chronicle] The Bible tells about that very day.\n\n*Read 2 Kings 24:10–12.*", "sources": [{"id": "babylonian-chronicle", "label": "The Babylonian Chronicle · Jerusalem taken on 2 Adar 597 BC", "citation": "Chronicle 5 (the “Jerusalem Chronicle”), British Museum 21946. D. J. Wiseman, Chronicles of Chaldaean Kings (626–556 B.C.) in the British Museum (London, 1956); A. K. Grayson, Assyrian and Babylonian Chronicles (Locust Valley, 1975).", "trail": "The tablet → Wiseman 1956 → Grayson 1975 → Jean-Jacques Glassner, Mesopotamian Chronicles (Society of Biblical Literature, 2004).", "note": "It records Carchemish (605 BC, Jeremiah 46:2) and the capture of “the city of Judah” on 2 Adar of Nebuchadnezzar’s seventh year: 15/16 March 597 BC. The chronicles for 594–557 BC are missing, which is why 587 or 586 for Jerusalem’s fall is still argued.", "url": "https://www.livius.org/sources/content/mesopotamian-chronicles-content/abc-5-jerusalem-chronicle/", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 10, "title": "The clay barrel", "text": "**The Cyrus Cylinder.** Found in Iraq in 1879. It is a little smaller than a football.\n\nKing Cyrus of Persia says he sent captured peoples back to their homes.[^cyrus-cylinder]\n\nIt does not name the Jews. But the Bible says Cyrus did the same for them, and let them go home to rebuild God’s house.\n\n*Read Ezra 1:1–3.*", "sources": [{"id": "cyrus-cylinder", "label": "The Cyrus Cylinder · the policy of return", "citation": "Clay cylinder, Babylon, after 539 BC; British Museum, 1880,0617.1941. Found by Hormuzd Rassam in 1879. Irving Finkel (ed.), The Cyrus Cylinder: The King of Persia’s Proclamation from Ancient Babylon (I. B. Tauris, 2013).", "trail": "The cylinder → Rawlinson’s first translation (1880) → Finkel 2013, with the fragments of a second copy identified in 2010.", "note": "Cyrus says he returned gods and peoples to their homes. It names places in Mesopotamia and western Iran, not Judah. It shows a policy; Ezra 1 and 6 record a decree for Jerusalem. Some historians think Cyrus’s generosity was more limited than his propaganda claims; Ezra’s decree fits the way Persian kings dealt with local temples.", "url": "https://www.britishmuseum.org/collection/object/W_1880-0617-1941", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}]}, {"number": 11, "title": "The very long scroll", "text": "**The Great Isaiah Scroll.** Found in a cave by the Dead Sea in 1947, in a jar.\n\nIt is the whole book of Isaiah, as long as a room is wide. It was copied about 125 years before Jesus was born.[^dead-sea-scrolls]\n\nIt has the same words as the Isaiah in your Bible. People copied them very carefully for a very long time.\n\n*Read Isaiah 53:4–6.*", "sources": [{"id": "dead-sea-scrolls", "label": "The Dead Sea Scrolls", "citation": "Eleven caves near Qumran, 1947–1956; Roland de Vaux’s excavation of the settlement, Archaeology and the Dead Sea Scrolls (Schweich Lectures 1959; Oxford, 1973). James VanderKam and Peter Flint, The Meaning of the Dead Sea Scrolls (HarperSanFrancisco, 2002). The Great Isaiah Scroll, 1QIsaᵃ, is in the Shrine of the Book, Israel Museum.", "trail": "The caves → de Vaux → the official edition, Discoveries in the Judaean Desert (Oxford, 1955–2011) → VanderKam and Flint.", "note": "Most scholars link the scrolls with the Essenes described by Pliny the Elder (Natural History 5.73) and Josephus (Jewish War 2.119–161); Norman Golb argued they came from Jerusalem libraries. The Isaiah scroll is about a thousand years older than the Leningrad Codex (AD 1008) and agrees with it closely. Some books, such as Jeremiah, also circulated in a shorter edition close to the Septuagint.", "url": "http://dss.collections.imj.org.il/isaiah", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 12, "title": "What the ten tell us", "text": "These ten things were made by many peoples. Some of them were Israel’s enemies. None of them was trying to help the Bible.\n\nYet each one fits what the Bible says. The kings were real. The wars were real. The words were kept safe.\n\nThese discoveries show that the Bible tells about real people in real places. God can use what we learn to deepen our trust in him. That is a good reason to keep reading his Word."}], "source": "Foundation-Claude/old-testament/books/OT-A-archaeology-short.md", "sha256": "f6e7f5e782454aa0809bdb226d510e797255810f91f69b05f5db7c9a55153c69"}, "long": {"title": "The Spade and the Scroll", "subtitle": "A field guide to twenty discoveries from the Old Testament’s world", "blurb": "A stone built into a wall. A silver roll smaller than your finger. A clay barrel that an emperor buried. Each was found by someone who was looking for something else, and each has a line in it that you already know.", "pages": [{"number": 1, "title": "Before you dig", "text": "In the Bible’s lands a town was built of mud brick on stone footings. When it burned or fell down, people leveled the ruin and built on top. After two thousand years of this there is a hill with flat sides where no hill used to be. It is called a tel.\n\nA tel is read from the top down, and the top is the newest. Each layer is a city. Each city has floors, and on the floors are the things people dropped, lost or left behind when they ran.\n\nAn archaeologist’s first rule is that where a thing lies matters more than what it is. A seal on a burnt floor has a date and a story. The same seal in a dealer’s shop has neither.\n\nMost of what you find is broken pottery. Now and then there is writing."}, {"number": 2, "title": "How a find is read", "text": "When something with writing comes out of the ground, ask three questions in this order.\n\n**What is it?** A slab of basalt. A clay tablet. Say only what you can see.\n\n**What does its maker claim?** Kings wrote to be admired. They list their victories and leave out their defeats. That does not make them useless. It means you read them as you would read anyone’s account of his own success.\n\n**How does it meet the Bible?** Sometimes it names the same king. Sometimes it describes the same war from the other side. Sometimes it only shows that the Bible’s world was real.\n\nThen give it a grade. **Secure** means everyone who can read it agrees. **Strong** means nearly everyone. **Debated** means the experts are still arguing. **Caution** means do not lean on it."}, {"number": 3, "title": "A stone in a wall", "text": "In July 1993 a surveyor named Gila Cook was working at Tel Dan, in the far north of Israel. Late in the day the low sun fell across an old wall, and she saw letters on one of its stones.\n\nIt was a piece of a monument, broken up long ago and reused as building stone. Two more pieces turned up the next year. Together they give thirteen lines of Aramaic from about 840 BC.\n\nThe speaker is a king of Damascus, almost certainly Hazael. He boasts that he killed a king of Israel and a king of the “House of David.”\n\nBefore 1993 some scholars said David was a legend. Here an enemy, about 130 years after David, calls the kings of Judah by his name.[^tel-dan-stele]\n\n*Grade: Secure. Read 2 Kings 8:28–9:28.*", "sources": [{"id": "tel-dan-stele", "label": "The Tel Dan Stele · “House of David”, about 840 BC", "citation": "Avraham Biran and Joseph Naveh, “An Aramaic Stele Fragment from Tel Dan,” Israel Exploration Journal 43 (1993): 81–98; “The Tel Dan Inscription: A New Fragment,” IEJ 45 (1995): 1–18. Israel Museum, Jerusalem.", "trail": "Found by Gila Cook of Biran’s team, July 1993; fragments B1 and B2 in 1994 → Biran and Naveh → George Athas, The Tel Dan Inscription (Sheffield, 2003).", "note": "The phrase bytdwd is read “House of David” by nearly all specialists; a few early alternatives (a place name, “house of the kettle”) have not held. The speaker is most likely Hazael of Damascus, who claims the killings 2 Kings 9 credits to Jehu; perhaps Jehu acted in league with Hazael, or the king took credit. How the fragments join is still discussed.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 4, "title": "The stone they broke", "text": "In 1868 a missionary was shown a black stone lying at Dhiban, east of the Dead Sea. It was over a meter tall and covered in writing. French and German agents both tried to buy it. While they bargained, a paper mold was pressed onto it to copy the text.\n\nThat was fortunate. The stone’s keepers, angry at the pressure, heated it in a fire and poured cold water on it. It burst. The pieces were later gathered, and the paper mold showed where they went.\n\nIt is the monument of Mesha, king of Moab.[^mesha-stele] He says Omri, king of Israel, had oppressed Moab, and that he, Mesha, broke free. He names Israel’s God, Yahweh.\n\nThe Bible tells the same revolt from Israel’s side.\n\n*Grade: Secure. It is in the Louvre. Read 2 Kings 3.*", "sources": [{"id": "mesha-stele", "label": "The Mesha Stele · Moab’s side of the story", "citation": "Basalt stele of Mesha, king of Moab, about 840 BC; Louvre, AO 5066. Seen at Dhiban by F. A. Klein in 1868; a paper squeeze was taken for Charles Clermont-Ganneau before the stone was broken. Translation by K. A. D. Smelik in The Context of Scripture, vol. 2 (2000), no. 2.23.", "trail": "The stone and squeeze → Clermont-Ganneau 1870 → Smelik → André Lemaire, “‘House of David’ Restored in Moabite Inscription,” Biblical Archaeology Review 20:3 (1994).", "note": "Mesha says Omri oppressed Moab “many days” and that he took vessels of Yahweh from Nebo. 2 Kings 3 tells the revolt from Israel’s side; the two differ on who won. Lemaire’s reading of “House of David” in line 31 is possible but damaged and still debated.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 5, "title": "The king who bowed", "text": "In 1846 Austen Henry Layard was digging at Nimrud in Iraq and had almost given up on one trench when his workmen struck a black stone pillar, two meters tall and complete.\n\nIt has twenty small carved panels, five on each side, showing the tribute brought to the Assyrian king Shalmaneser III. In one panel a man kneels with his face to the ground. The writing above says this is the tribute of “Jehu, son of Omri”: silver, gold, a golden bowl, golden cups.[^black-obelisk]\n\nThe year is 841 BC. The Bible tells how Jehu seized the throne of Israel that year. It does not mention that he paid Assyria. The pillar adds something the Bible left out.\n\nIt is the only picture we are likely to have of a king of Israel.\n\n*Grade: Secure. British Museum. Read 2 Kings 9–10.*", "sources": [{"id": "black-obelisk", "label": "The Black Obelisk · Jehu’s tribute, 841 BC", "citation": "Black Obelisk of Shalmaneser III, from Nimrud; British Museum, 1848,1104.1. Found by Austen Henry Layard in 1846; Nineveh and Its Remains (London, 1849). Edited in Grayson, Royal Inscriptions of Mesopotamia, Assyrian Periods 3 (1996).", "trail": "The obelisk → Edward Hincks and Henry Rawlinson read the name in 1851 → Grayson 1996.", "note": "The caption calls him “Jehu, son of Omri.” Jehu was not Omri’s son; he ended that family (2 Kings 9–10). Assyrians called Israel the House of Omri for a century, so “son of Omri” means “of the land of Omri.” The kneeling figure may be Jehu himself or his envoy.", "url": "https://www.britishmuseum.org/collection/object/W_1848-1104-1", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}]}, {"number": 6, "title": "Ahab’s chariots", "text": "The Bible gives King Ahab six chapters, most of them about his wife Jezebel, the prophet Elijah and a stolen vineyard. It says little about his army.\n\nAn Assyrian monument found in Turkey in 1861 fills the gap. Shalmaneser III lists the kings who fought him at Qarqar in 853 BC. One is “Ahab the Israelite,” who brought two thousand chariots and ten thousand foot soldiers.[^kurkh-monolith] No king on the list brought more chariots.\n\nSo the Bible’s Ahab was a real king, and a strong one. The writers of Kings knew it. They simply cared more about what he did to Naboth than about how many chariots he owned.\n\nThat is worth remembering. The Bible is history told by people who thought that how a king treated God and his neighbor was the most important fact about him.\n\n*Grade: Secure. British Museum. Read 1 Kings 21.*", "sources": [{"id": "kurkh-monolith", "label": "The Kurkh Monolith · Ahab at Qarqar, 853 BC", "citation": "Monolith of Shalmaneser III from Kurkh, Turkey, found by J. E. Taylor in 1861; British Museum. Edited in A. K. Grayson, Assyrian Rulers of the Early First Millennium BC II (858–745 BC), Royal Inscriptions of Mesopotamia, Assyrian Periods 3 (Toronto, 1996).", "trail": "The stone → Grayson 1996 → Kitchen, On the Reliability of the Old Testament (2003), ch. 2.", "note": "Shalmaneser lists “Ahab the Israelite” with 2,000 chariots and 10,000 soldiers. Some think the scribe miscopied the chariots (perhaps 200); either way Ahab’s force ranks among the largest. The Bible does not mention Qarqar; Assyria claimed a victory, but it did not advance for years.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 7, "title": "The wall carving", "text": "In 701 BC the Assyrian king Sennacherib invaded Judah. He went home and built a palace at Nineveh, and gave one whole room to pictures of a single victory: the taking of Lachish, Judah’s second city.\n\nLayard found the room in 1847.[^lachish-reliefs] The stone panels are now in London and run for eighteen meters. You can see the siege ramps, the battering rams, the archers behind their shields, the defenders throwing torches from the towers. Families walk out with their goods on carts. The king sits on a throne and watches.\n\nAt Lachish itself the siege ramp is still there. Hundreds of arrowheads lay in the slope.\n\nAsk why Sennacherib chose Lachish for his wall. A king shows his best victory. The capital was Jerusalem, and he did not take it.\n\n*Grade: Secure. Read 2 Kings 18:13–17.*", "sources": [{"id": "lachish-reliefs", "label": "The Lachish reliefs · Sennacherib’s showpiece", "citation": "Stone panels from Room XXXVI of the Southwest Palace, Nineveh, excavated by Layard 1847–51; British Museum. David Ussishkin, The Conquest of Lachish by Sennacherib (Tel Aviv University, 1982).", "trail": "The reliefs → Layard → Ussishkin 1982, with the excavated siege ramp at Lachish.", "note": "The Assyrian siege ramp at Lachish, the only one of its kind excavated, still lies against the city’s south-west corner, with a Judahite counter-ramp inside. Arrowheads, sling stones and the remains of the burned gate match the carving closely.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 8, "title": "The six-sided boast", "text": "Sennacherib also wrote the story down, on six-sided blocks of clay that were buried in the foundations of his buildings. Three survive. The best known was found at Nineveh in 1830.\n\nHe says he captured forty-six walled towns of Judah. He says he shut up Hezekiah in Jerusalem “like a bird in a cage.”[^sennacherib-prism] He says Hezekiah sent him thirty talents of gold. The Bible gives the same figure for the gold.\n\nThen the account simply moves on. He does not say he took the city. He does not say why he left.\n\nThe Bible says that in the night his army was struck down, and that he went home and was later murdered by his own sons. Babylonian records confirm the murder. A Greek historian heard in Egypt that this army was ruined in a single night.\n\n*Grade: Secure. Read 2 Kings 19:32–37.*", "sources": [{"id": "sennacherib-prism", "label": "Sennacherib’s prisms · Hezekiah “like a bird in a cage”", "citation": "Taylor Prism, British Museum; Oriental Institute Prism, Chicago; Jerusalem Prism, Israel Museum. Daniel David Luckenbill, The Annals of Sennacherib (Oriental Institute Publications 2, Chicago, 1924); A. Kirk Grayson and Jamie Novotny, Royal Inscriptions of the Neo-Assyrian Period 3/1 (2012).", "trail": "Prisms from Nineveh → Luckenbill 1924 → Grayson and Novotny 2012; on the murder, Simo Parpola, “The Murderer of Sennacherib,” in Death in Mesopotamia (1980); Herodotus, Histories 2.141.", "note": "Sennacherib claims 46 towns and 30 talents of gold, the same figure as 2 Kings 18:14 (the silver differs, 800 talents to 300). He never claims Jerusalem. Herodotus heard in Egypt that mice gnawed the Assyrians’ bowstrings in one night; 2 Kings 19:35 says the angel of the LORD struck the camp. Babylonian Chronicle 1 and Esarhaddon’s own inscription confirm his murder by a son (2 Kings 19:37).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 9, "title": "Pick against pick", "text": "Jerusalem’s water came from a spring outside the wall. Before the Assyrians arrived, Hezekiah had a tunnel cut through the rock under the city to bring the water inside. Two teams started at opposite ends, 533 meters apart, and dug toward each other in the dark.\n\nIn 1880 a boy wading in the tunnel saw writing on the wall. Six lines of Hebrew describe the day the teams met. While there was still rock between them, each could hear the other calling. Then the picks struck, “pick against pick,” and the water ran.\n\nThe workmen do not name the king. The Bible does. Tests on the tunnel’s plaster date it to about 700 BC.[^siloam-tunnel]\n\nYou can still walk it. The water comes up to your knees.\n\n*Grade: Secure. The inscription is in Istanbul. Read 2 Kings 20:20 and 2 Chronicles 32:30.*", "sources": [{"id": "siloam-tunnel", "label": "The Siloam Tunnel and its inscription", "citation": "Inscription found in 1880; Istanbul Archaeology Museums. Amos Frumkin, Aryeh Shimron and Jeff Rosenbaum, “Radiometric dating of the Siloam Tunnel, Jerusalem,” Nature 425 (2003): 169–171.", "trail": "The tunnel → the inscription (Conrad Schick, Archibald Sayce, 1880–81) → Frumkin et al. 2003.", "note": "Radiocarbon from plant matter in the plaster and uranium-thorium dates from cave deposits place the tunnel about 700 BC, Hezekiah’s time (2 Kings 20:20; 2 Chronicles 32:30). A few scholars have proposed an earlier start; the inscription’s letter forms also fit about 700.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 10, "title": "A king’s seal", "text": "A letter in ancient Judah was rolled, tied with string and closed with a lump of clay. The sender pressed his seal into the clay. The lump is called a bulla.\n\nIn 2009, in soil sieved from a trash layer south of the Temple Mount, Eilat Mazar’s team found a bulla one centimeter wide. In 2015 it was read: “Belonging to Hezekiah, son of Ahaz, king of Judah.”[^hezekiah-bulla]\n\nIt is the first seal of a king of Judah to be found by archaeologists in the ground.\n\nThree meters away was another, with a piece missing. It reads “Belonging to Isaiah,” and then three letters. With one more letter they would spell “prophet.” Without it they could be a family name. The break is exactly where the letter would be.\n\nThe first is certain. The second is not, and an honest card says so.\n\n*Grades: Secure and Debated. Read Isaiah 37.*", "sources": [{"id": "hezekiah-bulla", "label": "The Hezekiah and “Isaiah” bullae", "citation": "Ophel excavations directed by Eilat Mazar; the Hezekiah bulla published in 2015; Eilat Mazar, “Is This the Prophet Isaiah’s Signature?” Biblical Archaeology Review 44:2 (2018).", "trail": "Sifted soil from a refuse layer (2009) → reading by the excavation team → Mazar 2015 and 2018.", "note": "The Hezekiah bulla’s reading is not in doubt; it carries a winged sun, a royal emblem of Judah. The “Isaiah” bulla breaks after the letters nby, so the word may be “prophet” (with a missing aleph) or a personal or family name. Christopher Rollston and others regard “prophet” as possible but unproven.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 11, "title": "Silver the size of a finger", "text": "In 1979 Gabriel Barkay was digging burial caves beside the Hinnom Valley in Jerusalem. He set a thirteen-year-old helper to clean a corner. The boy got bored and hit the floor with a hammer. It gave way. Underneath was a chamber the tomb-robbers had never found.\n\nAmong a thousand objects were two tiny rolls of silver. It took three years to unroll them without breaking them. Scratched inside, in the old Hebrew letters, were words you may know: *The LORD bless you and keep you. The LORD make his face shine upon you.*\n\nThey were made about 600 BC, before Jerusalem fell. They are the oldest words of the Bible that anyone has found, four hundred years older than the Dead Sea Scrolls.[^ketef-hinnom]\n\nSomeone wore them. Someone wanted that blessing close.\n\n*Grade: Secure. Israel Museum. Read Numbers 6:22–27.*", "sources": [{"id": "ketef-hinnom", "label": "Ketef Hinnom · the silver scrolls", "citation": "Excavated by Gabriel Barkay, 1979; Israel Museum. Gabriel Barkay, Marilyn J. Lundberg, Andrew G. Vaughn and Bruce Zuckerman, “The Amulets from Ketef Hinnom: A New Edition and Evaluation,” Bulletin of the American Schools of Oriental Research 334 (2004): 41–71.", "trail": "Cave 25 at Ketef Hinnom → first edition by Barkay (1992) → the new imaging and edition of 2004.", "note": "The 2004 edition, using new imaging, confirms a late 7th- or early 6th-century date and reads a form of Numbers 6:24–26. A few scholars had argued for a later date; the new edition answers them on letter forms and archaeology.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 12, "title": "Letters from the gate", "text": "In 1935, in the burnt ruins of a guardroom in the gate of Lachish, excavators found twenty-one pieces of broken pottery with writing in ink. They are letters from an officer at an outpost to his commander in the city, written as the army of Babylon closed in.\n\nOne of them says, more or less: we are watching for the signal fires of Lachish, as you ordered, for we cannot see Azekah.[^lachish-letters]\n\nJeremiah 34:7 says that near the end only two fortified towns of Judah were left besides Jerusalem: Lachish and Azekah.\n\nThe officer could no longer see Azekah’s fire. It is hard to read that line without knowing what it probably meant.\n\n*Grade: Secure. Read Jeremiah 34:6–7.*", "sources": [{"id": "lachish-letters", "label": "The Lachish letters · “we cannot see Azekah”", "citation": "Ink-written potsherds (ostraca) from the gate of Lachish, found by J. L. Starkey in 1935 (more in 1938). Harry Torczyner, Lachish I: The Lachish Letters (Oxford, 1938). The letters are divided between the British Museum and the Israel Museum.", "trail": "The ostraca → Torczyner 1938 → Dennis Pardee in The Context of Scripture, vol. 3 (2002).", "note": "Letter 4 says the writer is watching for the signals of Lachish, “for we cannot see Azekah.” Some read this as meaning Azekah had already fallen (Jeremiah 34:7); others think the outpost simply could not see it from where it stood. Either way the letters come from the last weeks before Babylon’s conquest.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 13, "title": "The second of Adar", "text": "The Babylonians kept a plain record of each year: where the king marched and what he took. One clay tablet covers the years 605 to 594 BC. It lay unread in the British Museum for sixty years and was published in 1956.\n\nFor the king’s seventh year it says that he marched west, camped against “the city of Judah,” and on the second day of the month Adar took the city and captured its king. He set up a king of his own choosing and carried heavy tribute to Babylon.\n\nThe second of Adar in that year was 16 March 597 BC.[^babylonian-chronicle]\n\nThe tablet does not name the kings. The Bible does: Jehoiachin was taken, and Zedekiah was put in his place. The two accounts fit like two halves of a broken dish.\n\n*Grade: Secure. Read 2 Kings 24:10–17.*", "sources": [{"id": "babylonian-chronicle", "label": "The Babylonian Chronicle · Jerusalem taken on 2 Adar 597 BC", "citation": "Chronicle 5 (the “Jerusalem Chronicle”), British Museum 21946. D. J. Wiseman, Chronicles of Chaldaean Kings (626–556 B.C.) in the British Museum (London, 1956); A. K. Grayson, Assyrian and Babylonian Chronicles (Locust Valley, 1975).", "trail": "The tablet → Wiseman 1956 → Grayson 1975 → Jean-Jacques Glassner, Mesopotamian Chronicles (Society of Biblical Literature, 2004).", "note": "It records Carchemish (605 BC, Jeremiah 46:2) and the capture of “the city of Judah” on 2 Adar of Nebuchadnezzar’s seventh year: 15/16 March 597 BC. The chronicles for 594–557 BC are missing, which is why 587 or 586 for Jerusalem’s fall is still argued.", "url": "https://www.livius.org/sources/content/mesopotamian-chronicles-content/abc-5-jerusalem-chronicle/", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 14, "title": "Oil for a king", "text": "What happened to Jehoiachin? The Bible says he lived in Babylon as a prisoner for thirty-seven years and was then given a seat at the king’s table.\n\nGerman excavators at Babylon found a storeroom near the great blue Ishtar Gate. In it were tablets listing the oil given out to foreigners kept at court. Among sailors from Tyre and craftsmen from Egypt is this entry: oil for “Jehoiachin, king of the land of Judah,” and for his five sons.[^jehoiachin-rations]\n\nHe is a captive, and the clerk still writes “king.”\n\nThe tablets are in Berlin, a short walk from the rebuilt gate he would have passed under.\n\n*Grade: Secure. Read 2 Kings 25:27–30.*", "sources": [{"id": "jehoiachin-rations", "label": "Jehoiachin’s rations · the king in Babylon", "citation": "Clay tablets from the Southern Palace of Babylon, excavated by Robert Koldewey (1899–1917); Vorderasiatisches Museum, Berlin. Ernst F. Weidner, “Jojachin, König von Juda, in babylonischen Keilschrifttexten,” in Mélanges syriens offerts à M. René Dussaud, vol. 2 (Paris, 1939).", "trail": "The tablets → Weidner 1939 → William F. Albright’s English discussion (Biblical Archaeologist, 1942).", "note": "Dated 592 BC, they list oil for “Ya’ukin, king of the land of Yahudu” and his five sons, among workers and captives from Tyre, Egypt, Ionia and elsewhere. 2 Kings 25:27–30 says he was later released and fed at the king’s table.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 15, "title": "The barrel of clay", "text": "In 539 BC Cyrus of Persia took Babylon. Soon after, a text was written on a clay barrel a little smaller than a football and buried in a temple wall. It was found in 1879.\n\nCyrus says that Babylon’s god chose him, that he entered the city in peace, and that he sent back to their temples the gods that Babylon had carried off, and gathered their peoples and returned them to their homes.\n\nThe book of Ezra says Cyrus let the Jews go home and rebuild their temple.\n\nNow be careful. The cylinder does not mention the Jews, or Judah, or Jerusalem. The places it names are in Iraq and Iran. What it shows is the policy.[^cyrus-cylinder] Ezra describes that same policy applied to one more people.\n\nIt fits the Bible. That is a smaller claim than “it proves the Bible,” and it is the true one.\n\n*Grade: Secure, for the policy. British Museum. Read Ezra 1:1–4.*", "sources": [{"id": "cyrus-cylinder", "label": "The Cyrus Cylinder · the policy of return", "citation": "Clay cylinder, Babylon, after 539 BC; British Museum, 1880,0617.1941. Found by Hormuzd Rassam in 1879. Irving Finkel (ed.), The Cyrus Cylinder: The King of Persia’s Proclamation from Ancient Babylon (I. B. Tauris, 2013).", "trail": "The cylinder → Rawlinson’s first translation (1880) → Finkel 2013, with the fragments of a second copy identified in 2010.", "note": "Cyrus says he returned gods and peoples to their homes. It names places in Mesopotamia and western Iran, not Judah. It shows a policy; Ezra 1 and 6 record a decree for Jerusalem. Some historians think Cyrus’s generosity was more limited than his propaganda claims; Ezra’s decree fits the way Persian kings dealt with local temples.", "url": "https://www.britishmuseum.org/collection/object/W_1880-0617-1941", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}]}, {"number": 16, "title": "The king nobody believed in", "text": "The book of Daniel says that on the night Babylon fell its king was Belshazzar. The Greek historians had never heard of him. They said the last king was Nabonidus. For a long time that looked like a plain mistake in Daniel.\n\nIn 1854 clay cylinders were dug from the corners of the temple tower at Ur. On them Nabonidus prays for himself and for “Belshazzar, my eldest son.”[^nabonidus-belshazzar] Other tablets explain that Nabonidus spent ten years away in Arabia and left his son to rule in Babylon.\n\nSo there were two kings, father and son. That explains a detail in Daniel 5 which nobody had understood. Belshazzar offers to make Daniel the *third* ruler in the kingdom. He could not offer second. He was second.\n\n*Grade: Secure. Read Daniel 5.*", "sources": [{"id": "nabonidus-belshazzar", "label": "Nabonidus and Belshazzar · the second ruler", "citation": "Nabonidus Cylinders from Ur, found by J. E. Taylor in 1854 (one in the British Museum); the Nabonidus Chronicle (Chronicle 7, British Museum 35382); the Verse Account of Nabonidus (British Museum 38299). Raymond P. Dougherty, Nabonidus and Belshazzar (Yale, 1929).", "trail": "The cylinders and chronicle → Dougherty 1929 → Alan Millard, “Daniel and Belshazzar in History,” Biblical Archaeology Review 11:3 (1985).", "note": "The cylinders pray for “Belshazzar, my eldest son.” The chronicle says that for years the king stayed at Tema in Arabia while the crown prince was in Babylon; the Verse Account says he “entrusted the kingship” to him. Daniel 5:29 has Belshazzar make Daniel “third ruler.” Daniel calls Nebuchadnezzar his “father,” a common way of naming a royal predecessor.", "url": "https://www.livius.org/sources/content/mesopotamian-chronicles-content/abc-7-nabonidus-chronicle/", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 17, "title": "Jars in a cave", "text": "In 1947 a shepherd near the Dead Sea threw a stone into a cave and heard pottery break. Inside were tall jars, and in the jars were scrolls.\n\nOver nine years, eleven caves gave up the remains of more than nine hundred manuscripts.[^dead-sea-scrolls] About two hundred and thirty are books of the Bible. They were copied between about 250 BC and AD 68.\n\nOne is a complete scroll of Isaiah, seven meters long, copied about 125 BC. Before 1947 the oldest complete Hebrew copy of Isaiah was from about AD 1000. When scholars laid the two side by side, eleven centuries apart, they were reading the same book.[^scribes-counted] The differences are mostly in spelling.\n\nColumn 44 holds Isaiah 53, about a servant who is pierced for the sins of others. It was written out more than a hundred years before Jesus was born.\n\n*Grade: Secure. Israel Museum. Read Isaiah 52:13–53:12.*", "sources": [{"id": "dead-sea-scrolls", "label": "The Dead Sea Scrolls", "citation": "Eleven caves near Qumran, 1947–1956; Roland de Vaux’s excavation of the settlement, Archaeology and the Dead Sea Scrolls (Schweich Lectures 1959; Oxford, 1973). James VanderKam and Peter Flint, The Meaning of the Dead Sea Scrolls (HarperSanFrancisco, 2002). The Great Isaiah Scroll, 1QIsaᵃ, is in the Shrine of the Book, Israel Museum.", "trail": "The caves → de Vaux → the official edition, Discoveries in the Judaean Desert (Oxford, 1955–2011) → VanderKam and Flint.", "note": "Most scholars link the scrolls with the Essenes described by Pliny the Elder (Natural History 5.73) and Josephus (Jewish War 2.119–161); Norman Golb argued they came from Jerusalem libraries. The Isaiah scroll is about a thousand years older than the Leningrad Codex (AD 1008) and agrees with it closely. Some books, such as Jeremiah, also circulated in a shorter edition close to the Septuagint.", "url": "http://dss.collections.imj.org.il/isaiah", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}, {"id": "scribes-counted", "label": "Scribes who counted letters", "citation": "Babylonian Talmud, Qiddushin 30a: the early scribes were called soferim because they counted the letters of the Torah. Ernst Würthwein, The Text of the Old Testament (3rd ed., Eerdmans, 2014); Emanuel Tov, Textual Criticism of the Hebrew Bible (3rd ed., Fortress, 2012).", "trail": "The Talmud and the Masoretic notes → Würthwein → Tov.", "note": "The letter and word counts are best documented in the Masoretes’ work of AD 600–1000, who marked middle letters and verses in the margins. Earlier scribes were careful too, and the Dead Sea Scrolls show both carefully copied texts and freer ones.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 18, "title": "A people called Israel", "text": "Now go back six hundred years, to a period where the evidence is thinner.\n\nIn 1896 Flinders Petrie found a granite slab three meters tall in the ruins of a temple at Thebes. Pharaoh Merneptah had it carved about 1208 BC to celebrate his victories. Near the end is a list of defeated enemies in Canaan, and one line says that Israel is laid waste and its seed is no more.\n\nEgyptian writing adds a small sign after a name to show what kind of thing it is. The other names in the list have the sign for a city. Israel has the sign for a people.[^merneptah-stele]\n\nSo by 1208 BC there was a people called Israel living in Canaan, and Pharaoh thought them worth a boast. He was wrong about their seed.\n\n*Grade: Secure. Cairo. Read Judges 2:6–15.*", "sources": [{"id": "merneptah-stele", "label": "The Merneptah Stele · “Israel” in Canaan, about 1208 BC", "citation": "Victory stele of Merneptah, granite, from his mortuary temple at Thebes; Egyptian Museum, Cairo, JE 31408. Found by W. M. Flinders Petrie in 1896; Six Temples at Thebes (London, 1897). English translation by James K. Hoffmeier in W. W. Hallo (ed.), The Context of Scripture, vol. 2 (Brill, 2000), no. 2.6.", "trail": "The stone → Petrie 1897 (Wilhelm Spiegelberg read the name) → Hoffmeier in The Context of Scripture.", "note": "Ashkelon, Gezer and Yanoam carry the sign for a foreign city-state; Israel carries the sign for a people. Scholars agree it names Israel; they debate what it implies, from a group recently settled in the hills to a people long in the land. A pedestal fragment in Berlin (ÄM 21687) may name Israel two centuries earlier; Manfred Görg proposed this in 2001, and the reading is still debated.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 19, "title": "The fallen wall", "text": "Jericho is one of the oldest towns on earth. Its mound has been dug four times, and the diggers agree about what they found: a walled city, a brick wall fallen outward down the slope, a fierce fire, and rows of jars still full of burnt grain.\n\nFull jars mean two things. The siege was short, or the grain would have been eaten. And the city was not looted, because grain was money. Both fit the book of Joshua.\n\nThey do not agree about the date. One excavator said about 1400 BC, which would suit Joshua. A later one said about 1550 BC, long before him, and tests on the grain support her.[^jericho-dates] A third scholar has argued for 1400 again from the pottery.\n\nSo here is a destruction that looks like the one in the Bible, at a date most experts think is too early. That is where the question stands.\n\n*Grade: Debated. Read Joshua 6.*", "sources": [{"id": "jericho-dates", "label": "Jericho · the date of the fallen wall", "citation": "John Garstang (1930–36); Kathleen Kenyon, Digging Up Jericho (London, 1957); Bryant G. Wood, “Did the Israelites Conquer Jericho? A New Look at the Archaeological Evidence,” Biblical Archaeology Review 16:2 (1990); Hendrik J. Bruins and Johannes van der Plicht, “Tell es-Sultan (Jericho): Radiocarbon Results of Short-Lived Cereal and Multiyear Charcoal Samples from the End of the Middle Bronze Age,” Radiocarbon 37:2 (1995): 213–220.", "trail": "Ernst Sellin and Carl Watzinger (1907–09) → Garstang → Kenyon → Wood → Bruins and van der Plicht; the Italian-Palestinian excavations since 1997.", "note": "Garstang dated the burned city to about 1400 BC; Kenyon to about 1550, by the absence of imported Cypriot pottery. Wood re-dated the local pottery to about 1400. The radiocarbon dates on the burned grain came out near 1550 BC, supporting Kenyon. The evidence fits Joshua 6 in kind; the date is the open question.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 20, "title": "A town with two gates", "text": "The Bible sets David’s fight with Goliath in the Valley of Elah. On a hill above that valley is a ruin called Khirbet Qeiyafa.\n\nBetween 2007 and 2013 Yosef Garfinkel dug there and found a walled town that was lived in for only a few decades. Burnt olive pits date it to about 1000 BC, the time of Saul and David.[^qeiyafa-fortress] It has a wall of huge stones, houses built against the wall in the manner of Judah, no pig bones, and two gates. Towns of that size had one. A town named in the Goliath story is called Shaaraim, which means “two gates.”\n\nIt does not have David’s name on it. What it shows is that someone in Judah, in David’s day, could plan and build a fortress. That takes a king, or something close to one.\n\n*Grade: Strong. Read 1 Samuel 17:1–3, 52.*", "sources": [{"id": "qeiyafa-fortress", "label": "Khirbet Qeiyafa · a fortress in David’s day", "citation": "Yosef Garfinkel and Saar Ganor, Khirbet Qeiyafa, vol. 1: Excavation Report 2007–2008 (Israel Exploration Society, 2009); Yosef Garfinkel, Igor Kreimerman and Peter Zilberg, Debating Khirbet Qeiyafa: A Fortified City in Judah from the Time of King David (Israel Exploration Society, 2016).", "trail": "Excavation 2007–2013 → radiocarbon dates on olive pits → the reports above.", "note": "The excavators read a Judahite town of about 1000 BC; others propose a Saulide, Canaanite or Philistine-period site. Shaaraim (“two gates”, 1 Samuel 17:52) is their identification, debated by Nadav Na’aman and others. The ink ostracon found there in 2008 is early Hebrew or Canaanite writing; its translation is uncertain.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 21, "title": "The painted caravan", "text": "Go back further still. In a rock tomb at Beni Hasan in Egypt, painted about 1890 BC, a line of visitors walks along the wall. There are thirty-seven of them, led by a man the caption calls Abisha, ruler of a foreign land.[^beni-hasan] The men wear kilts in bright stripes. The women wear patterned dresses and boots. There are donkeys, children, a man playing a lyre, and bows.\n\nThey are people from Canaan, come down to Egypt to trade.\n\nThis is not Abraham’s family or Jacob’s. But it was painted in their time, and it shows what they looked like, how they traveled and how the Egyptians received them.\n\nOther tombs, four centuries later, show foreign captives making mud bricks while overseers stand by with rods. Egyptian letters complain of brick quotas and of having no straw.[^brick-quotas]\n\n*Grade: Secure, as background. Read Genesis 46:28–34 and Exodus 5:6–14.*", "sources": [{"id": "beni-hasan", "label": "The Beni Hasan painting · visitors from Canaan, about 1890 BC", "citation": "Tomb of Khnumhotep II (tomb 3), Beni Hasan, Egypt. Percy E. Newberry, Beni Hasan, part I (London, 1893).", "trail": "The tomb painting → Newberry 1893 → Hoffmeier, Israel in Egypt (1997).", "note": "The caption counts 37 ‘Aamu (Asiatics) led by Abisha, “ruler of a foreign land” (heqa khasut, the phrase that later gives “Hyksos”). The bright woven cloth recalls Joseph’s robe, though the Hebrew of Genesis 37:3 is uncertain.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "brick-quotas", "label": "Bricks and straw · the Egyptian records", "citation": "Tomb of Rekhmire (TT 100), Thebes, about 1450 BC: foreign workers making bricks; the Louvre Leather Roll (time of Ramesses II): brick quotas for work gangs; Papyrus Anastasi texts on brick-making. Collected in Kitchen, On the Reliability of the Old Testament (2003), ch. 6.", "trail": "Paintings and papyri → Kitchen 2003; Hoffmeier, Israel in Egypt (1997).", "note": "The records show quotas, foreign labor and straw in bricks, the conditions of Exodus 5. They do not name Israel; they show the writer of Exodus knew how Egypt worked.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 22, "title": "The town in the Delta", "text": "Where the Bible puts Israel in Egypt, in the eastern Delta, lies a buried town called Avaris.[^avaris-dab-a] For about four hundred years it was full of people from Syria and Canaan.\n\nAn early house there is built to a Syrian plan. Over it someone built an Egyptian mansion with a garden of tombs. In one tomb lay the smashed statue of a foreign official, larger than life, with traces of paint. The tomb had been emptied.\n\nSome researchers see Joseph here, and then, in later layers, slavery, plague and a sudden departure, in the Bible’s own order. It is a striking pattern.\n\nMost Egyptologists do not accept it.[^exodus-dates] The excavator thinks these people were Canaanite townsmen who later ruled as the Hyksos kings. No inscription names Israel. And the dates only match if Egypt’s time line is moved by two centuries.\n\nOther Christian scholars place the Exodus later and read Avaris differently. Everyone agrees on this much: people like Jacob’s family lived exactly here.\n\n*Grade: Secure for the town; Debated for the pattern. Read Genesis 47:1–12.*", "sources": [{"id": "avaris-dab-a", "label": "Avaris (Tell el-Dab‘a) · people from Canaan in the Delta", "citation": "Manfred Bietak, Austrian Archaeological Institute excavations from 1966; Avaris: The Capital of the Hyksos. Recent Excavations at Tell el-Dab‘a (British Museum Press, 1996).", "trail": "Excavation reports (Tell el-Dab‘a series) → Bietak 1996 → James K. Hoffmeier, Israel in Egypt (Oxford, 1997).", "note": "Houses of Syrian plan, burials with donkeys and bronze weapons, and Canaanite pottery fill the town from about 1800 BC. The name Hyksos comes from Egyptian heqa khasut, “rulers of foreign lands.” Bietak reads the people as Canaanites who became the Hyksos dynasty. David Rohl and the film Patterns of Evidence read the same layers as Joseph’s family and Israel; that requires lowering Egypt’s dates by about two centuries, which most Egyptologists reject.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "exodus-dates", "label": "The date of the Exodus · 1446 BC or about 1260 BC", "citation": "Early date: 1 Kings 6:1; Judges 11:26; Bryant G. Wood, “The Rise and Fall of the 13th-Century Exodus-Conquest Theory,” Journal of the Evangelical Theological Society 48:3 (2005): 475–489; Eugene H. Merrill, Kingdom of Priests (2nd ed., Baker, 2008). Late date: Exodus 1:11; James K. Hoffmeier, Israel in Egypt (Oxford, 1997); Kitchen, On the Reliability of the Old Testament (2003), ch. 6.", "trail": "The biblical figures → the excavations at Qantir (Pi-Ramesse) by Edgar Pusch and Manfred Bietak → the two schools above.", "note": "Early-date scholars read the 480 years literally and note that “Rameses” can be a later name for the place, as Genesis 47:11 uses it for Joseph’s day. Late-date scholars read 480 as twelve generations of forty years and point to Pi-Ramesse, the Delta capital built by Ramesses II. A third view moves Egypt’s whole chronology; most Egyptologists reject it. Both main views take the Exodus as history.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 23, "title": "Things not found, and things not real", "text": "Not everything you hear is true.\n\nNo one has found chariot wheels in the Red Sea. No one has found Noah’s Ark. A lead “curse tablet” announced from Mount Ebal in 2022 has no writing that other experts can see.[^forgeries-care] Several famous objects bought from dealers have turned out to be forged.\n\nA Christian has more reason than anyone to be careful about this. If you tell a friend something false in defense of the Bible and he looks it up, he will not believe the next true thing you say.\n\nSome things have not been found and may never be. There is no Egyptian record of Moses. Pharaohs did not carve their defeats, and papyrus does not last in wet ground. But be honest: an explanation for silence is not the same as evidence.\n\nThe Hittites, Sargon and Belshazzar were all missing once. They were found. Not everything will be.", "sources": [{"id": "forgeries-care", "label": "Fakes and overclaims · how to check", "citation": "Museum of the Bible’s Dead Sea Scroll fragments: Colette Loll, Art Fraud Insights report (March 2020), finding all sixteen to be modern forgeries. Mount Ebal tablet: Scott Stripling et al., Heritage Science 11 (2023), with responses by Aren Maeir, Christopher Rollston and others. Chariot-wheel claims: Ron Wyatt, never published in a peer-reviewed form.", "trail": "Reports and responses as above.", "note": "The test is provenance (where it was found and by whom), publication (can others examine it?) and agreement among specialists. The Hittites (Hugo Winckler at Boğazköy, 1906), Sargon II (Botta at Khorsabad, 1843; Isaiah 20:1) and Belshazzar were once known only from the Bible; they are now well documented.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 24, "title": "What it adds up to", "text": "Put the twenty finds in a row.\n\nFrom about 850 BC onward, the Bible’s kings, wars and exiles are confirmed again and again, often by the records of Israel’s enemies. Before that, back to about 1200 BC, the outline is there: Israel in the land, a house of David, fortified towns. Earlier still, the Bible’s world is true to its time, but nobody’s name is on anything.\n\nThe words themselves were copied with great care. We can check them across a thousand years.\n\nNone of this proves that God spoke to Moses or Isaiah. A spade cannot dig that up. What it shows is that the book which says so is about real places and real people, and was written by men who knew them.\n\nThat is a reason to listen to what else it says."}], "source": "Foundation-Claude/old-testament/books/OT-A-archaeology-long.md", "sha256": "5391f344d0755dbf8a1c40dfed6ff3c30262185fe70b56697ffb8c7389f80f25"}}}, {"id": "old-h", "hall": "ot", "subject": "History", "editions": {"short": {"title": "The Long Road", "subtitle": "The Old Testament’s story in twelve steps", "blurb": "From one man in a tent to a nation coming home. Twelve steps, two thousand years, and a promise that was kept the whole way.", "pages": [{"number": 1, "title": "The road", "text": "The land of the Bible is small. You could drive across it in an afternoon.\n\nBut it sat between the biggest kingdoms in the world. Egypt was on one side. Assyria and Babylon were on the other. The road between them ran right through the middle.\n\nThis book is about what happened on that road, in order."}, {"number": 2, "title": "A man in a tent", "text": "*About 2000 BC.*\n\nGod spoke to a man named Abraham and told him to leave his city. He promised him a land, a great family, and a blessing for the whole world.\n\nAbraham had no land and no children. He went anyway. He lived in tents for the rest of his life.[^mari-archives]\n\n*Read Genesis 12:1–3.*", "sources": [{"id": "mari-archives", "label": "The Mari archives · herders on the edge of the towns", "citation": "About 20,000 cuneiform tablets from the palace of Mari (Tell Hariri, Syria), 18th century BC, excavated by André Parrot from 1933 and published in the series Archives royales de Mari (1950– ).", "trail": "Palace archive → Archives royales de Mari → Daniel E. Fleming, Democracy’s Ancient Ancestors: Mari and Early Collective Governance (Cambridge, 2004) → K. A. Kitchen, On the Reliability of the Old Testament (Eerdmans, 2003), ch. 7.", "note": "The letters describe tribes such as the Binu Yamina (“sons of the south”) who moved flocks between pasture and towns and made covenants with settled kings, sealed by sacrifice. They do not mention Abraham. They show that the life Genesis describes belongs to the early second millennium BC.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 3, "title": "Down to Egypt", "text": "Abraham’s grandson Jacob had twelve sons. One of them, Joseph, was sold as a slave and taken to Egypt.[^slave-price] Years later he was put in charge of the whole country.\n\nWhen a famine came, Joseph’s family moved to Egypt to live. There were about seventy of them.\n\n*Read Genesis 46:1–7.*", "sources": [{"id": "slave-price", "label": "Twenty shekels · the price of a slave over time", "citation": "K. A. Kitchen, “The Patriarchal Age: Myth or History?” Biblical Archaeology Review 21:2 (1995); On the Reliability of the Old Testament (Eerdmans, 2003), ch. 7. Prices from the laws of Hammurabi and from Old Babylonian, Mari, Nuzi, Ugarit, Assyrian and Persian contracts.", "trail": "Contracts and law codes → Kitchen’s table of prices across fifteen centuries.", "note": "Kitchen’s table: about 20 shekels in the 18th–17th centuries BC (Genesis 37:28); about 30 in the 14th–13th (compare Exodus 21:32); 50–60 in Assyria in the 8th (compare 2 Kings 15:20); 90–120 under Persia. Critics answer that prices varied with age, skill and place. The trend is still the point: a writer guessing in a later century would likely have used the price of his own day.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 4, "title": "Slaves", "text": "The family grew into a nation. A new king of Egypt was afraid of them and made them slaves. They made bricks from mud and straw, day after day.[^brick-quotas]\n\nThey cried out to God, and he heard.\n\n*Read Exodus 2:23–25.*", "sources": [{"id": "brick-quotas", "label": "Bricks and straw · the Egyptian records", "citation": "Tomb of Rekhmire (TT 100), Thebes, about 1450 BC: foreign workers making bricks; the Louvre Leather Roll (time of Ramesses II): brick quotas for work gangs; Papyrus Anastasi texts on brick-making. Collected in Kitchen, On the Reliability of the Old Testament (2003), ch. 6.", "trail": "Paintings and papyri → Kitchen 2003; Hoffmeier, Israel in Egypt (1997).", "note": "The records show quotas, foreign labor and straw in bricks, the conditions of Exodus 5. They do not name Israel; they show the writer of Exodus knew how Egypt worked.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 5, "title": "Out", "text": "God sent Moses to the king. After ten plagues the king let the people go.[^exodus-dates] God led them through the sea on dry ground.\n\nThe people of Israel never forgot that night. They still remember it every year at Passover.\n\n*Read Exodus 14:21–22.*", "sources": [{"id": "exodus-dates", "label": "The date of the Exodus · 1446 BC or about 1260 BC", "citation": "Early date: 1 Kings 6:1; Judges 11:26; Bryant G. Wood, “The Rise and Fall of the 13th-Century Exodus-Conquest Theory,” Journal of the Evangelical Theological Society 48:3 (2005): 475–489; Eugene H. Merrill, Kingdom of Priests (2nd ed., Baker, 2008). Late date: Exodus 1:11; James K. Hoffmeier, Israel in Egypt (Oxford, 1997); Kitchen, On the Reliability of the Old Testament (2003), ch. 6.", "trail": "The biblical figures → the excavations at Qantir (Pi-Ramesse) by Edgar Pusch and Manfred Bietak → the two schools above.", "note": "Early-date scholars read the 480 years literally and note that “Rameses” can be a later name for the place, as Genesis 47:11 uses it for Joseph’s day. Late-date scholars read 480 as twelve generations of forty years and point to Pi-Ramesse, the Delta capital built by Ramesses II. A third view moves Egypt’s whole chronology; most Egyptologists reject it. Both main views take the Exodus as history.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 6, "title": "The mountain", "text": "At Mount Sinai God gave Israel his law and made a promise with them.[^treaty-covenant] He would be their God, and they would be his people.\n\nHe also warned them. If they turned to other gods, they would lose the land.\n\n*Read Exodus 19:3–6.*", "sources": [{"id": "treaty-covenant", "label": "Covenant and treaty · the shape of Sinai", "citation": "George E. Mendenhall, Law and Covenant in Israel and the Ancient Near East (Pittsburgh, 1955); Meredith G. Kline, Treaty of the Great King (Eerdmans, 1963); K. A. Kitchen and Paul J. N. Lawrence, Treaty, Law and Covenant in the Ancient Near East, 3 vols. (Harrassowitz, 2012).", "trail": "Hittite treaty tablets from Hattusa (Boğazköy) → Mendenhall 1955 → Kline 1963 → Kitchen and Lawrence 2012.", "note": "Hittite treaties of the 14th–13th centuries BC run: preamble, history, stipulations, deposit and public reading, witnesses, blessings and curses. Exodus 20–24 and Deuteronomy follow that order. Kitchen argues the shape fits the late second millennium better than the Assyrian treaties of the 7th century; scholars who date Deuteronomy late compare it with Esarhaddon’s succession treaties instead.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 7, "title": "Home at last", "text": "Under Joshua the people went into the land God had promised Abraham. For a long time they had no king.[^hill-villages] When enemies came, God sent leaders called judges to rescue them.\n\n*Read Joshua 21:43–45.*", "sources": [{"id": "hill-villages", "label": "The hill-country villages · Iron Age I", "citation": "Israel Finkelstein, The Archaeology of the Israelite Settlement (Israel Exploration Society, 1988); Avraham Faust, Israel’s Ethnogenesis (Equinox, 2006).", "trail": "Surface surveys of the central hills (1970s–80s) → Finkelstein 1988 → Faust 2006.", "note": "Surveys found about 250 new villages in the central hills in the 12th–11th centuries BC: four-room houses, plastered cisterns, terraced fields and almost no pig bones. Most scholars treat them as early Israel. How Israel came to be there is argued: conquest, gradual settlement, or a movement from within Canaan. Joshua and Judges themselves describe a quick campaign followed by a long, incomplete settlement.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 8, "title": "Kings", "text": "*About 1000 BC.*\n\nThe people asked for a king. The second king was David, a shepherd from Bethlehem. He made Jerusalem his city.[^tel-dan-stele] God promised that a king from David’s family would rule for ever.\n\nDavid’s son Solomon built God’s temple there.\n\n*Read 2 Samuel 7:12–13.*", "sources": [{"id": "tel-dan-stele", "label": "The Tel Dan Stele · “House of David”, about 840 BC", "citation": "Avraham Biran and Joseph Naveh, “An Aramaic Stele Fragment from Tel Dan,” Israel Exploration Journal 43 (1993): 81–98; “The Tel Dan Inscription: A New Fragment,” IEJ 45 (1995): 1–18. Israel Museum, Jerusalem.", "trail": "Found by Gila Cook of Biran’s team, July 1993; fragments B1 and B2 in 1994 → Biran and Naveh → George Athas, The Tel Dan Inscription (Sheffield, 2003).", "note": "The phrase bytdwd is read “House of David” by nearly all specialists; a few early alternatives (a place name, “house of the kettle”) have not held. The speaker is most likely Hazael of Damascus, who claims the killings 2 Kings 9 credits to Jehu; perhaps Jehu acted in league with Hazael, or the king took credit. How the fragments join is still discussed.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 9, "title": "Two kingdoms", "text": "After Solomon the kingdom split in two. Israel was in the north. Judah was in the south.\n\nMost of the kings did what was wrong. God sent prophets, like Elijah and Isaiah, to call the people back.\n\n*Read 1 Kings 12:16–17.*"}, {"number": 10, "title": "The north falls", "text": "*722 BC.*\n\nThe army of Assyria came and destroyed the northern kingdom.[^sargon-samaria] Its people were taken far away and never came back.\n\nJudah was almost destroyed too. But King Hezekiah prayed, and God saved Jerusalem.[^sennacherib-prism]\n\n*Read 2 Kings 19:14–19.*", "sources": [{"id": "sargon-samaria", "label": "Sargon II and the fall of Samaria, 722–720 BC", "citation": "Sargon II’s annals at Khorsabad and the Nimrud Prism: 27,290 people deported (another text has 27,280). Babylonian Chronicle 1 says Shalmaneser V “ravaged Samaria.” K. Lawson Younger Jr., “The Deportations of the Israelites,” Journal of Biblical Literature 117 (1998): 201–227.", "trail": "Paul-Émile Botta found Sargon’s palace at Khorsabad in 1843 → the annals → Younger 1998.", "note": "2 Kings 17 credits the siege to Shalmaneser V and the capture to “the king of Assyria.” Sargon claimed the deportations in his own inscriptions. Most historians conclude that Shalmaneser took the city in 722 and Sargon completed the deportations and resettlement by 720.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "sennacherib-prism", "label": "Sennacherib’s prisms · Hezekiah “like a bird in a cage”", "citation": "Taylor Prism, British Museum; Oriental Institute Prism, Chicago; Jerusalem Prism, Israel Museum. Daniel David Luckenbill, The Annals of Sennacherib (Oriental Institute Publications 2, Chicago, 1924); A. Kirk Grayson and Jamie Novotny, Royal Inscriptions of the Neo-Assyrian Period 3/1 (2012).", "trail": "Prisms from Nineveh → Luckenbill 1924 → Grayson and Novotny 2012; on the murder, Simo Parpola, “The Murderer of Sennacherib,” in Death in Mesopotamia (1980); Herodotus, Histories 2.141.", "note": "Sennacherib claims 46 towns and 30 talents of gold, the same figure as 2 Kings 18:14 (the silver differs, 800 talents to 300). He never claims Jerusalem. Herodotus heard in Egypt that mice gnawed the Assyrians’ bowstrings in one night; 2 Kings 19:35 says the angel of the LORD struck the camp. Babylonian Chronicle 1 and Esarhaddon’s own inscription confirm his murder by a son (2 Kings 19:37).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 11, "title": "The south falls", "text": "*586 BC.*\n\nLater the army of Babylon came. This time Jerusalem was burned and the temple was torn down. The people were marched to Babylon.[^babylonian-chronicle]\n\nIt looked like the end. But God had said it would last seventy years, and no longer.\n\n*Read Jeremiah 29:10–11.*", "sources": [{"id": "babylonian-chronicle", "label": "The Babylonian Chronicle · Jerusalem taken on 2 Adar 597 BC", "citation": "Chronicle 5 (the “Jerusalem Chronicle”), British Museum 21946. D. J. Wiseman, Chronicles of Chaldaean Kings (626–556 B.C.) in the British Museum (London, 1956); A. K. Grayson, Assyrian and Babylonian Chronicles (Locust Valley, 1975).", "trail": "The tablet → Wiseman 1956 → Grayson 1975 → Jean-Jacques Glassner, Mesopotamian Chronicles (Society of Biblical Literature, 2004).", "note": "It records Carchemish (605 BC, Jeremiah 46:2) and the capture of “the city of Judah” on 2 Adar of Nebuchadnezzar’s seventh year: 15/16 March 597 BC. The chronicles for 594–557 BC are missing, which is why 587 or 586 for Jerusalem’s fall is still argued.", "url": "https://www.livius.org/sources/content/mesopotamian-chronicles-content/abc-5-jerusalem-chronicle/", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 12, "title": "Coming home", "text": "*538 BC.*\n\nA new king, Cyrus of Persia, let the people go home.[^cyrus-cylinder] They rebuilt the temple. Later Nehemiah rebuilt the city wall.[^elephantine]\n\nThen the prophets stopped speaking. For four hundred years the people waited.\n\n*Read Ezra 1:1–3.*", "sources": [{"id": "cyrus-cylinder", "label": "The Cyrus Cylinder · the policy of return", "citation": "Clay cylinder, Babylon, after 539 BC; British Museum, 1880,0617.1941. Found by Hormuzd Rassam in 1879. Irving Finkel (ed.), The Cyrus Cylinder: The King of Persia’s Proclamation from Ancient Babylon (I. B. Tauris, 2013).", "trail": "The cylinder → Rawlinson’s first translation (1880) → Finkel 2013, with the fragments of a second copy identified in 2010.", "note": "Cyrus says he returned gods and peoples to their homes. It names places in Mesopotamia and western Iran, not Judah. It shows a policy; Ezra 1 and 6 record a decree for Jerusalem. Some historians think Cyrus’s generosity was more limited than his propaganda claims; Ezra’s decree fits the way Persian kings dealt with local temples.", "url": "https://www.britishmuseum.org/collection/object/W_1880-0617-1941", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}, {"id": "elephantine", "label": "The Elephantine papyri · Nehemiah’s neighbors", "citation": "Aramaic papyri from a Jewish garrison at Elephantine, Egypt, 5th century BC. A. E. Cowley, Aramaic Papyri of the Fifth Century B.C. (Oxford, 1923), nos. 30–31; Bezalel Porten, The Elephantine Papyri in English (Brill, 1996).", "trail": "The papyri (Berlin, Brooklyn and Cairo) → Cowley 1923 → Porten 1996.", "note": "A letter of 407 BC to Bagohi, governor of Judah, mentions Johanan the high priest (Nehemiah 12:22) and the sons of Sanballat, governor of Samaria, Nehemiah’s opponent (Nehemiah 2:10). It sets Nehemiah’s people in a real Persian province.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 13, "title": "Still waiting", "text": "The Old Testament ends with promises that had not come true yet. A king from David’s family was coming. He would rule for ever. He would carry the sins of his people.\n\nEveryone was waiting for him.\n\nThen, in Bethlehem, David’s town, a baby was born.\n\n*Read Isaiah 9:6 and Luke 2:10–11.*"}], "source": "Foundation-Claude/old-testament/books/OT-H-history-short.md", "sha256": "b93ee71314db451388cca42f530f59a78a1c25b676dae09c7201708a107d84c3"}, "long": {"title": "Kings and Empires", "subtitle": "The Old Testament’s history, with the world around it", "blurb": "A small people on a strip of land between the two greatest powers on earth. Egypt on one side, Assyria and Babylon on the other, and the main road between them running straight through. This is what happened there, and when.", "pages": [{"number": 1, "title": "The land between", "text": "Look at a map. To the south-west is Egypt, strung along the Nile. To the north-east is Mesopotamia, the land of the Tigris and Euphrates, where Assyria and Babylon rose. Between them is desert, except for one narrow strip of green along the Mediterranean.\n\nThat strip is Canaan. Every army and every caravan going from one great power to the other had to pass through it.\n\nThis is where God put Abraham’s family. It was not a quiet corner. It was the crossroads of the ancient world, and almost everything in the Old Testament’s history happens because someone bigger wanted the road.\n\nKeep that map in your head. The rest of this book is what happened on it."}, {"number": 2, "title": "How we know the dates", "text": "The Bible counts years by kings: “in the fifth year of King Rehoboam.” To turn that into a date we need a fixed point.\n\nThe Assyrians gave us one. They named each year after an official and kept the lists. One list records an eclipse of the sun, which astronomers can date exactly: 15 June 763 BC.[^eponym-eclipse] From that, every Assyrian year can be numbered.\n\nWhen an Assyrian king says he fought Ahab or took tribute from Jehu, we have a date for a king of Israel. From those points the Bible’s own figures carry us backward and forward.\n\nSo dates after about 900 BC are firm, often to the year. Dates before that are estimates, and you will see “about” in front of them.", "sources": [{"id": "eponym-eclipse", "label": "The Assyrian eponym lists · the eclipse of 15 June 763 BC", "citation": "Assyrian Eponym Chronicle, year of Bur-Saggile: a revolt in the city of Assur, and in the month Simanu an eclipse of the sun. Edited in Alan Millard, The Eponyms of the Assyrian Empire 910–612 BC, State Archives of Assyria Studies 2 (Helsinki: Neo-Assyrian Text Corpus Project, 1994).", "trail": "Clay tablets from Nineveh and Assur → Henry Rawlinson linked the entry to the eclipse in 1867 → Millard 1994 → Edwin R. Thiele, The Mysterious Numbers of the Hebrew Kings (3rd ed., Zondervan, 1983).", "note": "Astronomers can compute exactly when and where that eclipse was seen. Counting from it fixes every Assyrian year from 910 to 649 BC, and so the years when Shalmaneser III met Ahab (853) and took Jehu’s tribute (841). Scholars still differ by a year or two for some kings of Israel and Judah, mostly over overlapping reigns (co-regencies) and how each kingdom counted a king’s first year.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 3, "title": "Before Abraham", "text": "By the time of Abraham, historians believe, civilization was already old.\n\nOn the dating most historians use, people in Mesopotamia had been writing on clay for about a thousand years. They had cities with tens of thousands of people, law codes, schools, banks and star charts. They built stepped temple-towers of baked brick. The great pyramids of Egypt are usually dated several centuries before him.\n\nSome Christians read the genealogies in Genesis as a complete count of years, and fit these peoples into a shorter span of time.[^genealogies] Either way, these were the peoples Abraham’s family lived among.\n\nThese peoples told stories of creation and of a great flood.[^atrahasis][^enuma-elish] Their stories have many gods who quarrel, grow tired and send the flood because humans are noisy.\n\nGenesis tells of one God who makes everything by speaking, calls it good, and judges because of real evil. It was written for people who knew the other stories and needed to hear the true one.", "sources": [{"id": "genealogies", "label": "Early dates and the genealogies of Genesis", "citation": "William Henry Green, “Primeval Chronology,” Bibliotheca Sacra 47 (1890): 285–303. For the conventional dates: writing at Uruk about 3200 BC; the Great Pyramid of Khufu about 2560 BC (Ian Shaw, ed., The Oxford History of Ancient Egypt, Oxford, 2000).", "trail": "Genesis 5 and 11 → Green 1890, a Princeton Old Testament scholar who held to inerrancy → present-day young-earth and old-earth discussion.", "note": "Green argued that biblical genealogies can skip generations, as Matthew 1:8 skips three kings between Joram and Uzziah, so they were not written as a clock. Young-earth Christians read Genesis 5 and 11 as complete and so shorten the early dates. The early dates themselves rest on king lists, layers in the ground and radiocarbon, and are more secure after about 2000 BC.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "atrahasis", "label": "Atrahasis and Gilgamesh · the Mesopotamian flood stories", "citation": "Atra-hasis, Old Babylonian copy of the 17th century BC: W. G. Lambert and A. R. Millard, Atra-ḫasīs: The Babylonian Story of the Flood (Oxford, 1969). Gilgamesh, Tablet XI (the “Flood Tablet”), British Museum K.3375, read by George Smith in 1872: A. R. George, The Babylonian Gilgamesh Epic (Oxford, 2003).", "trail": "Clay tablets from Sippar and from Ashurbanipal’s library at Nineveh → Smith 1872; Lambert and Millard 1969 → George 2003.", "note": "In Atrahasis the gods try plague, drought and finally the flood because the noise of the growing human race keeps the god Enlil awake. Genesis shares the outline (a warned man, a boat, birds sent out, a sacrifice) and differs in its theology: one God, judging real wickedness, who then binds himself by covenant. Scholars debate whether the accounts remember a common event or Genesis answers the older stories; this book takes Genesis as the true account.", "url": "https://www.britishmuseum.org/collection/object/W_K-3375", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}, {"id": "enuma-elish", "label": "Enuma Elish and Genesis 1", "citation": "Enuma Elish, the Babylonian creation epic; copies from Ashurbanipal’s library at Nineveh and from Assur and Babylon. First published by George Smith, The Chaldean Account of Genesis (London, 1876). W. G. Lambert, Babylonian Creation Myths (Eisenbrauns, 2013).", "trail": "Tablets → Smith 1876 → Lambert 2013 → Gerhard F. Hasel, “The Polemic Nature of the Genesis Cosmology,” Evangelical Quarterly 46 (1974): 81–102.", "note": "Marduk makes the world from the split body of the goddess Tiamat after a war among the gods; humans are made from a slain god’s blood to do the gods’ work. Genesis 1 shares a word with it (tehom, “the deep,” related to Tiamat) and reads as a deliberate contrast: one God, no battle, the sun and moon as lamps rather than gods, people made in God’s image to rule and to rest. Lambert himself doubted that Genesis borrowed from the Babylonian story.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 4, "title": "Abraham, Isaac and Jacob", "text": "*About 2100 to 1800 BC.*\n\nAbraham came from Ur, a rich city, and was called to leave it.[^ur-woolley] He lived the rest of his life in tents, moving with his flocks between the towns of Canaan. He owned no land there except a burial cave.\n\nThis was a normal way to live at the time. Tablets from the city of Mari describe tribes who moved with their herds on the edges of settled land and made agreements with the towns.[^mari-archives]\n\nTo this man, with no land and no child, God promised a land, a nation and a blessing for every family on earth. The whole Old Testament is the story of that promise being kept, slowly, to people who mostly did not deserve it.\n\n*Read Genesis 12:1–3.*", "sources": [{"id": "ur-woolley", "label": "Ur of the Chaldeans", "citation": "Leonard Woolley, excavations at Tell el-Muqayyar, Iraq, 1922–1934; Ur of the Chaldees (London, 1929). Finds from the Royal Cemetery (about 2600 BC) are in the British Museum and the Penn Museum.", "trail": "Excavation reports → Woolley 1929 → Kitchen, On the Reliability of the Old Testament, ch. 7.", "note": "Genesis 11:31 uses “Chaldeans,” a people known in the region from about 1000 BC, so the name was probably updated for later readers, as we say “Iraq” for ancient Mesopotamia. Most identify Abraham’s Ur with Woolley’s city in the south; a minority, pointing to Haran, look for a northern Ur near Urfa.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "mari-archives", "label": "The Mari archives · herders on the edge of the towns", "citation": "About 20,000 cuneiform tablets from the palace of Mari (Tell Hariri, Syria), 18th century BC, excavated by André Parrot from 1933 and published in the series Archives royales de Mari (1950– ).", "trail": "Palace archive → Archives royales de Mari → Daniel E. Fleming, Democracy’s Ancient Ancestors: Mari and Early Collective Governance (Cambridge, 2004) → K. A. Kitchen, On the Reliability of the Old Testament (Eerdmans, 2003), ch. 7.", "note": "The letters describe tribes such as the Binu Yamina (“sons of the south”) who moved flocks between pasture and towns and made covenants with settled kings, sealed by sacrifice. They do not mention Abraham. They show that the life Genesis describes belongs to the early second millennium BC.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 5, "title": "Into Egypt", "text": "Jacob’s son Joseph was sold by his brothers for twenty shekels of silver, which records from that era suggest was about the going price for a slave.[^slave-price] He rose to rule Egypt under Pharaoh. In a famine his family joined him and settled in Goshen, in the eastern Nile Delta.\n\nEgypt’s own records show that people from Canaan came into the Delta in large numbers in these centuries.[^brooklyn-papyrus] Some came to trade, some as servants, some in famine. They built a town there called Avaris.[^avaris-dab-a] For a time a line of foreign kings, the Hyksos, ruled northern Egypt from it.\n\nAbout 1550 BC a native Egyptian king drove the Hyksos out. A new line of pharaohs began, strong and suspicious of foreigners. The Bible says simply that a king arose who did not know Joseph.\n\n*Read Exodus 1:8–14.*", "sources": [{"id": "slave-price", "label": "Twenty shekels · the price of a slave over time", "citation": "K. A. Kitchen, “The Patriarchal Age: Myth or History?” Biblical Archaeology Review 21:2 (1995); On the Reliability of the Old Testament (Eerdmans, 2003), ch. 7. Prices from the laws of Hammurabi and from Old Babylonian, Mari, Nuzi, Ugarit, Assyrian and Persian contracts.", "trail": "Contracts and law codes → Kitchen’s table of prices across fifteen centuries.", "note": "Kitchen’s table: about 20 shekels in the 18th–17th centuries BC (Genesis 37:28); about 30 in the 14th–13th (compare Exodus 21:32); 50–60 in Assyria in the 8th (compare 2 Kings 15:20); 90–120 under Persia. Critics answer that prices varied with age, skill and place. The trend is still the point: a writer guessing in a later century would likely have used the price of his own day.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "brooklyn-papyrus", "label": "Papyrus Brooklyn 35.1446 · Semitic servants in an Egyptian house", "citation": "Brooklyn Museum 35.1446, about 1740 BC. William C. Hayes, A Papyrus of the Late Middle Kingdom in the Brooklyn Museum (Brooklyn, 1955); W. F. Albright, “Northwest-Semitic Names in a List of Egyptian Slaves from the Eighteenth Century B.C.,” Journal of the American Oriental Society 74 (1954): 222–233.", "trail": "Papyrus → Hayes 1955 and Albright 1954 → Hoffmeier, Israel in Egypt (1997).", "note": "A list of about ninety-five servants in one household in Upper Egypt. Dozens are labeled “Asiatic” and carry Northwest Semitic names; Albright read one as Shiphrah, the name of a Hebrew midwife in Exodus 1:15. It shows Semitic people serving in Egyptian homes in the era of Joseph.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "avaris-dab-a", "label": "Avaris (Tell el-Dab‘a) · people from Canaan in the Delta", "citation": "Manfred Bietak, Austrian Archaeological Institute excavations from 1966; Avaris: The Capital of the Hyksos. Recent Excavations at Tell el-Dab‘a (British Museum Press, 1996).", "trail": "Excavation reports (Tell el-Dab‘a series) → Bietak 1996 → James K. Hoffmeier, Israel in Egypt (Oxford, 1997).", "note": "Houses of Syrian plan, burials with donkeys and bronze weapons, and Canaanite pottery fill the town from about 1800 BC. The name Hyksos comes from Egyptian heqa khasut, “rulers of foreign lands.” Bietak reads the people as Canaanites who became the Hyksos dynasty. David Rohl and the film Patterns of Evidence read the same layers as Joseph’s family and Israel; that requires lowering Egypt’s dates by about two centuries, which most Egyptologists reject.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 6, "title": "Out of Egypt", "text": "The Israelites were made slaves and set to making bricks. God sent Moses. After ten plagues Pharaoh let them go, changed his mind, and lost his army in the sea.\n\nWhen was this? The Bible gives a figure: 480 years before Solomon began the temple, which points to about 1446 BC. It also says the slaves built a city called Rameses, which points to the pharaoh of that name, about 1260 BC. Christians who trust the Bible hold both views, and a few hold a third.[^exodus-dates]\n\nNo Egyptian record of it has been found. That is not surprising. Pharaohs carved their victories on their walls, not their defeats.[^egypt-silence]\n\nWhat Israel remembered is not in doubt. Every later book of the Bible looks back to this: *we were slaves, and the LORD brought us out.*\n\n*Read Exodus 12:40–42 and 1 Kings 6:1.*", "sources": [{"id": "exodus-dates", "label": "The date of the Exodus · 1446 BC or about 1260 BC", "citation": "Early date: 1 Kings 6:1; Judges 11:26; Bryant G. Wood, “The Rise and Fall of the 13th-Century Exodus-Conquest Theory,” Journal of the Evangelical Theological Society 48:3 (2005): 475–489; Eugene H. Merrill, Kingdom of Priests (2nd ed., Baker, 2008). Late date: Exodus 1:11; James K. Hoffmeier, Israel in Egypt (Oxford, 1997); Kitchen, On the Reliability of the Old Testament (2003), ch. 6.", "trail": "The biblical figures → the excavations at Qantir (Pi-Ramesse) by Edgar Pusch and Manfred Bietak → the two schools above.", "note": "Early-date scholars read the 480 years literally and note that “Rameses” can be a later name for the place, as Genesis 47:11 uses it for Joseph’s day. Late-date scholars read 480 as twelve generations of forty years and point to Pi-Ramesse, the Delta capital built by Ramesses II. A third view moves Egypt’s whole chronology; most Egyptologists reject it. Both main views take the Exodus as history.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "egypt-silence", "label": "Why Egypt’s records are silent", "citation": "Kitchen, On the Reliability of the Old Testament (2003), ch. 6; Hoffmeier, Israel in Egypt (1997), ch. 5. On Kadesh: the Poem and the Bulletin of Ramesses II, carved at Karnak, Luxor, the Ramesseum and Abu Simbel; the Egyptian–Hittite peace treaty of about 1259 BC, copies at Karnak and Hattusa.", "trail": "Temple inscriptions and the Hattusa archives → Kitchen; Hoffmeier.", "note": "Almost no papyrus survives from the wet soil of the eastern Delta, where Israel lived, and the royal archives of the period are lost. Pharaohs did carve near-defeats, but as triumphs: Ramesses II portrayed the battle of Kadesh (1274 BC) as his victory, while Hittite records and the later treaty show a stalemate. Silence is expected; it is not evidence either way.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 7, "title": "The covenant at Sinai", "text": "At Mount Sinai God made a covenant with Israel. It has a shape. The great king names himself, tells what he has done for his people, sets out what he requires, calls witnesses, and lists the blessings of loyalty and the curses of rebellion.\n\nKings of that age made treaties with lesser kings in the same shape.[^treaty-covenant][^hammurabi] Israel would have recognized it at once. The difference was who the great king was.\n\nThis covenant explains the rest of the history. When the books of Kings say a ruler “did evil in the sight of the LORD,” they are measuring him against Sinai. When the prophets warn of exile, they are quoting its curses. When exile comes, no one in Israel can say they were not told.\n\n*Read Exodus 19:3–6 and Deuteronomy 28.*", "sources": [{"id": "treaty-covenant", "label": "Covenant and treaty · the shape of Sinai", "citation": "George E. Mendenhall, Law and Covenant in Israel and the Ancient Near East (Pittsburgh, 1955); Meredith G. Kline, Treaty of the Great King (Eerdmans, 1963); K. A. Kitchen and Paul J. N. Lawrence, Treaty, Law and Covenant in the Ancient Near East, 3 vols. (Harrassowitz, 2012).", "trail": "Hittite treaty tablets from Hattusa (Boğazköy) → Mendenhall 1955 → Kline 1963 → Kitchen and Lawrence 2012.", "note": "Hittite treaties of the 14th–13th centuries BC run: preamble, history, stipulations, deposit and public reading, witnesses, blessings and curses. Exodus 20–24 and Deuteronomy follow that order. Kitchen argues the shape fits the late second millennium better than the Assyrian treaties of the 7th century; scholars who date Deuteronomy late compare it with Esarhaddon’s succession treaties instead.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "hammurabi", "label": "The laws of Hammurabi and the Law of Moses", "citation": "Diorite stele of Hammurabi of Babylon (about 1750 BC), found at Susa in 1901–02 by Jacques de Morgan’s expedition and published by Jean-Vincent Scheil (1902); Louvre, Sb 8. Martha T. Roth, Law Collections from Mesopotamia and Asia Minor (2nd ed., Scholars Press, 1997).", "trail": "The stele → Scheil 1902 → Roth 1997 → John H. Walton, Ancient Near Eastern Thought and the Old Testament (2nd ed., Baker, 2018).", "note": "Both collections deal with goring oxen, theft and injury, and both have “eye for eye” (Hammurabi laws 196–200; Exodus 21:23–25). The differences matter. Hammurabi’s penalties depend on class: a commoner’s eye is paid for in silver, a slave’s at half its price. Exodus protects a slave’s body and life (21:20, 26–27), and its laws come as God’s covenant with the whole people, not a king’s decree.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 8, "title": "Into the land", "text": "*About 1400 BC, or about 1220 BC.*\n\nUnder Joshua, Israel crossed the Jordan. The book of Joshua describes fast campaigns in the center, south and north. It names three cities that were burned: Jericho, Ai and Hazor.[^jericho-dates][^hazor-ai] The rest were taken and lived in.\n\nCanaan at this time was a land of small walled cities, each with its own king, all paying tax to Egypt. Letters from these kings to Pharaoh survive.[^amarna-letters] They complain of raiders and beg for soldiers who never come.\n\nBy about 1208 BC a pharaoh could list “Israel” among the peoples of Canaan.[^merneptah-stele] Archaeologists find that soon after, hundreds of small farming villages appeared in the hills, where few had lived before.[^hill-villages]\n\n*Read Joshua 11:16–23.*", "sources": [{"id": "jericho-dates", "label": "Jericho · the date of the fallen wall", "citation": "John Garstang (1930–36); Kathleen Kenyon, Digging Up Jericho (London, 1957); Bryant G. Wood, “Did the Israelites Conquer Jericho? A New Look at the Archaeological Evidence,” Biblical Archaeology Review 16:2 (1990); Hendrik J. Bruins and Johannes van der Plicht, “Tell es-Sultan (Jericho): Radiocarbon Results of Short-Lived Cereal and Multiyear Charcoal Samples from the End of the Middle Bronze Age,” Radiocarbon 37:2 (1995): 213–220.", "trail": "Ernst Sellin and Carl Watzinger (1907–09) → Garstang → Kenyon → Wood → Bruins and van der Plicht; the Italian-Palestinian excavations since 1997.", "note": "Garstang dated the burned city to about 1400 BC; Kenyon to about 1550, by the absence of imported Cypriot pottery. Wood re-dated the local pottery to about 1400. The radiocarbon dates on the burned grain came out near 1550 BC, supporting Kenyon. The evidence fits Joshua 6 in kind; the date is the open question.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "hazor-ai", "label": "Hazor and Ai · burned cities in Joshua", "citation": "Yigael Yadin, Hazor: The Rediscovery of a Great Citadel of the Bible (Random House, 1975); Amnon Ben-Tor, “The Fall of Canaanite Hazor: The ‘Who’ and ‘When’ Questions,” in S. Gitin et al. (eds.), Mediterranean Peoples in Transition (Israel Exploration Society, 1998); Bryant G. Wood, “The Search for Joshua’s Ai,” in R. Hess, G. Klingbeil and P. Ray (eds.), Critical Issues in Early Israelite History (Eisenbrauns, 2008).", "trail": "Hazor excavations (Yadin 1955–58, 1968; Ben-Tor from 1990) → the essays above.", "note": "At Hazor a great fire ended the Canaanite city, with smashed statues of gods and kings. Ben-Tor holds that Israel burned it in the 13th century; early-date scholars point to an earlier destruction (Joshua 11:10–13). The usual site for Ai, et-Tell, was empty in Joshua’s day, so Wood and the Associates for Biblical Research excavated Khirbet el-Maqatir as the better candidate.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "amarna-letters", "label": "The Amarna letters · Canaan’s kings write to Pharaoh", "citation": "About 380 clay tablets from Akhetaten (el-Amarna), Egypt, found in 1887, mid-14th century BC. William L. Moran, The Amarna Letters (Johns Hopkins, 1992). Letters EA 286–290 are from Abdi-Heba, king of Jerusalem.", "trail": "Tablets in Berlin, London and Cairo → J. A. Knudtzon’s numbering (1907–15) → Moran 1992.", "note": "The kings of Canaan’s small walled cities beg Pharaoh for archers and complain of the ‘Apiru (Habiru), raiders and outlaws. Some early-date scholars link the ‘Apiru with Joshua’s Hebrews. Most think the word names a social class rather than a people, though the Hebrews could have been counted among them.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "merneptah-stele", "label": "The Merneptah Stele · “Israel” in Canaan, about 1208 BC", "citation": "Victory stele of Merneptah, granite, from his mortuary temple at Thebes; Egyptian Museum, Cairo, JE 31408. Found by W. M. Flinders Petrie in 1896; Six Temples at Thebes (London, 1897). English translation by James K. Hoffmeier in W. W. Hallo (ed.), The Context of Scripture, vol. 2 (Brill, 2000), no. 2.6.", "trail": "The stone → Petrie 1897 (Wilhelm Spiegelberg read the name) → Hoffmeier in The Context of Scripture.", "note": "Ashkelon, Gezer and Yanoam carry the sign for a foreign city-state; Israel carries the sign for a people. Scholars agree it names Israel; they debate what it implies, from a group recently settled in the hills to a people long in the land. A pedestal fragment in Berlin (ÄM 21687) may name Israel two centuries earlier; Manfred Görg proposed this in 2001, and the reading is still debated.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "hill-villages", "label": "The hill-country villages · Iron Age I", "citation": "Israel Finkelstein, The Archaeology of the Israelite Settlement (Israel Exploration Society, 1988); Avraham Faust, Israel’s Ethnogenesis (Equinox, 2006).", "trail": "Surface surveys of the central hills (1970s–80s) → Finkelstein 1988 → Faust 2006.", "note": "Surveys found about 250 new villages in the central hills in the 12th–11th centuries BC: four-room houses, plastered cisterns, terraced fields and almost no pig bones. Most scholars treat them as early Israel. How Israel came to be there is argued: conquest, gradual settlement, or a movement from within Canaan. Joshua and Judges themselves describe a quick campaign followed by a long, incomplete settlement.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 9, "title": "The judges", "text": "*Until about 1050 BC.*\n\nIsrael had no king and no capital. Twelve tribes farmed the hills, joined by a shared worship centered on the tabernacle at Shiloh. When enemies pressed, God raised up a leader, a judge, for that crisis.\n\nThe book of Judges runs in a circle: Israel turns to other gods, is oppressed, cries out, is rescued, and turns away again. Each turn is worse than the last.\n\nIn these same years a new people landed on the coast. The Philistines came from the Aegean world, across the sea.[^philistines] They had iron, chariots and five strong cities. They pushed inland. Around 1050 BC they defeated Israel, captured the ark, and Shiloh was burned.[^shiloh]\n\n*Read Judges 2:11–19.*", "sources": [{"id": "philistines", "label": "The Philistines · from the Aegean to the coast", "citation": "Reliefs of Ramesses III at Medinet Habu (about 1175 BC) naming the Peleset among the Sea Peoples; excavations at Ashkelon (Lawrence Stager), Ekron (Trude Dothan and Seymour Gitin) and Gath (Aren Maeir); Michal Feldman et al., “Ancient DNA sheds light on the genetic origins of early Iron Age Philistines,” Science Advances 5:7 (2019).", "trail": "Egyptian reliefs → excavation reports → the 2019 DNA study of Ashkelon burials.", "note": "Aegean-style pottery, hearths and a taste for pork mark the early Philistine towns. The DNA study found a European-related ancestry in early Ashkelon burials that soon blended into the local population. Genesis and Exodus already say “Philistines” for earlier coastal peoples; many take this as a later name used for readers, as Amos 9:7 traces them from Caphtor (Crete).", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "shiloh", "label": "Shiloh · the tabernacle town", "citation": "Danish excavations 1926–32; Israel Finkelstein (ed.), Shiloh: The Archaeology of a Biblical Site (Tel Aviv University, 1993); renewed excavation by Scott Stripling for the Associates for Biblical Research from 2017.", "trail": "Excavation reports → Finkelstein 1993 → ongoing excavation.", "note": "A destruction by fire in the 11th century BC fits the loss of the ark in 1 Samuel 4. Jeremiah 7:12–14 and Psalm 78:60 remember Shiloh as the place God abandoned. Where exactly the tabernacle stood on the site is still being studied.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 10, "title": "Saul and David", "text": "*About 1050 to 970 BC.*\n\nIsrael asked for a king, to be like the other nations. Saul was the first, and he spent his reign fighting the Philistines and failing to obey God.\n\nDavid, a shepherd from Bethlehem, followed him. He took the hill fortress of Jerusalem, which belonged to no tribe, and made it his capital.[^david-jerusalem][^qeiyafa-fortress] He brought the ark there. He defeated the Philistines for good and extended his rule over the neighboring peoples.\n\nGod made David a promise: one of his descendants would reign for ever. From this point the hope of Israel has a family name. Enemy kings a century later still called Judah the “House of David.”[^tel-dan-stele]\n\n*Read 2 Samuel 7:8–16.*", "sources": [{"id": "david-jerusalem", "label": "David’s Jerusalem · the Large Stone Structure", "citation": "Eilat Mazar, “Did I Find King David’s Palace?” Biblical Archaeology Review 32:1 (2006); Israel Finkelstein, Ze’ev Herzog, Lily Singer-Avitz and David Ussishkin, “Has King David’s Palace in Jerusalem Been Found?” Tel Aviv 34 (2007): 142–164.", "trail": "City of David excavations (Kathleen Kenyon, Yigal Shiloh, Eilat Mazar) → the exchange above.", "note": "Mazar dated a massive building and the Stepped Stone Structure to David’s time; her critics date parts earlier or later. The size of David’s kingdom is debated; that a royal house of David existed is secured by the Tel Dan Stele.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "qeiyafa-fortress", "label": "Khirbet Qeiyafa · a fortress in David’s day", "citation": "Yosef Garfinkel and Saar Ganor, Khirbet Qeiyafa, vol. 1: Excavation Report 2007–2008 (Israel Exploration Society, 2009); Yosef Garfinkel, Igor Kreimerman and Peter Zilberg, Debating Khirbet Qeiyafa: A Fortified City in Judah from the Time of King David (Israel Exploration Society, 2016).", "trail": "Excavation 2007–2013 → radiocarbon dates on olive pits → the reports above.", "note": "The excavators read a Judahite town of about 1000 BC; others propose a Saulide, Canaanite or Philistine-period site. Shaaraim (“two gates”, 1 Samuel 17:52) is their identification, debated by Nadav Na’aman and others. The ink ostracon found there in 2008 is early Hebrew or Canaanite writing; its translation is uncertain.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "tel-dan-stele", "label": "The Tel Dan Stele · “House of David”, about 840 BC", "citation": "Avraham Biran and Joseph Naveh, “An Aramaic Stele Fragment from Tel Dan,” Israel Exploration Journal 43 (1993): 81–98; “The Tel Dan Inscription: A New Fragment,” IEJ 45 (1995): 1–18. Israel Museum, Jerusalem.", "trail": "Found by Gila Cook of Biran’s team, July 1993; fragments B1 and B2 in 1994 → Biran and Naveh → George Athas, The Tel Dan Inscription (Sheffield, 2003).", "note": "The phrase bytdwd is read “House of David” by nearly all specialists; a few early alternatives (a place name, “house of the kettle”) have not held. The speaker is most likely Hazael of Damascus, who claims the killings 2 Kings 9 credits to Jehu; perhaps Jehu acted in league with Hazael, or the king took credit. How the fragments join is still discussed.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 11, "title": "Solomon and the temple", "text": "*About 970 to 931 BC.*\n\nSolomon inherited peace. Egypt and Assyria were both weak in these decades, and for once the land between them was not being fought over. He taxed the trade that crossed it, built fortified cities, and in about 966 BC began the temple in Jerusalem.[^solomon-gates]\n\nThe temple took seven years. It was not large, about the size of a small church, but it was lined with cedar and gold, and it was the one place on earth where God had said his name would dwell.[^ain-dara]\n\nSolomon also married foreign princesses to seal his treaties, and built shrines for their gods. The writer of Kings records the wisdom, the wealth and the idols without softening any of them.\n\n*Read 1 Kings 8:27–30 and 11:1–8.*", "sources": [{"id": "solomon-gates", "label": "Solomon’s gates · Hazor, Megiddo and Gezer", "citation": "Yigael Yadin, “Solomon’s City Wall and Gate at Gezer,” Israel Exploration Journal 8 (1958): 80–86; Israel Finkelstein, “The Archaeology of the United Monarchy: An Alternative View,” Levant 28 (1996): 177–187; William G. Dever, What Did the Biblical Writers Know and When Did They Know It? (Eerdmans, 2001).", "trail": "1 Kings 9:15 → Yadin read the three six-chambered gates as one royal plan → Finkelstein’s “low chronology” moved them later → Dever and Amihai Mazar defend a 10th-century date for Gezer.", "note": "The argument is about decades of pottery and radiocarbon dating. It decides whether the gates belong to Solomon or to the kings of Israel a few generations later. Students should know both sides and that the matter is still under study.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "ain-dara", "label": "The ‘Ain Dara temple · the closest parallel to Solomon’s plan", "citation": "John Monson, “The New ‘Ain Dara Temple: Closest Solomonic Parallel,” Biblical Archaeology Review 26:3 (2000); Ali Abu Assaf’s excavation report, Der Tempel von ‘Ain Dara (1990).", "trail": "Excavation in northern Syria (1980s) → Abu Assaf 1990 → Monson 2000.", "note": "A temple of the 10th–8th centuries BC with a porch, a main hall and an inner room, side chambers and two pillars at the entrance, the same three-part plan as 1 Kings 6. The building was badly damaged in fighting in 2018.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 12, "title": "Two kingdoms", "text": "*931 BC.*\n\nWhen Solomon died, the ten northern tribes refused his son and made Jeroboam their king. From then on there were two kingdoms.\n\n**Israel**, in the north, was larger and richer. Its capital came to be Samaria. It had nineteen kings from nine families in two hundred years, and many of them died by murder. Jeroboam set up golden calves at Dan and Bethel so that his people would not go to Jerusalem.[^tel-dan-high-place]\n\n**Judah**, in the south, was small and hilly. Its capital was Jerusalem. It had the temple, and every one of its kings was a descendant of David.\n\nFive years after the split, the pharaoh Shishak marched through both and carried off the temple’s gold.[^shoshenq]\n\n*Read 1 Kings 12:16–20, 26–30.*", "sources": [{"id": "tel-dan-high-place", "label": "Dan · Jeroboam’s high place", "citation": "Avraham Biran, Biblical Dan (Israel Exploration Society, 1994).", "trail": "Excavations at Tel Dan from 1966 → Biran 1994.", "note": "A large platform of dressed stone, an altar enclosure and a horned altar stood at Dan’s sacred precinct, rebuilt over centuries. Biran tied the first phase to Jeroboam I (1 Kings 12:29). Bethel’s shrine has not been identified with the same certainty.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "shoshenq", "label": "Shoshenq I (Shishak) · the campaign of about 925 BC", "citation": "The Bubastite Portal, temple of Amun at Karnak: a list of about 150 places; a fragment of Shoshenq’s stele found at Megiddo in 1926. K. A. Kitchen, The Third Intermediate Period in Egypt (1100–650 BC) (2nd ed., Aris & Phillips, 1986).", "trail": "Karnak relief → Kitchen 1986.", "note": "The surviving names include Megiddo, Taanach, Gibeon and Arad. Jerusalem is not among them, which fits 1 Kings 14:25–26, where Rehoboam gives up the temple’s gold. Part of the list is broken, and scholars differ on the campaign’s route.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 13, "title": "Omri, Ahab and Elijah", "text": "*About 885 to 850 BC.*\n\nOmri built Samaria and made Israel a real power.[^mesha-stele] The Assyrians were so impressed that they called Israel “the house of Omri” for a hundred years after his family was gone.[^black-obelisk] The Bible gives him eight verses.\n\nHis son Ahab married Jezebel, a princess of Sidon, who brought the worship of Baal with her. Against them stood the prophet Elijah.\n\nThis is the pattern for the rest of the kingdoms’ history. On one side is the king, with his army, his alliances and his gods. On the other is a man with no power at all who says, “Thus says the LORD.” The Bible is plain about which one mattered.\n\n*Read 1 Kings 18:17–39.*", "sources": [{"id": "mesha-stele", "label": "The Mesha Stele · Moab’s side of the story", "citation": "Basalt stele of Mesha, king of Moab, about 840 BC; Louvre, AO 5066. Seen at Dhiban by F. A. Klein in 1868; a paper squeeze was taken for Charles Clermont-Ganneau before the stone was broken. Translation by K. A. D. Smelik in The Context of Scripture, vol. 2 (2000), no. 2.23.", "trail": "The stone and squeeze → Clermont-Ganneau 1870 → Smelik → André Lemaire, “‘House of David’ Restored in Moabite Inscription,” Biblical Archaeology Review 20:3 (1994).", "note": "Mesha says Omri oppressed Moab “many days” and that he took vessels of Yahweh from Nebo. 2 Kings 3 tells the revolt from Israel’s side; the two differ on who won. Lemaire’s reading of “House of David” in line 31 is possible but damaged and still debated.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "black-obelisk", "label": "The Black Obelisk · Jehu’s tribute, 841 BC", "citation": "Black Obelisk of Shalmaneser III, from Nimrud; British Museum, 1848,1104.1. Found by Austen Henry Layard in 1846; Nineveh and Its Remains (London, 1849). Edited in Grayson, Royal Inscriptions of Mesopotamia, Assyrian Periods 3 (1996).", "trail": "The obelisk → Edward Hincks and Henry Rawlinson read the name in 1851 → Grayson 1996.", "note": "The caption calls him “Jehu, son of Omri.” Jehu was not Omri’s son; he ended that family (2 Kings 9–10). Assyrians called Israel the House of Omri for a century, so “son of Omri” means “of the land of Omri.” The kneeling figure may be Jehu himself or his envoy.", "url": "https://www.britishmuseum.org/collection/object/W_1848-1104-1", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}]}, {"number": 14, "title": "Assyria rises", "text": "*From 853 BC.*\n\nFar to the north-east, on the Tigris, Assyria was building the first great empire of the Iron Age. Its method was terror. Cities that resisted were destroyed and their people were moved to the other end of the empire, so that they would forget who they were.\n\nIn 853 BC Ahab joined a league of kings and stopped an Assyrian army at Qarqar in Syria.[^kurkh-monolith] In 841 BC a new king of Israel, Jehu, chose to pay tribute.[^black-obelisk]\n\nFor a century the pressure came and went. Under Jeroboam II, about 780 BC, Israel was rich again. The prophets Amos and Hosea walked through its markets and ivory-panelled houses and said it was rotten, and that the end was close.[^samaria-ivories]\n\n*Read Amos 6:1–7.*", "sources": [{"id": "kurkh-monolith", "label": "The Kurkh Monolith · Ahab at Qarqar, 853 BC", "citation": "Monolith of Shalmaneser III from Kurkh, Turkey, found by J. E. Taylor in 1861; British Museum. Edited in A. K. Grayson, Assyrian Rulers of the Early First Millennium BC II (858–745 BC), Royal Inscriptions of Mesopotamia, Assyrian Periods 3 (Toronto, 1996).", "trail": "The stone → Grayson 1996 → Kitchen, On the Reliability of the Old Testament (2003), ch. 2.", "note": "Shalmaneser lists “Ahab the Israelite” with 2,000 chariots and 10,000 soldiers. Some think the scribe miscopied the chariots (perhaps 200); either way Ahab’s force ranks among the largest. The Bible does not mention Qarqar; Assyria claimed a victory, but it did not advance for years.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "black-obelisk", "label": "The Black Obelisk · Jehu’s tribute, 841 BC", "citation": "Black Obelisk of Shalmaneser III, from Nimrud; British Museum, 1848,1104.1. Found by Austen Henry Layard in 1846; Nineveh and Its Remains (London, 1849). Edited in Grayson, Royal Inscriptions of Mesopotamia, Assyrian Periods 3 (1996).", "trail": "The obelisk → Edward Hincks and Henry Rawlinson read the name in 1851 → Grayson 1996.", "note": "The caption calls him “Jehu, son of Omri.” Jehu was not Omri’s son; he ended that family (2 Kings 9–10). Assyrians called Israel the House of Omri for a century, so “son of Omri” means “of the land of Omri.” The kneeling figure may be Jehu himself or his envoy.", "url": "https://www.britishmuseum.org/collection/object/W_1848-1104-1", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}, {"id": "samaria-ivories", "label": "Samaria · the ivory houses", "citation": "Harvard excavations led by George Reisner (1908–10) and the Joint Expedition under J. W. Crowfoot (1931–35); J. W. and G. M. Crowfoot, Early Ivories from Samaria (London, 1938).", "trail": "Excavation reports → Crowfoot 1938.", "note": "More than five hundred fragments of carved ivory, once set into furniture and wall panels, came from the royal quarter. Amos 3:15 and 6:4 condemn the “houses of ivory” and “beds of ivory”; 1 Kings 22:39 mentions Ahab’s ivory house. The Samaria ostraca, records of wine and oil, come from the same palace.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 15, "title": "The fall of Samaria", "text": "*722 BC.*\n\nIn 745 BC a soldier took the Assyrian throne as Tiglath-Pileser III and began conquering in earnest. Israel’s last kings twisted between paying him and rebelling against him. One of them was murdered by the next.\n\nIn 724 BC the Assyrians laid siege to Samaria. It held for three years. In 722 BC it fell. The Assyrian king recorded that he carried away 27,290 people and settled foreigners in their place.[^sargon-samaria]\n\nThe ten northern tribes were scattered across the empire and never returned as a nation. The mixed people who lived in their land afterward were the ancestors of the Samaritans.\n\nThe writer of Kings stops the story to explain why. It is the longest comment in the book.\n\n*Read 2 Kings 17:5–23.*", "sources": [{"id": "sargon-samaria", "label": "Sargon II and the fall of Samaria, 722–720 BC", "citation": "Sargon II’s annals at Khorsabad and the Nimrud Prism: 27,290 people deported (another text has 27,280). Babylonian Chronicle 1 says Shalmaneser V “ravaged Samaria.” K. Lawson Younger Jr., “The Deportations of the Israelites,” Journal of Biblical Literature 117 (1998): 201–227.", "trail": "Paul-Émile Botta found Sargon’s palace at Khorsabad in 1843 → the annals → Younger 1998.", "note": "2 Kings 17 credits the siege to Shalmaneser V and the capture to “the king of Assyria.” Sargon claimed the deportations in his own inscriptions. Most historians conclude that Shalmaneser took the city in 722 and Sargon completed the deportations and resettlement by 720.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 16, "title": "Hezekiah", "text": "*701 BC.*\n\nJudah was now alone, with an Assyrian province a short day’s walk north of Jerusalem.\n\nKing Hezekiah closed the country shrines, repaired the temple and called the people back to the LORD.[^hezekiah-bulla] He also prepared for war. He built a new wall, stored grain in jars stamped with the royal mark, and cut a tunnel to bring water inside the city.[^lmlk-jars][^siloam-tunnel]\n\nIn 701 BC Sennacherib came. He took every fortified town in Judah except one and sent an officer to shout at the walls of Jerusalem in Hebrew.[^lachish-reliefs][^sennacherib-prism] Hezekiah took the letter of demand into the temple and spread it out before God. The prophet Isaiah said the king of Assyria would not shoot an arrow there.\n\nHe did not. His army died in the night, and he went home.\n\n*Read 2 Kings 19:14–19, 32–36.*", "sources": [{"id": "hezekiah-bulla", "label": "The Hezekiah and “Isaiah” bullae", "citation": "Ophel excavations directed by Eilat Mazar; the Hezekiah bulla published in 2015; Eilat Mazar, “Is This the Prophet Isaiah’s Signature?” Biblical Archaeology Review 44:2 (2018).", "trail": "Sifted soil from a refuse layer (2009) → reading by the excavation team → Mazar 2015 and 2018.", "note": "The Hezekiah bulla’s reading is not in doubt; it carries a winged sun, a royal emblem of Judah. The “Isaiah” bulla breaks after the letters nby, so the word may be “prophet” (with a missing aleph) or a personal or family name. Christopher Rollston and others regard “prophet” as possible but unproven.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "lmlk-jars", "label": "Royal jars and the Broad Wall · Hezekiah prepares", "citation": "Storage jars with handles stamped lmlk, “belonging to the king,” and one of four towns (Hebron, Ziph, Socoh, Mmšt): Andrew G. Vaughn, Theology, History, and Archaeology in the Chronicler’s Account of Hezekiah (Scholars Press, 1999). The Broad Wall: Nahman Avigad, Discovering Jerusalem (Nelson, 1983).", "trail": "Thousands of stamped handles from Judahite sites → Vaughn 1999; the Jewish Quarter excavations (1969–82) → Avigad 1983.", "note": "Most of the stamped jars come from layers destroyed in 701 BC, matching 2 Chronicles 32:27–29. Avigad’s seven-meter-thick wall cuts through houses, as Isaiah 22:10 says: “you tore down houses to fortify the wall.”", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "siloam-tunnel", "label": "The Siloam Tunnel and its inscription", "citation": "Inscription found in 1880; Istanbul Archaeology Museums. Amos Frumkin, Aryeh Shimron and Jeff Rosenbaum, “Radiometric dating of the Siloam Tunnel, Jerusalem,” Nature 425 (2003): 169–171.", "trail": "The tunnel → the inscription (Conrad Schick, Archibald Sayce, 1880–81) → Frumkin et al. 2003.", "note": "Radiocarbon from plant matter in the plaster and uranium-thorium dates from cave deposits place the tunnel about 700 BC, Hezekiah’s time (2 Kings 20:20; 2 Chronicles 32:30). A few scholars have proposed an earlier start; the inscription’s letter forms also fit about 700.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "lachish-reliefs", "label": "The Lachish reliefs · Sennacherib’s showpiece", "citation": "Stone panels from Room XXXVI of the Southwest Palace, Nineveh, excavated by Layard 1847–51; British Museum. David Ussishkin, The Conquest of Lachish by Sennacherib (Tel Aviv University, 1982).", "trail": "The reliefs → Layard → Ussishkin 1982, with the excavated siege ramp at Lachish.", "note": "The Assyrian siege ramp at Lachish, the only one of its kind excavated, still lies against the city’s south-west corner, with a Judahite counter-ramp inside. Arrowheads, sling stones and the remains of the burned gate match the carving closely.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "sennacherib-prism", "label": "Sennacherib’s prisms · Hezekiah “like a bird in a cage”", "citation": "Taylor Prism, British Museum; Oriental Institute Prism, Chicago; Jerusalem Prism, Israel Museum. Daniel David Luckenbill, The Annals of Sennacherib (Oriental Institute Publications 2, Chicago, 1924); A. Kirk Grayson and Jamie Novotny, Royal Inscriptions of the Neo-Assyrian Period 3/1 (2012).", "trail": "Prisms from Nineveh → Luckenbill 1924 → Grayson and Novotny 2012; on the murder, Simo Parpola, “The Murderer of Sennacherib,” in Death in Mesopotamia (1980); Herodotus, Histories 2.141.", "note": "Sennacherib claims 46 towns and 30 talents of gold, the same figure as 2 Kings 18:14 (the silver differs, 800 talents to 300). He never claims Jerusalem. Herodotus heard in Egypt that mice gnawed the Assyrians’ bowstrings in one night; 2 Kings 19:35 says the angel of the LORD struck the camp. Babylonian Chronicle 1 and Esarhaddon’s own inscription confirm his murder by a son (2 Kings 19:37).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 17, "title": "Manasseh and Josiah", "text": "*697 to 609 BC.*\n\nHezekiah’s son Manasseh reigned fifty-five years, longer than any king of Judah, and undid everything his father had done. Assyrian records list him as a loyal subject.[^manasseh-assyria]\n\nHis grandson Josiah became king at eight. In 622 BC, during repairs to the temple, a scroll of the Law was found. Josiah heard it read and tore his clothes. He led the most thorough reform in Judah’s history.\n\nBy then Assyria was collapsing. Its capital, Nineveh, fell in 612 BC to the Babylonians and their allies.[^nineveh-fall] In 609 BC the pharaoh marched north to prop up what was left of Assyria. Josiah tried to stop him at Megiddo and was killed.\n\nJudah had twenty-three years left.\n\n*Read 2 Kings 22:8–13 and 23:25–30.*", "sources": [{"id": "manasseh-assyria", "label": "Manasseh in the Assyrian records", "citation": "Esarhaddon’s Nineveh prisms list “Manasseh, king of Judah” among twenty-two western kings who supplied building materials: Erle Leichty, The Royal Inscriptions of Esarhaddon, King of Assyria (680–669 BC), Royal Inscriptions of the Neo-Assyrian Period 4 (Eisenbrauns, 2011). Ashurbanipal’s annals name him among kings who sent troops for the campaign against Egypt.", "trail": "Prisms from Nineveh → Leichty 2011.", "note": "2 Chronicles 33:11–13 says Manasseh was taken in hooks to Babylon and later restored. No Assyrian text mentions it. Some connect it with the Babylonian revolt of 652–648 BC, when Assyria questioned the loyalty of its western vassals.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "nineveh-fall", "label": "The fall of Nineveh and Josiah at Megiddo", "citation": "Babylonian Chronicle 3 (British Museum 21901): Nineveh taken in 612 BC; the Egyptian army marches to help Assyria at Harran in 609 BC. C. J. Gadd, The Fall of Nineveh (London, 1923); Grayson, Assyrian and Babylonian Chronicles (1975). Nahum 3.", "trail": "The tablet → Gadd 1923 → Grayson 1975.", "note": "The chronicle explains 2 Kings 23:29: Pharaoh Necho went up to the Euphrates to help the king of Assyria, not to fight him, as some older translations put it. Josiah tried to stop Egypt’s army on the way and was killed at Megiddo.", "url": "https://www.livius.org/sources/content/mesopotamian-chronicles-content/abc-3-fall-of-nineveh-chronicle/", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 18, "title": "Babylon", "text": "*605 to 586 BC.*\n\nIn 605 BC the Babylonian prince Nebuchadnezzar crushed Egypt’s army at Carchemish and became master of the west.[^babylonian-chronicle] That year he took hostages from Jerusalem, among them a young man named Daniel.\n\nJudah rebelled. On 16 March 597 BC Nebuchadnezzar took Jerusalem and carried off its eighteen-year-old king, Jehoiachin, with ten thousand of its leading people.[^jehoiachin-rations] Ezekiel was among them.\n\nJudah rebelled again. The prophet Jeremiah told the king to surrender and was thrown in a pit for it. After a siege of eighteen months the wall was breached in the summer of 586 BC.[^lachish-letters] The city was burned, the temple destroyed and most of the people marched to Babylon.\n\n*Read 2 Kings 25:1–12.*", "sources": [{"id": "babylonian-chronicle", "label": "The Babylonian Chronicle · Jerusalem taken on 2 Adar 597 BC", "citation": "Chronicle 5 (the “Jerusalem Chronicle”), British Museum 21946. D. J. Wiseman, Chronicles of Chaldaean Kings (626–556 B.C.) in the British Museum (London, 1956); A. K. Grayson, Assyrian and Babylonian Chronicles (Locust Valley, 1975).", "trail": "The tablet → Wiseman 1956 → Grayson 1975 → Jean-Jacques Glassner, Mesopotamian Chronicles (Society of Biblical Literature, 2004).", "note": "It records Carchemish (605 BC, Jeremiah 46:2) and the capture of “the city of Judah” on 2 Adar of Nebuchadnezzar’s seventh year: 15/16 March 597 BC. The chronicles for 594–557 BC are missing, which is why 587 or 586 for Jerusalem’s fall is still argued.", "url": "https://www.livius.org/sources/content/mesopotamian-chronicles-content/abc-5-jerusalem-chronicle/", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}, {"id": "jehoiachin-rations", "label": "Jehoiachin’s rations · the king in Babylon", "citation": "Clay tablets from the Southern Palace of Babylon, excavated by Robert Koldewey (1899–1917); Vorderasiatisches Museum, Berlin. Ernst F. Weidner, “Jojachin, König von Juda, in babylonischen Keilschrifttexten,” in Mélanges syriens offerts à M. René Dussaud, vol. 2 (Paris, 1939).", "trail": "The tablets → Weidner 1939 → William F. Albright’s English discussion (Biblical Archaeologist, 1942).", "note": "Dated 592 BC, they list oil for “Ya’ukin, king of the land of Yahudu” and his five sons, among workers and captives from Tyre, Egypt, Ionia and elsewhere. 2 Kings 25:27–30 says he was later released and fed at the king’s table.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "lachish-letters", "label": "The Lachish letters · “we cannot see Azekah”", "citation": "Ink-written potsherds (ostraca) from the gate of Lachish, found by J. L. Starkey in 1935 (more in 1938). Harry Torczyner, Lachish I: The Lachish Letters (Oxford, 1938). The letters are divided between the British Museum and the Israel Museum.", "trail": "The ostraca → Torczyner 1938 → Dennis Pardee in The Context of Scripture, vol. 3 (2002).", "note": "Letter 4 says the writer is watching for the signals of Lachish, “for we cannot see Azekah.” Some read this as meaning Azekah had already fallen (Jeremiah 34:7); others think the outpost simply could not see it from where it stood. Either way the letters come from the last weeks before Babylon’s conquest.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 19, "title": "The exile", "text": "*586 to 539 BC.*\n\nThis should have been the end. Every other nation deported by Assyria or Babylon vanished into the population.\n\nJudah did not. The exiles were settled in villages along the canals of Babylonia.[^al-yahudu] They farmed, traded and raised families. They kept the Sabbath. They copied and studied the scrolls they had brought. They wept when they remembered Zion, and they taught their children who they were.\n\nThey had been told that this would happen and why, and they had been told it would not be for ever. Jeremiah had named the length: seventy years. A hundred and fifty years earlier, Isaiah’s book had named the man who would end it.[^isaiah-cyrus]\n\n*Read Jeremiah 29:4–14 and Psalm 137.*", "sources": [{"id": "al-yahudu", "label": "Āl-Yāhūdu · “Judah-town” in Babylonia", "citation": "About 200 cuneiform tablets, 572–477 BC: Laurie E. Pearce and Cornelia Wunsch, Documents of Judean Exiles and West Semites in Babylonia in the Collection of David Sofer (CDL Press, 2014).", "trail": "Tablets that came through the antiquities market → Pearce and Wunsch 2014.", "note": "Contracts and receipts from a village of Judean exiles, with names built on Yahweh (such as Yahu-azar) across four generations. They show the exiles farming and trading, as Jeremiah 29:5–7 told them to. Because the tablets were not excavated, scholars use them with care over their exact origin.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "isaiah-cyrus", "label": "Isaiah names Cyrus · two readings", "citation": "Isaiah 44:28–45:1. One-author view: Oswald T. Allis, The Unity of Isaiah (Presbyterian & Reformed, 1950); John N. Oswalt, The Book of Isaiah, Chapters 40–66 (Eerdmans, 1998). Majority critical view: Joseph Blenkinsopp, Isaiah 40–55 (Anchor Bible, 2002). Josephus, Antiquities 11.5–6.", "trail": "Josephus → modern commentaries.", "note": "Those who hold one Isaiah of the 8th century read the naming of Cyrus as prediction; Josephus says Cyrus himself read it. Most critical scholars assign chapters 40–55 to a prophet writing in the exile about 540 BC. The Great Isaiah Scroll copies all 66 chapters as one book, with no break at chapter 40.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 20, "title": "Cyrus and the return", "text": "*539 to 516 BC.*\n\nIn October 539 BC Cyrus, king of Persia, took Babylon almost without a fight. His way of ruling was the opposite of Assyria’s. He let conquered peoples go home and worship their own gods, and expected their loyalty in return.[^cyrus-cylinder]\n\nIn 538 BC he issued a decree for the Jews. About fifty thousand made the four-month journey back to a ruined city. They built an altar, then laid the foundation of a new temple. The old men who remembered Solomon’s temple wept when they saw how small it was.\n\nOpposition stopped the work for sixteen years. The prophets Haggai and Zechariah started it again. The second temple was finished in 516 BC, seventy years after the first was burned.\n\n*Read Ezra 1:1–4 and 3:10–13.*", "sources": [{"id": "cyrus-cylinder", "label": "The Cyrus Cylinder · the policy of return", "citation": "Clay cylinder, Babylon, after 539 BC; British Museum, 1880,0617.1941. Found by Hormuzd Rassam in 1879. Irving Finkel (ed.), The Cyrus Cylinder: The King of Persia’s Proclamation from Ancient Babylon (I. B. Tauris, 2013).", "trail": "The cylinder → Rawlinson’s first translation (1880) → Finkel 2013, with the fragments of a second copy identified in 2010.", "note": "Cyrus says he returned gods and peoples to their homes. It names places in Mesopotamia and western Iran, not Judah. It shows a policy; Ezra 1 and 6 record a decree for Jerusalem. Some historians think Cyrus’s generosity was more limited than his propaganda claims; Ezra’s decree fits the way Persian kings dealt with local temples.", "url": "https://www.britishmuseum.org/collection/object/W_1880-0617-1941", "consulted": "Compiled from the published record, November 2026. Museum page by registration number."}]}, {"number": 21, "title": "Esther, Ezra and Nehemiah", "text": "*486 to about 430 BC.*\n\nMost Jews did not go back. They stayed across the Persian Empire, which ran from India to Ethiopia. The book of Esther is set among them, at the court of Xerxes, the same king who invaded Greece and was beaten at Salamis.[^xerxes-esther]\n\nIn 458 BC Ezra, a priest and scholar, led a second group home and taught the Law. In 445 BC Nehemiah, cupbearer to the Persian king, was sent as governor.[^elephantine] He rebuilt Jerusalem’s wall in fifty-two days with a trowel in one hand and a sword in the other.\n\nThe last prophet, Malachi, spoke around 430 BC. He promised a messenger who would prepare the way, and then the LORD himself coming to his temple. After that the Old Testament falls silent.\n\n*Read Nehemiah 4:15–20 and Malachi 3:1.*", "sources": [{"id": "xerxes-esther", "label": "Xerxes and the world of Esther", "citation": "Herodotus, Histories, books 7–9 (Xerxes’ invasion, Salamis 480 BC); the Persepolis Fortification and Treasury tablets; Edwin M. Yamauchi, Persia and the Bible (Baker, 1990).", "trail": "Herodotus and the Persepolis archives → Yamauchi 1990.", "note": "Esther’s Ahasuerus is the Hebrew form of Xšayāršā, Xerxes I (486–465 BC). French excavations at Susa uncovered the palace Esther describes. A Persepolis tablet names an official Marduka; whether he is Mordecai is uncertain, because the name was common.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "elephantine", "label": "The Elephantine papyri · Nehemiah’s neighbors", "citation": "Aramaic papyri from a Jewish garrison at Elephantine, Egypt, 5th century BC. A. E. Cowley, Aramaic Papyri of the Fifth Century B.C. (Oxford, 1923), nos. 30–31; Bezalel Porten, The Elephantine Papyri in English (Brill, 1996).", "trail": "The papyri (Berlin, Brooklyn and Cairo) → Cowley 1923 → Porten 1996.", "note": "A letter of 407 BC to Bagohi, governor of Judah, mentions Johanan the high priest (Nehemiah 12:22) and the sons of Sanballat, governor of Samaria, Nehemiah’s opponent (Nehemiah 2:10). It sets Nehemiah’s people in a real Persian province.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 22, "title": "Four hundred years", "text": "*About 430 BC to the birth of Christ.*\n\nThe silence was not empty.\n\nIn 332 BC Alexander the Great took the land from Persia. After him it lay between two Greek kingdoms, in Egypt and in Syria, as it had once lain between Egypt and Assyria. Greek became the common language from Spain to India. In Egypt the Hebrew Scriptures were translated into it.[^septuagint]\n\nIn 167 BC a Syrian king, Antiochus IV, banned the Jewish faith and set up an altar to Zeus in the temple.[^maccabees] A family of priests, the Maccabees, led a revolt and won. They rededicated the temple in 164 BC. Jews remember it at Hanukkah.\n\nFor a century Judea had its own kings. In 63 BC a Roman general walked into the temple. Rome later gave the throne to Herod.", "sources": [{"id": "septuagint", "label": "The Septuagint · the Scriptures in Greek", "citation": "The Letter of Aristeas (2nd century BC) on the translation of the Law under Ptolemy II; Karen H. Jobes and Moisés Silva, Invitation to the Septuagint (2nd ed., Baker, 2015).", "trail": "Aristeas → Jobes and Silva.", "note": "The Law was translated into Greek in Alexandria in the 3rd century BC, and the other books over the next two centuries. Aristeas’ story of seventy-two translators finishing in seventy-two days is legend; the translation itself is real. The New Testament writers often quote it.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "maccabees", "label": "Antiochus IV and the Maccabees, 167–164 BC", "citation": "1 Maccabees 1:54–61 and 4:36–59; 2 Maccabees 10:1–8; Josephus, Antiquities 12.248–326; Daniel 11:31. Pompey in the temple, 63 BC: Josephus, Antiquities 14.72; Tacitus, Histories 5.9.", "trail": "1–2 Maccabees and Josephus → modern histories of the Second Temple period.", "note": "1 Maccabees is a careful history written about 100 BC; it is not part of the Protestant canon, but it is a primary source. John 10:22 shows Jesus in the temple at the Feast of Dedication, Hanukkah.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 23, "title": "Keeping the scrolls", "text": "Through all of this, somebody was copying the books.\n\nScrolls wear out. Each one had to be copied by hand before it did, letter by letter, on leather. Scribes counted the letters in each book and checked the middle one.[^scribes-counted] If the count was wrong, the copy was not used.\n\nBy the last centuries before Christ there were synagogues wherever Jews lived, and each needed scrolls. Most scholars think a community by the Dead Sea owned hundreds, and hid them in caves when the Romans came in AD 68.\n\nThose scrolls were found in 1947.[^dead-sea-scrolls] They show that the Old Testament read in the synagogue at Nazareth was essentially the one we read now.\n\n*Read Luke 4:16–21.*", "sources": [{"id": "scribes-counted", "label": "Scribes who counted letters", "citation": "Babylonian Talmud, Qiddushin 30a: the early scribes were called soferim because they counted the letters of the Torah. Ernst Würthwein, The Text of the Old Testament (3rd ed., Eerdmans, 2014); Emanuel Tov, Textual Criticism of the Hebrew Bible (3rd ed., Fortress, 2012).", "trail": "The Talmud and the Masoretic notes → Würthwein → Tov.", "note": "The letter and word counts are best documented in the Masoretes’ work of AD 600–1000, who marked middle letters and verses in the margins. Earlier scribes were careful too, and the Dead Sea Scrolls show both carefully copied texts and freer ones.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "dead-sea-scrolls", "label": "The Dead Sea Scrolls", "citation": "Eleven caves near Qumran, 1947–1956; Roland de Vaux’s excavation of the settlement, Archaeology and the Dead Sea Scrolls (Schweich Lectures 1959; Oxford, 1973). James VanderKam and Peter Flint, The Meaning of the Dead Sea Scrolls (HarperSanFrancisco, 2002). The Great Isaiah Scroll, 1QIsaᵃ, is in the Shrine of the Book, Israel Museum.", "trail": "The caves → de Vaux → the official edition, Discoveries in the Judaean Desert (Oxford, 1955–2011) → VanderKam and Flint.", "note": "Most scholars link the scrolls with the Essenes described by Pliny the Elder (Natural History 5.73) and Josephus (Jewish War 2.119–161); Norman Golb argued they came from Jerusalem libraries. The Isaiah scroll is about a thousand years older than the Leningrad Codex (AD 1008) and agrees with it closely. Some books, such as Jeremiah, also circulated in a shorter edition close to the Septuagint.", "url": "http://dss.collections.imj.org.il/isaiah", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 24, "title": "The thread", "text": "Step back and look at the whole.\n\nA promise to one man with no children. A family in Egypt. A nation at a mountain. A kingdom, then two, then none. An exile that should have erased them, and a return that no one could have predicted. Four silent centuries of waiting.\n\nEmpires far stronger than Israel rose and fell around it: Egypt, Assyria, Babylon, Persia, Greece. Their gods are in museums.\n\nThe Old Testament ends unfinished. It promises a king from David’s line whose kingdom will have no end, a servant who will bear the sins of many, and the LORD himself coming to his people. It does not say how those can be the same person.\n\nThat is where the New Testament begins.\n\n*Read Isaiah 9:6–7 and Galatians 4:4–5.*"}], "source": "Foundation-Claude/old-testament/books/OT-H-history-long.md", "sha256": "95f19231d159165fc90179727e092c1d6c2a30677bc902e8e0d1d119064794e7"}}}, {"id": "old-r", "hall": "ot", "subject": "Apologetics", "editions": {"short": {"title": "Good Questions", "subtitle": "Questions about the Old Testament, and reasons to trust", "blurb": "A friend asks whether the Bible can be trusted. Start with a good question, explore the evidence, and see why faith and truth belong together.", "pages": [{"number": 1, "title": "Is faith blind?", "text": "Some people think faith means believing what you know ain’t true. The Bible invites us to look at what God has done.\n\nLuke says why he investigated Jesus’s life and wrote his account: “so that you may know the certainty about the things you have been taught.” (Luke 1:4 LSB)\n\nFaith includes knowing what is claimed, believing it is true, and trusting the one it is about. Imagine a bridge: you learn how it was built, see that it holds, then trust it enough to cross.\n\nSomeone whose care and honesty you trust may first tell you about God. That can be a good beginning. Reading Scripture and examining the evidence help you see why Jesus is trustworthy.\n\nAsk good questions. Look for truthful answers. Trust grows as you come to know the God you are trusting."}, {"number": 2, "title": "“Isn’t believing just guessing?”", "text": "You probably trust your mom to pick you up if she has kept that promise before. Or think of another person who has earned your trust. Their dependability gives you a reason.\n\nYou cannot see tomorrow’s journey yet. You still have reasons to expect that person to keep their word. Trust goes beyond what is in front of your eyes, while resting on what you have learned.\n\nHebrews says, “Now faith is the assurance of things hoped for, the conviction of things not seen.” (Hebrews 11:1 LSB)\n\nChristians trust God because of who he is and what he has done. We learn about him through Scripture, through people who tell us the truth, and through the evidence of his work in history.\n\nYou can begin to trust while you are still learning."}, {"number": 3, "title": "“Were the people in the Bible real?”", "text": "Enemy kings left records that name people in the Bible. A stone from Tel Dan names David’s dynasty. Assyria’s Black Obelisk names Jehu. Another Assyrian account names Hezekiah of Judah.\n\nThese rulers were busy praising themselves. They were not trying to help Christians write a book. Their records let us check names and events from another side.\n\nThe Bible says God acts so that people may know him: “that you might know that Yahweh, He is God; there is no other besides Him.” (Deuteronomy 4:35 LSB)\n\nThe artifact gives us one piece of the history. Scripture helps us understand the person, the promise and the God who was at work."}, {"number": 4, "title": "“Why hasn’t everything been found?”", "text": "Most everyday things do not last for thousands of years. Cloth and wood rot. Buildings are rebuilt. Many old towns are still mostly buried.\n\nHistorian Edwin Yamauchi pictured several losses between ancient life and the handful of evidence we read today: what survived, what was found, what was dug and what was published. Missing pieces are part of archaeology.\n\nHattusa is a good example. Excavators found thousands of tablets in the old Hittite capital. A once-obscure people could be studied through their own records.\n\nCareful investigation matters. Luke described his work as “having investigated everything carefully from the beginning” (Luke 1:3 LSB).\n\nAsk where people have looked and what they have found. A new discovery can give us another reason to listen to the Bible’s history."}, {"number": 5, "title": "“Did the Bible get changed?”", "text": "We can compare the copies. The Great Isaiah Scroll was written about 125 BC, roughly a thousand years before the great medieval Hebrew copies. It contains the same recognizable book, including chapter 53.\n\nScholars publish the differences too. Some concern spelling; some concern wording. That lets us check the copying instead of guessing what happened.\n\nA burned scroll from En-Gedi adds another comparison. Computer scans recovered part of Leviticus, and its letters match the later Hebrew text. Tiny silver amulets from Ketef Hinnom carry blessing words from Numbers even earlier.\n\n“The grass withers, the flower fades,\nBut the word of our God stands forever.” (Isaiah 40:8 LSB)\n\nPeople carried these words through centuries. Today we can inspect the old copies and read them ourselves."}, {"number": 6, "title": "“What can a stone show us?”", "text": "A stone can name a king. A ruined wall can show how a city was built. A scroll can show that certain words were written before a certain date.\n\nThink of a friend whose story keeps checking out. Each true detail gives you another reason to listen. Archaeological finds can do that for the Bible’s history.\n\nThe Gospel of John explains why its accounts were written: “these have been written so that you may believe that Jesus is the Christ, the Son of God; and that believing you may have life in His name.” (John 20:31 LSB)\n\nRead the object and the account together. The evidence belongs to a larger invitation: come to know Jesus and trust him."}, {"number": 7, "title": "“Did someone find chariot wheels in the sea?”", "text": "Exciting claims about chariot wheels in the Red Sea have not produced accepted archaeological evidence. Before sharing a discovery, ask where it came from and whether there is a report people can examine.\n\nGod says, “You shall not bear false witness against your neighbor.” (Exodus 20:16 LSB)\n\nYou can ask a parent, pastor or teacher to help you check a source. Look for the people who did the work, the object’s location and what was actually published.\n\nIf you repeat something mistaken, you can correct it. Speaking truthfully matters more than having the most exciting answer.\n\nWe honor God and care for friends when our words can be trusted."}, {"number": 8, "title": "“Why tell bad things about the heroes?”", "text": "The Bible tells us Abraham lied. David did terrible wrong. God’s people worshiped idols and hurt one another. Its writers tell the truth about people they care about.\n\nThey are showing us why those people needed mercy. Isaiah includes himself when he says, “All of us like sheep have gone astray,\nEach of us has turned to his own way” (Isaiah 53:6 LSB).\n\nThe same chapter describes a servant who bears his people’s sins. Christians recognize Jesus there.\n\nGod’s grace is for people who need forgiveness, including us. The Bible can be honest about our wrongs because it also tells us about the Savior who came to rescue us."}, {"number": 9, "title": "“What if I don’t know the answer?”", "text": "Say so: “I don’t know yet. Let’s look into it.” You can ask someone who has studied the question and read what they found.\n\nChristians who trust the Bible sometimes disagree about a date, such as when Israel left Egypt. They can compare their reasons without treating each other as enemies.\n\nPaul says, “Let your words always be with grace, seasoned with salt” (Colossians 4:6 LSB).\n\nYour friend may ask something you have never considered. Listen carefully. You can come back to the question after you have learned more.\n\nAn honest, kind conversation can help both of you understand the truth better."}, {"number": 10, "title": "Be like a gardener", "text": "A gardener plants and waters. Growth takes time.\n\nPaul says, “I planted, Apollos watered, but God was causing the growth.” (1 Corinthians 3:6 LSB)\n\nGreg Koukl uses gardening as a picture for talking about Jesus. You might help a friend with one question today. Someone else may explain another part later. God is at work through more than one conversation.\n\nOffer one true thing your friend can think about. Ask what they make of it, and give them room to answer.\n\nYou do not earn God’s love by having all the answers. Christ is our Savior. We can pray for our friends, share our reasons, and trust God to give the growth."}, {"number": 11, "title": "The best reason", "text": "Jesus trusted the Old Testament and showed how it pointed to him. After his resurrection, “He interpreted to them the things concerning Himself in all the Scriptures.” (Luke 24:27 LSB)\n\nWe need forgiveness. Jesus, God’s Son, became human, died for sinners and rose again. He gives new life to those who turn from sin and trust him. His Spirit helps us follow him.\n\nThe people and places you have studied belong to that history of promises kept. The evidence gives us good reasons to trust Jesus and share our hope kindly.\n\nAt Jerusalem, Jesus said:\n\n“I tell you, if these were silent, the stones will cry out!” (Luke 19:40 LSB)\n\n*Read together: John 3:16; Isaiah 53; 1 Peter 3:15–16.*"}], "source": "Foundation-Claude/old-testament/books/OT-R-apologetics-short.md", "sha256": "08b2b42563b3e85f62951af84c57dfc54660ad59e93dad78b05ffdd5e77b9c1d", "revision": "November 20, 2026", "translationNotices": {"LSB": "Scripture quotations taken from the (LSB®) Legacy Standard Bible®, Copyright © 2021 by The Lockman Foundation. Used by permission. All rights reserved. Managed in partnership with Three Sixteen Publishing Inc. LSBible.org and 316publishing.com.", "CSB": "Scripture quotations marked CSB have been taken from the Christian Standard Bible®, Copyright © 2017, 2020 by Holman Bible Publishers. Used by permission. Christian Standard Bible® and CSB® are federally registered trademarks of Holman Bible Publishers."}}, "long": {"title": "Fair Questions", "subtitle": "How to think about the Old Testament and the evidence", "blurb": "Faith welcomes truthful questions. Read Scripture, meet the scholars, and examine discoveries that bring its history into view.", "pages": [{"number": 1, "title": "Is faith blind?", "text": "Some people think faith means believing what you know ain’t true. Others treat faith and evidence like a seesaw: the more evidence you have, the less faith you need.\n\nThe Bible doesn’t talk that way. God gave Moses signs to do in front of the people, “that they may believe that Yahweh … has appeared to you.” (Exodus 4:5 LSB) Elijah asked for fire from heaven in front of a whole crowd: “today let it be known that You are God in Israel” (1 Kings 18:36 LSB).\n\nLuke, “having investigated everything carefully from the beginning,” (Luke 1:3 LSB) wrote his Gospel “so that you may know the certainty about the things you have been taught.” (Luke 1:4 LSB) And Peter tells every Christian to be “always being ready to make a defense to everyone who asks you to give an account for the hope that is in you” (1 Peter 3:15 LSB).\n\nIn the Bible, evidence is not the enemy of faith. God gives it on purpose.\n\nChristians have taught this through the centuries. Augustine distinguished believing that God is, believing what God says, and believing in God. The Reformers named three parts of faith: knowing what is claimed, agreeing that it is true, and trusting the one it is about.[^faith] You can know a bridge’s design and agree that it will hold, but you have not trusted it until you walk across. Trust is the heart of it.\n\nYou may first hear about God from someone whose care and honesty you have come to trust. Taking that person’s word seriously is a reasonable beginning. As you read Scripture and look at the evidence, you come to see more clearly why Jesus is worth trusting.\n\nPaul did the same. For three Sabbaths he “reasoned with them from the Scriptures, explaining and setting before them that the Christ had to suffer and rise again from the dead” (Acts 17:2–3 LSB). Giving reasons and inviting trust belong together. You do not have to answer every question before you begin to trust Christ.\n\nFaith entrusts us to the God we are getting to know. The evidence shows us why that trust is well placed.\n\n*Read Exodus 4:1–5, 1 Kings 18:36–39, Luke 1:1–4, Acts 17:2–4 and 1 Peter 3:15–16.*", "sources": [{"id": "faith", "label": "Augustine, Lombard and Berkhof · knowing, assent and trust", "citation": "Peter Lombard, Sentences 3.23.4, receiving Augustine’s distinction; Louis Berkhof, Systematic Theology, Part IV, “Faith,” section D, “The Elements of Faith.”", "trail": "Classical Reformed account; compare Grisanti, OT796 Notes, printed pp. 27–28.", "note": "Knowledge and agreement belong with personal reliance on Christ. The bridge is this book’s illustration, not a quotation from these authors.", "url": "https://www.ccel.org/ccel/berkhof/systematictheology.vi.viii.html", "consulted": "Berkhof’s elements-of-faith section consulted directly; Lombard’s section is a bibliographic trail, not a verified page quotation."}]}, {"number": 2, "title": "What kind of book this is", "text": "The Bible names kings, cities, rivers, battles and years. Its history says: this happened, here, when this person was king. Its prayers and poetry grow out of that history too.\n\nMoses tells Israel why God showed them his works: “To you it was shown that you might know that Yahweh, He is God; there is no other besides Him.” (Deuteronomy 4:35 LSB)\n\nThe apostles make the same kind of claim about Jesus. Peter says, “For we did not make known to you the power and coming of our Lord Jesus Christ, following cleverly devised myths, but being eyewitnesses of His majesty.” (2 Peter 1:16 LSB) Paul puts the stakes plainly: “And if Christ has not been raised, your faith is worthless; you are still in your sins.” (1 Corinthians 15:17 LSB)\n\nChristian faith has put itself on the map. God brought a people out of Egypt, made promises in their history, and sent his Son into the world. Whether Jesus died and rose matters because Christianity says it really happened.\n\nGrisanti approaches archaeology from that confidence in God’s Word.[^grisanti] We can welcome a close look at its history and tell the truth about what we find.", "sources": [{"id": "grisanti", "label": "Michael A. Grisanti · archaeology and Scripture", "citation": "“Recent Archaeological Discoveries That Lend Credence to the Historicity of the Scriptures.” Journal of the Evangelical Theological Society 56/3 (2013): 475–497, especially 475–476.", "trail": "Also OT796: Old Testament Introduction, Spring 2026 course notes, printed pp. 162–168. Private notes are cited, not redistributed.", "note": "Grisanti begins with confidence in Scripture and explains how archaeology can confirm its historical setting and answer objections. This book follows that perspective without treating an individual artifact as the whole Christian case.", "url": "https://etsjets.org/wp-content/uploads/2013/10/files_JETS-PDFs_56_56-3_JETS_56-3_475-497_Grisanti.pdf", "consulted": "Published article consulted directly, along with the privately supplied notes."}]}, {"number": 3, "title": "What a spade can show", "text": "Archaeology can confirm that a biblical king lived, locate a city, illuminate a custom or show how early a manuscript existed. Randall Price and Wayne House define confirm as “to give new assurance of the validity of something.” That is a useful word for what these finds do.[^price]\n\nHezekiah’s tunnel is a good example. You can study a real water system and compare it with the king’s preparations in Scripture. The inscription records workers meeting as they cut through rock. The biblical account tells us whose kingdom was threatened and why Jerusalem needed water.[^siloam]\n\nRaymond Dillard and Tremper Longman remind us that stones need interpretation. The Bible supplies a narrative; the remains let us examine its world.[^dillard]\n\nThink of a witness in court whose street names, dates and descriptions keep checking out. Those agreements give you reasons to take the witness seriously. Greg Koukl makes the same point about Scripture’s historical reliability.[^koukl]\n\nRead an artifact for the claim it actually supports, then bring that finding into the larger case. The tunnel, the text and the history belong in the same investigation.", "sources": [{"id": "price", "label": "J. Randall Price and H. Wayne House · confirmation", "citation": "Zondervan Handbook of Biblical Archaeology. Grand Rapids: Zondervan, 2017, pp. 10, 194–200.", "trail": "Definition on p. 10 quoted in Grisanti, OT796 Notes, printed p. 162; discovery chart pp. 194–200 supplied by Geoff.", "note": "Their definition of confirmation is “to give new assurance of the validity of something.” The chart supplies the bullae, Gezer, Gath, En-Gedi and Lachish leads. Original reports below refine individual claims.", "url": "", "consulted": "Chart scans consulted directly; definition consulted through Grisanti. Scans and third-party images are not reproduced."}, {"id": "siloam", "label": "Amos Frumkin, Aryeh Shimron and Jeff Rosenbaum · Hezekiah’s tunnel", "citation": "“Radiometric dating of the Siloam Tunnel, Jerusalem.” Nature 425 (2003): 169–171. DOI 10.1038/nature01875.", "trail": "The tunnel/Siloam inscription example in Grisanti’s archaeology discussion; compare 2 Kings 20:20 and 2 Chronicles 32:30.", "note": "Radiocarbon and uranium-thorium dating place the waterwork in the Iron Age II period. The surviving inscription describes the meeting of the cutting teams, without naming the king.", "url": "https://pubmed.ncbi.nlm.nih.gov/12968177/", "consulted": "Original research abstract consulted directly; no scanned course illustrations are reused."}, {"id": "dillard", "label": "Raymond B. Dillard and Tremper Longman III · interpreting remains", "citation": "An Introduction to the Old Testament. Grand Rapids: Zondervan, 1994, p. 25.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 163.", "note": "Objects need interpretation, while a written narrative tells how its author understands events. Read material evidence and Scripture together rather than pretending either interpreter has no starting assumptions.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, {"id": "koukl", "label": "Gregory Koukl · questions and ambassadors", "citation": "Tactics: A Game Plan for Discussing Your Christian Convictions, updated and expanded edition. Zondervan, 2019; “Ancient Words, Ever True?” Stand to Reason.", "trail": "Columbo questions, the pebble-in-the-shoe image, gardening and knowledge/wisdom/character are credited to Koukl.", "note": "Questions invite a person to explain a claim. Offer truthful reasons with patience; the aim is persuasion rather than pressure.", "url": "https://www.str.org/w/ancient-words-ever-true-", "consulted": "Stand to Reason article consulted directly; the book is the fuller method reference."}]}, {"number": 4, "title": "Why so much is missing", "text": "Try an archaeologist’s arithmetic. Edwin Yamauchi pictured five losses between ancient life and the evidence we get to read.[^yamauchi]\n\nSuppose one-tenth survived, six-tenths of the sites were surveyed, one-fiftieth of those were excavated, one-tenth examined and half the results published:\n\n**1/10 × 6/10 × 1/50 × 1/10 × 1/2 = 6/100,000.**\n\nHis illustration leaves six parts in a hundred thousand: 0.006 percent. Think of a whole town, then the handful of pieces that reach a museum.\n\nCloth, leather and papyrus rot. Clay can survive a fire. Only a small part of many sites has been dug. Kings preferred victories on their monuments. People traveling with tents and flocks left lighter traces than palace builders. John Currid points out how incomplete the record is.[^currid]\n\nAsk whether something was likely to survive, whether anyone has looked in the right place and whether the result has been published. A missing object deserves that much thought.\n\nThe world we study is God’s world: “The heavens are telling of the glory of God;\nAnd the expanse is declaring the work of His hands.” (Psalm 19:1 LSB)\n\nEven a small surviving piece can help us recognize the people who lived in it.", "sources": [{"id": "yamauchi", "label": "Edwin M. Yamauchi · the fraction of surviving evidence", "citation": "The Stones and the Scriptures. J. B. Lippincott, 1972, pp. 146–157; calculation p. 156.", "trail": "Quoted in Grisanti, OT796 Notes, printed pp. 166–167 (PDF pp. 167–168).", "note": "This is a historical teaching estimate, not a measured percentage of today’s archaeological knowledge. Its five factors are 1/10 × 6/10 × 1/50 × 1/10 × 1/2 = 6/100,000 = 0.006%. Different questions have different survival and detection rates.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, {"id": "currid", "label": "John D. Currid · the incomplete record", "citation": "The Case for Biblical Archaeology: Uncovering the Historical Record of God’s Old Testament People. Phillipsburg, NJ: P&R, 2020, p. 6.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 166.", "note": "Currid describes archaeological evidence as fragmentary, piecemeal and incomplete. The four examples on the page summarize why traces can be lost; ancient rulers sometimes did record setbacks, so “never” would be too strong.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}]}, {"number": 5, "title": "The argument from silence", "text": "Imagine being told an ancient people were invented, then standing in their capital among thousands of their written records. Excavations begun at Boğazköy-Hattusa in 1906 brought the Hittite archives into view. A world that had become obscure could be studied in its own words.[^hittites]\n\nSargon’s palace at Khorsabad gave a setting to the Assyrian king named in Isaiah 20:1.[^beck] A monument at Tel Dan named David’s dynasty in an enemy’s boast.[^tel-dan]\n\nBelshazzar is another striking case. The Ur cylinder names him as Nabonidus’s son, and the Verse Account describes royal authority entrusted to the eldest son. That makes Daniel’s offer of third place intelligible: “he now would be the third powerful ruler in the kingdom.” (Daniel 5:29 LSB)[^belshazzar]\n\nIain Provan, V. Philips Long and Tremper Longman challenge a method that refuses to hear a biblical text until something outside it confirms every claim. Ask instead what the actual evidence gives us reason to believe.[^confidence]\n\nAlan Millard’s conclusion is worth remembering: “discovery after discovery points to the accuracy of biblical narrators.”[^millard] These discoveries give us good reasons to listen before dismissing an ancient account.", "sources": [{"id": "hittites", "label": "Jared L. Miller · the archives at Hattusa", "citation": "“The Tablet Finds of Temple I from the Early Excavations at Boğazköy-Hattusa (1906–1912).” In The Discovery of an Anatolian Empire, 2017.", "trail": "Hittite example also in Grisanti, OT796 Notes, printed pp. 150, 163.", "note": "The excavations began in 1906 and uncovered major archives. Distinguish evidence for the Hittite empire from the separate question of every biblical use of the name Hittite.", "url": "https://www.assyriologie.uni-muenchen.de/personen/professoren/miller/publ_miller/early_excavation_bogazkoy_2017.pdf", "consulted": "Original study’s archive overview consulted."}, {"id": "beck", "label": "John A. Beck · the historical setting", "citation": "The Baker Book of Bible Charts, Maps, and Time Lines. Grand Rapids: Baker Books, 2016, “Archaeology of the Old Testament,” pp. 126–135.", "trail": "Privately supplied excerpt from Geoff.", "note": "Entry 4, p. 126, is the Beni Hasan painting; entry 12, p. 128, is Merneptah; entry 21, p. 130, is Tel Dan. The chart is a doorway to the object records, not a set of images reused in the game.", "url": "", "consulted": "Supplied chart consulted directly; pages and photographs are not reproduced."}, {"id": "tel-dan", "label": "Avraham Biran and Joseph Naveh · House of David", "citation": "“An Aramaic Stele Fragment from Tel Dan.” Israel Exploration Journal 43 (1993): 81–98; “The Tel Dan Inscription: A New Fragment.” IEJ 45 (1995): 1–18.", "trail": "Grisanti appendix #96, citing Price and House p. 119; Beck, p. 130, entry 21.", "note": "The ninth-century Aramaic monument names the House of David. The enemy’s boast is evidence for a recognized dynasty. The fragment does not itself give the author’s name; attribution to Hazael is an interpretation.", "url": "https://ngsba.org/excavations/tel-dan/", "consulted": "Excavation project’s account consulted directly; IEJ articles remain the original-publication trail."}, {"id": "belshazzar", "label": "Nabonidus texts · Belshazzar’s place", "citation": "Nabonidus Cylinder from Ur (British Museum BM 91128); Verse Account of Nabonidus, column II, on authority entrusted to his eldest son.", "trail": "Grisanti, OT796 Notes, printed p. 150; appendix #76; Price and House, pp. 194–200.", "note": "The Ur cylinder names Belshazzar; the Verse Account describes delegated royal authority. This helps explain Daniel’s third place. Belshazzar’s precise legal title is a separate historical question. The Nabonidus Chronicle refers to the crown prince but is not the text that supplies his name.", "url": "https://www.britishmuseum.org/collection/object/W_1882-0714-1025", "consulted": "Text identifications checked through the supplied notes/appendix; museum collection link is for further reading."}, {"id": "confidence", "label": "Iain Provan, V. Philips Long and Tremper Longman III · hearing the text", "citation": "A Biblical History of Israel, 2nd ed. Louisville: Westminster John Knox, 2015, p. 250.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 167.", "note": "They question making external corroboration a condition before a biblical text may be taken seriously. Ask what evidence actually counts against a claim, as well as what confirms it.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, {"id": "millard", "label": "Alan Millard · details that survive scrutiny", "citation": "“Did the Patriarchs Meet Philistines?” In An Excellent Fortress for His Armies, a Refuge for the People: Egyptological, Archaeological, and Biblical Studies in Honor of James K. Hoffmeier. Eisenbrauns, 2020, p. 230.", "trail": "Quoted in Grisanti, OT796 Notes, printed pp. 167–168.", "note": "Millard writes that “discovery after discovery points to the accuracy of biblical narrators.” This is quoted through the notes, not presented as a newly inspected book page.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}]}, {"number": 6, "title": "Three questions to ask", "text": "When someone makes a claim about the Bible and archaeology, three questions will carry you a long way. Greg Koukl calls them the Columbo questions, after a television detective who solved cases by asking polite questions.[^koukl]\n\n**“What do you mean by that?”** If a friend says archaeology has disproved the Bible, ask which part. There may be a real question behind the headline.\n\n**“How did you come to that conclusion?”** Whoever makes a claim should give reasons for it. That goes for you too.\n\n**“Have you considered…?”** Now offer one relevant fact for your friend to think about. You might ask whether they have seen the inscription that names David’s house.\n\nListen to the answer. Your friend may have noticed something you missed. Then you can think about it together.\n\nKoukl pictures leaving a pebble in someone’s shoe: one true thing they keep noticing. A conversation can begin with that.", "sources": [{"id": "koukl", "label": "Gregory Koukl · questions and ambassadors", "citation": "Tactics: A Game Plan for Discussing Your Christian Convictions, updated and expanded edition. Zondervan, 2019; “Ancient Words, Ever True?” Stand to Reason.", "trail": "Columbo questions, the pebble-in-the-shoe image, gardening and knowledge/wisdom/character are credited to Koukl.", "note": "Questions invite a person to explain a claim. Offer truthful reasons with patience; the aim is persuasion rather than pressure.", "url": "https://www.str.org/w/ancient-words-ever-true-", "consulted": "Stand to Reason article consulted directly; the book is the fuller method reference."}]}, {"number": 7, "title": "Three kinds of sentence", "text": "Here is a useful habit for reading an inscription. Keep three kinds of sentence apart.\n\n**What the object is.** “This is a clay cylinder from Babylon, written after Cyrus took the city in 539 BC.”\n\n**What its maker claims.** “Cyrus says he restored shrines and returned communities to their settlements.”\n\n**The link we draw.** “That restoration policy fits the return described in Ezra.”[^cyrus]\n\nEzra records Cyrus saying that God “has appointed me to build him a house at Jerusalem in Judah.” (Ezra 1:2 CSB)\n\nThe cylinder describes restorations in Mesopotamia. Ezra gives us the decree concerning Jerusalem. Read them together for the connection they actually make: the Bible’s account fits the Persian king’s policy.[^cyrus]\n\nThat is a substantial claim. A friend can inspect both texts and see why you made it.", "sources": [{"id": "cyrus", "label": "Mordechai Cogan · the Cyrus Cylinder", "citation": "“Cyrus Cylinder (2.124).” In The Context of Scripture, ed. William W. Hallo and K. Lawson Younger Jr., vol. 2. Brill, 2000, pp. 315–316, lines 20–36.", "trail": "Translation excerpt in Grisanti, OT796 appendix #87; Price and House, p. 198.", "note": "The text describes restoring shrines and communities in Mesopotamia. It supplies a restoration policy parallel; Ezra identifies its application to Jerusalem. It does not name the Jews.", "url": "https://www.britishmuseum.org/collection/object/W_1880-0617-1941", "consulted": "Cogan excerpt consulted through appendix #87; the museum page refused automated retrieval in this review."}]}, {"number": 8, "title": "Hostile witnesses", "text": "A witness who has no wish to help your case can be especially interesting.\n\nThe Aramean monument at Tel Dan names the House of David while boasting about defeated kings.[^tel-dan] Mesha of Moab names Omri and Israel while celebrating his own god.[^mesha]\n\nShalmaneser’s Kurkh Monolith lists Ahab of Israel among his opponents at Qarqar.[^kurkh] His Black Obelisk later names Jehu’s tribute. The Jehu whom Scripture introduces with “I anoint you king over Israel.” (2 Kings 9:3 CSB) also appears in Assyria’s records.[^obelisk]\n\nSennacherib names Hezekiah of Judah and says he confined him in Jerusalem like a bird in a cage. The annals describe tribute; they claim no capture of Jerusalem.[^sennacherib] The bird remains in the cage, in his own telling.\n\nThese kings were advertising themselves. Along the way, their monuments locate biblical rulers in the political world Scripture describes. Omri, Ahab, Jehu and Hezekiah become people we can meet in more than one nation’s records.", "sources": [{"id": "tel-dan", "label": "Avraham Biran and Joseph Naveh · House of David", "citation": "“An Aramaic Stele Fragment from Tel Dan.” Israel Exploration Journal 43 (1993): 81–98; “The Tel Dan Inscription: A New Fragment.” IEJ 45 (1995): 1–18.", "trail": "Grisanti appendix #96, citing Price and House p. 119; Beck, p. 130, entry 21.", "note": "The ninth-century Aramaic monument names the House of David. The enemy’s boast is evidence for a recognized dynasty. The fragment does not itself give the author’s name; attribution to Hazael is an interpretation.", "url": "https://ngsba.org/excavations/tel-dan/", "consulted": "Excavation project’s account consulted directly; IEJ articles remain the original-publication trail."}, {"id": "mesha", "label": "André Lemaire · Mesha’s monument", "citation": "“House of David Restored in Moabite Inscription.” Biblical Archaeology Review 20/3 (May/June 1994): 30–37.", "trail": "Mesha and Omri: Beck chart; Grisanti’s archaeology discussion.", "note": "Mesha names Omri and Israel securely. Lemaire’s House of David restoration on the damaged Mesha line is a separate debated reading; this page does not rely on it.", "url": "https://collections.louvre.fr/en/ark:/53355/cl010120339", "consulted": "Louvre collection record consulted directly; Lemaire’s article remains the original-publication trail for the distinct proposed David reading."}, {"id": "kurkh", "label": "Ahab at Qarqar · Assyrian royal text", "citation": "Kurkh Monolith of Shalmaneser III; The Context of Scripture, vol. 2, pp. 263–264; British Museum BM 118884.", "trail": "Grisanti’s Assyrian-history discussion; Price and House discovery chart.", "note": "The annal lists Ahab of Israel among the coalition at Qarqar in 853 BC. Its troop totals are a royal claim; the named ruler is the point used here.", "url": "https://www.britishmuseum.org/collection/object/W_1863-0704-1", "consulted": "Object/text trail through the supplied sources; no claim of obtaining the full Context of Scripture volume."}, {"id": "obelisk", "label": "Shalmaneser III · Jehu’s tribute", "citation": "Black Obelisk, British Museum BM 118885; translation in Ancient Near Eastern Texts Relating to the Old Testament, ed. James B. Pritchard, 3rd ed., p. 281.", "trail": "Grisanti appendix #82, citing Alfred Hoerth, Archaeology and the Old Testament, p. 322.", "note": "The tribute register names Jehu in 841 BC. The kneeling figure may be Jehu or his envoy. Assyrian “son of Omri” identifies Israel’s royal house/land, not Jehu’s biological father.", "url": "https://oracc.museum.upenn.edu/nimrud/livesofobjects/blackobelisk/index.html", "consulted": "University of Pennsylvania’s Nimrud project account consulted; ANET/Hoerth are the publication trail."}, {"id": "sennacherib", "label": "Sennacherib · the Jerusalem campaign", "citation": "Sennacherib’s annals, third campaign (701 BC), including the Taylor Prism, British Museum BM 91032.", "trail": "Grisanti appendix #82–84; Beck’s Old Testament archaeology chart.", "note": "The annals name Hezekiah and describe confining him in Jerusalem. They report tribute, not the capture of the city. Compare 2 Kings 18–19 and Isaiah 36–37.", "url": "https://www.britishmuseum.org/collection/object/W_1855-1003-1", "consulted": "Campaign text consulted in the supplied appendix; do not turn the bird-in-a-cage illustration into a claim about every detail of the siege."}]}, {"number": 9, "title": "“The Bible was written late”", "text": "Could Israel have written its history down early? Writing was already being used for records, laws and literature long before its monarchy. Ebla had a major written archive centuries before the usual dates proposed for Abraham. Kenneth Kitchen shows how ordinary the use of writing was when ancient people wanted to preserve something.[^writing]\n\nThen look at the details. Kitchen compares Joseph’s twenty shekels with slave prices in the early second millennium.[^kitchen] Such a small detail fits the story’s setting.\n\nOr look at two lumps of clay. Eilat Mazar’s excavations found seal impressions naming Jehucal son of Shelemiah and Gedaliah son of Pashhur. Both men appear among Jeremiah’s opponents in Jeremiah 38:1. The names and the fathers match.[^bullae] Price and House put these finds together in their discovery chart.[^price]\n\nMichael Jursa also recognized a Babylonian tablet naming an official commonly identified with Jeremiah’s Nebo-Sarsekim. The name and title fit the period.[^nebo]\n\nA writer remembering real officials leaves details a bare legend does not need. These discoveries give us something specific to check, and the names keep leading us back into Jeremiah’s world.", "sources": [{"id": "writing", "label": "Kenneth A. Kitchen · writing in the ancient world", "citation": "Ancient Orient and Old Testament. London: Tyndale Press, 1966, p. 136.", "trail": "Cited in Grisanti, OT796 Notes, printed p. 114; Ebla is also discussed in the notes.", "note": "Writing was used to preserve legal, administrative and literary material long before Israel’s monarchy. This rebuts the claim that early recording was impossible; particular books and passages require their own evidence.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, {"id": "kitchen", "label": "Kenneth A. Kitchen · prices and literary setting", "citation": "On the Reliability of the Old Testament. Grand Rapids: Eerdmans, 2003, pp. 344–345 (slave prices), and the treaty/covenant discussion.", "trail": "Kitchen is a recommended source in Grisanti’s notes; the specific price discussion is a publication trail.", "note": "Kitchen compares Joseph’s twenty shekels with early-second-millennium prices. Use it as contextual agreement, rather than a claim that no other price or later knowledge was possible.", "url": "", "consulted": "Kitchen’s original pp. 344–345 were not obtained; the page locator is supplied as further reading, not a direct quotation."}, {"id": "bullae", "label": "Eilat Mazar and Reut Livyatan Ben-Arie · Jeremiah’s officials", "citation": "“Hebrew and Non-Indicative Bullae.” In The Summit of the City of David Excavations 2005–2008: Final Reports, vol. I: Area G, ed. Eilat Mazar. Jerusalem: Old City Press, 2015, pp. 299–362.", "trail": "Price and House, p. 194, supplies the two named seals; Jeremiah 38:1 supplies the comparison.", "note": "Jehucal son of Shelemiah was found in 2005; Gedaliah son of Pashhur in 2008. Their names and fathers match the officials in Jeremiah. Those are the excavation dates, rather than the chart’s 2010/2017 entries.", "url": "https://www.academia.edu/19515093/Hebrew_and_Non_Indicative_Bullae_from_The_Summit_of_the_City_of_David", "consulted": "Authors’ posted report introduction consulted; chapter title, pages and 2005/2008 context checked against excavation-project records."}, {"id": "price", "label": "J. Randall Price and H. Wayne House · confirmation", "citation": "Zondervan Handbook of Biblical Archaeology. Grand Rapids: Zondervan, 2017, pp. 10, 194–200.", "trail": "Definition on p. 10 quoted in Grisanti, OT796 Notes, printed p. 162; discovery chart pp. 194–200 supplied by Geoff.", "note": "Their definition of confirmation is “to give new assurance of the validity of something.” The chart supplies the bullae, Gezer, Gath, En-Gedi and Lachish leads. Original reports below refine individual claims.", "url": "", "consulted": "Chart scans consulted directly; definition consulted through Grisanti. Scans and third-party images are not reproduced."}, {"id": "nebo", "label": "Michael Jursa · Nabû-šarrussu-ukīn", "citation": "“Nabû-šarrussu-ukīn, rab ša-rēši, und ‘Nebusarsekim’ (Jer. 39,3).” Nouvelles Assyriologiques Brèves et Utilitaires 2008/1, no. 5, pp. 9–10; tablet BM 114789.", "trail": "Grisanti, OT796 Notes, printed p. 150; appendix #75.", "note": "The tablet names an official with a matching title, commonly identified with Jeremiah’s Nebo-Sarsekim. It records a temple payment; it is not a Babylonian copy of the siege narrative.", "url": "https://sepoa.fr/wp/wp-content/uploads/2012/06/2008-1.pdf", "consulted": "Original NABU issue and scholarly publication record checked; Jursa’s no. 5 appears on pp. 9–10. The supplied notes provide the biblical connection."}]}, {"number": 10, "title": "“The stories were borrowed”", "text": "The Babylonians had a flood account with a boat and birds. They also had law collections older than Moses.[^beck] Does similarity make Genesis and Exodus copies?\n\nAsk how that conclusion follows. Two accounts might share an older tradition, remember an event, or answer one another. Look at the actual comparison before deciding.\n\nIn Gilgamesh the gods quarrel and crowd round the sacrifice like flies. Genesis describes one God judging human evil and making a covenant with his creation.[^gilgamesh] The difference tells us something important about what the biblical writer is saying.\n\nKitchen also compares Israel’s covenant with second-millennium treaties: a ruler’s history with his people, obligations, witnesses, blessings and curses. Grisanti draws attention to that historical shape.[^treaties]\n\nIsrael speaks in the forms of its world, while proclaiming that the LORD alone is God. Those ancient connections help us hear the Bible more clearly.", "sources": [{"id": "beck", "label": "John A. Beck · the historical setting", "citation": "The Baker Book of Bible Charts, Maps, and Time Lines. Grand Rapids: Baker Books, 2016, “Archaeology of the Old Testament,” pp. 126–135.", "trail": "Privately supplied excerpt from Geoff.", "note": "Entry 4, p. 126, is the Beni Hasan painting; entry 12, p. 128, is Merneptah; entry 21, p. 130, is Tel Dan. The chart is a doorway to the object records, not a set of images reused in the game.", "url": "", "consulted": "Supplied chart consulted directly; pages and photographs are not reproduced."}, {"id": "gilgamesh", "label": "The flood tablet · Nineveh", "citation": "Epic of Gilgamesh, Tablet XI; British Museum BM 120054 (K.3375).", "trail": "Beck, p. 126, entry 1; Grisanti, OT796 Notes, printed p. 149.", "note": "A shared flood, vessel and birds invite comparison. Distinguish Gilgamesh XI from Atrahasis, where human noise is especially explicit; this book does not merge those accounts.", "url": "https://www.britishmuseum.org/collection/object/W_K-3375", "consulted": "Object and story comparison checked through the supplied sources."}, {"id": "treaties", "label": "Kenneth A. Kitchen · ancient treaty forms", "citation": "On the Reliability of the Old Testament (2003), discussion of second-millennium treaty/covenant structures.", "trail": "Grisanti, OT796 Notes, printed p. 150.", "note": "Historical prologue, obligations, witnesses and sanctions have second-millennium parallels. These are positive setting comparisons, not a stand-alone timestamp for a whole biblical book.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}]}, {"number": 11, "title": "The hardest case: the Exodus", "text": "Israel taught its children to remember a real deliverance: “We were slaves to Pharaoh in Egypt, and Yahweh brought us from Egypt with a strong hand.” (Deuteronomy 6:21 LSB)\n\nExodus puts their work in named places: “So they appointed taskmasters over them to afflict them with hard labors. And they built for Pharaoh storage cities, Pithom and Raamses.” (Exodus 1:11 LSB) The eastern Delta was a real setting for people from Canaan and for the city of Raamses.[^delta]\n\nBeck’s chart also points to the Beni Hasan painting, about 1892 BC. It shows a group from the Levant entering Egypt with distinctive clothes and goods. The travel, trade and dress belong to the world in which Genesis places the patriarchs.[^beck]\n\nThen comes a firm landmark: Merneptah’s stele names **Israel as a people in Canaan by about 1208 BC**. Whatever Exodus date you hold, Israel was already in the land by then.[^merneptah]\n\nThere is still no Egyptian account of Moses and the plagues. Read that silence alongside the fragile Delta record, the limits of royal propaganda and the positive setting evidence.[^grisanti]\n\nIsrael remembered being enslaved, then rescued by the LORD. Its national beginning puts God’s mercy, rather than its own greatness, at the center. The setting fits, and the memory calls us to worship the God who brings his people out.", "sources": [{"id": "delta", "label": "Austrian Archaeological Institute · Avaris and Pi-Ramesse", "citation": "Tell el-Dabʿa / Avaris, excavation-project history, Austrian Archaeological Institute, Austrian Academy of Sciences; Manfred Bietak, Avaris: The Capital of the Hyksos (British Museum Press, 1996).", "trail": "The Egyptian-setting discussion in Grisanti and the original-concept Avaris study.", "note": "The excavated eastern Delta sites show Levantine settlement and the later Ramesside capital around Tell el-Dabʿa/Qantir. These identify a historical setting for Exodus, while the biblical account supplies the named deliverance.", "url": "https://www.oeaw.ac.at/en/oeai/institute/branches/cairo/excavations-projects/tell-el-dab%CA%BFa", "consulted": "Excavation institution’s published project history consulted directly; Bietak’s book is the fuller publication trail."}, {"id": "beck", "label": "John A. Beck · the historical setting", "citation": "The Baker Book of Bible Charts, Maps, and Time Lines. Grand Rapids: Baker Books, 2016, “Archaeology of the Old Testament,” pp. 126–135.", "trail": "Privately supplied excerpt from Geoff.", "note": "Entry 4, p. 126, is the Beni Hasan painting; entry 12, p. 128, is Merneptah; entry 21, p. 130, is Tel Dan. The chart is a doorway to the object records, not a set of images reused in the game.", "url": "", "consulted": "Supplied chart consulted directly; pages and photographs are not reproduced."}, {"id": "merneptah", "label": "Michael G. Hasel · Israel in Canaan", "citation": "“Israel in the Merneptah Stela.” Bulletin of the American Schools of Oriental Research 296 (1994): 45–61, DOI 10.2307/1357179; also Hasel’s discussion in Critical Issues in Early Israelite History (2008), p. 52.", "trail": "Grisanti appendix #79; Beck, p. 128, entry 12; notes printed p. 151.", "note": "The text names Israel as a people in Canaan around 1208 BC. This is the widely accepted inscriptional reference used here.", "url": "https://doi.org/10.2307/1357179", "consulted": "Publisher abstract and supplied appendix consulted; the full 1994 article was not obtained."}, {"id": "grisanti", "label": "Michael A. Grisanti · archaeology and Scripture", "citation": "“Recent Archaeological Discoveries That Lend Credence to the Historicity of the Scriptures.” Journal of the Evangelical Theological Society 56/3 (2013): 475–497, especially 475–476.", "trail": "Also OT796: Old Testament Introduction, Spring 2026 course notes, printed pp. 162–168. Private notes are cited, not redistributed.", "note": "Grisanti begins with confidence in Scripture and explains how archaeology can confirm its historical setting and answer objections. This book follows that perspective without treating an individual artifact as the whole Christian case.", "url": "https://etsjets.org/wp-content/uploads/2013/10/files_JETS-PDFs_56_56-3_JETS_56-3_475-497_Grisanti.pdf", "consulted": "Published article consulted directly, along with the privately supplied notes."}]}, {"number": 12, "title": "When Christians disagree", "text": "Christians who trust the Bible disagree about when the Exodus happened. Here is the text behind the early date: “in the four hundred and eightieth year after the sons of Israel came out of the land of Egypt” (1 Kings 6:1 LSB).\n\nEarly-date scholars count back 480 years from Solomon’s fourth year, commonly dated around 966 BC, and arrive at about 1446 BC. Many late-date scholars read the number as twelve generations and connect the city-name Raamses with a thirteenth-century setting, often around 1260 BC. Grisanti firmly favors the early date. He calls this an **intramural** debate: an argument within evangelical scholarship, rather than a simple contest between believers and unbelievers.[^exodus-date]\n\nA smaller group sees patterns at Avaris and elsewhere and proposes revising Egypt’s timeline. That proposal asks readers to reconsider many connected dates; the Investigation room gives it a place to be examined.[^exodus-date]\n\nCompare the reasons for each view and the evidence it must explain. People who agree that an event happened can still argue about its date.\n\nYou can trust Scripture while learning why fellow Christians read a chronological question differently. The deliverance they are discussing remains a reason to thank God.", "sources": [{"id": "exodus-date", "label": "Bruce K. Waltke and Eugene H. Merrill · Exodus/conquest dating", "citation": "Waltke, “Palestinian Artifactual Evidence Supporting the Early Date of the Exodus,” Bibliotheca Sacra 129 (1972): 33–47. Merrill, “Palestinian Archaeology and the Date of the Conquest: Do Tells Tell Tales?,” Grace Theological Journal 3/1 (1982): 107–121.", "trail": "Grisanti, OT796 Notes, printed pp. 139, 154–155; appendix #60.", "note": "Grisanti favors the early date and calls the chronology an intramural evangelical debate. The revised Egyptian timeline is a minority proposal; it should be compared with the full set of chronological anchors.", "url": "https://www.galaxie.com/article/gtj03-1-07", "consulted": "Merrill’s published opening argument and both bibliographic records consulted; Grisanti’s discussion consulted directly."}]}, {"number": 13, "title": "Patterns and paradigms", "text": "A paradigm is a shared picture of how the evidence fits together. Historian of science Thomas Kuhn explained how such frameworks guide the questions researchers ask and the puzzles they work on.[^kuhn]\n\nHere is what one historical judgment sounds like. Ronald Hendel wrote that archaeology had “secured the non-historicity of much of the Bible before the era of the kings.” Grisanti quotes that conclusion and then tests it against particular finds.[^hendel]\n\nThat is more useful than arguing about whether scholars are good or bad people. Grisanti also distinguishes several positions among non-evangelical scholars. Disagreeing with us does not make someone a minimalist.[^grisanti]\n\nA majority can be wrong. A minority can be wrong. Ask which explanation fits the evidence, including the facts its defenders find awkward.\n\nHold your view with the courage to examine it and the patience to hear another person’s reasons. A difficult question can lead to a better understanding of the history God has given us.", "sources": [{"id": "kuhn", "label": "Thomas S. Kuhn · paradigms", "citation": "The Structure of Scientific Revolutions. University of Chicago Press, 1962; later editions.", "trail": "Used as an analogy for historical interpretation, alongside Grisanti’s discussion of scholarly assumptions.", "note": "A paradigm is a framework for questions and evidence. Kuhn is not evidence that experts never change their minds or that a disliked theory is therefore right.", "url": "", "consulted": "Bibliographic method reference; no direct quotation from Kuhn is used."}, {"id": "hendel", "label": "Ronald S. Hendel · a historical claim to test", "citation": "“Is There a Biblical Archaeology?” Biblical Archaeology Review 32/4 (July/August 2006): 20.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 164, and in Grisanti, JETS 56/3 (2013), p. 475.", "note": "The quotation gives the conclusion some scholars reach. Grisanti argues against it with particular finds; he also distinguishes different non-evangelical positions rather than calling all of them minimalists.", "url": "https://etsjets.org/wp-content/uploads/2013/10/files_JETS-PDFs_56_56-3_JETS_56-3_475-497_Grisanti.pdf", "consulted": "Hendel’s passage consulted through Grisanti’s published quotation, not the full BAR issue."}, {"id": "grisanti", "label": "Michael A. Grisanti · archaeology and Scripture", "citation": "“Recent Archaeological Discoveries That Lend Credence to the Historicity of the Scriptures.” Journal of the Evangelical Theological Society 56/3 (2013): 475–497, especially 475–476.", "trail": "Also OT796: Old Testament Introduction, Spring 2026 course notes, printed pp. 162–168. Private notes are cited, not redistributed.", "note": "Grisanti begins with confidence in Scripture and explains how archaeology can confirm its historical setting and answer objections. This book follows that perspective without treating an individual artifact as the whole Christian case.", "url": "https://etsjets.org/wp-content/uploads/2013/10/files_JETS-PDFs_56_56-3_JETS_56-3_475-497_Grisanti.pdf", "consulted": "Published article consulted directly, along with the privately supplied notes."}]}, {"number": 14, "title": "Did Jericho’s walls fall?", "text": "Joshua’s account gives us things to look for: the wall “fell down beneath itself,” (Joshua 6:20 LSB) and the city was destroyed: “But they burned the city with fire, and all that was in it.” (Joshua 6:24 LSB)\n\nAt Jericho, excavators found collapsed fortifications, a fierce fire and stores of burnt grain. Bryant Wood argues that the destruction fits Joshua’s description: a sudden capture, little time to use the stored food, and a city burned rather than plundered for its supplies.[^jericho]\n\nThe argument is over the date. Kathleen Kenyon placed the major destruction around 1550 BC; Wood argues for about 1400 BC. Most radiocarbon results support the earlier destruction. That question connects with the Exodus chronology on page 12. Grisanti includes Jericho among the difficult cases Christians should study honestly.[^jericho]\n\nA fair way to put it is: the ruins at Jericho show striking features like Joshua’s account; deciding which destruction belongs to Joshua requires the dating work too.\n\nOpen the report, compare the pottery and dates, and take the biblical description seriously enough to do the work.", "sources": [{"id": "jericho", "label": "Bryant G. Wood; Hendrik J. Bruins and Johannes van der Plicht · Jericho’s destruction", "citation": "“Did the Israelites Conquer Jericho? A New Look at the Archaeological Evidence.” Biblical Archaeology Review 16/2 (March/April 1990): 44–58. Bruins and van der Plicht, “Tell es-Sultan (Jericho): Radiocarbon results of short-lived cereal and multiyear charcoal samples from the end of the Middle Bronze Age,” Radiocarbon 37/2 (1995): 213–220, DOI 10.1017/S0033822200030666.", "trail": "Grisanti, OT796 Notes, printed pp. 154, 164; his JETS article pp. 477–480 surveys Kenyon, Wood and the dating disagreement.", "note": "Wood argues for an early-conquest date; Kathleen Kenyon dated the major destruction to around 1550 BC, and most radiocarbon work favors the earlier destruction. Compare the dating arguments as well as the dramatic visible match.", "url": "https://biblearchaeology.org/research-articles/did-the-israelites-conquer-jericho-a-new-look-at-the-archaeological-evidence/", "consulted": "Wood’s published argument, the radiocarbon study’s published abstract/record and Grisanti’s discussion consulted. This remains a debated identification."}]}, {"number": 15, "title": "Was David a small-town chief?", "text": "The Tel Dan inscription gives us an enemy’s reference to David’s dynasty. The discussion has moved on to the reach of that kingdom.[^tel-dan]\n\nKhirbet Qeiyafa, near the Valley of Elah, has substantial fortifications and an inscription from around the early tenth century BC. Garfinkel, Ganor and Hasel see evidence of organized government in this period.[^qeiyafa]\n\nGezer adds another line of inquiry. Price and House point to Steve Ortiz’s palace excavation.[^price] A later radiocarbon study by Lyndelle Webster and colleagues places major building and administration there in the tenth century. That gives the discussion of Solomon’s building projects fresh evidence to consider.[^gezer]\n\nAt Gath, Aren Maeir’s team uncovered monumental fortifications and a gate in the Philistine city Scripture calls Goliath’s home. This was a world of substantial cities and competing kingdoms.[^gath]\n\nBaruch Halpern makes an important point: large public buildings can indicate a state, but “the absence of such buildings does not indicate the lack of a state.”[^halpern]\n\nJerusalem has been occupied and rebuilt for millennia. Read the surviving buildings for what they reveal, and compare the rival historical explanations. David’s dynasty and its neighbors belong to a real, increasingly visible world.", "sources": [{"id": "tel-dan", "label": "Avraham Biran and Joseph Naveh · House of David", "citation": "“An Aramaic Stele Fragment from Tel Dan.” Israel Exploration Journal 43 (1993): 81–98; “The Tel Dan Inscription: A New Fragment.” IEJ 45 (1995): 1–18.", "trail": "Grisanti appendix #96, citing Price and House p. 119; Beck, p. 130, entry 21.", "note": "The ninth-century Aramaic monument names the House of David. The enemy’s boast is evidence for a recognized dynasty. The fragment does not itself give the author’s name; attribution to Hazael is an interpretation.", "url": "https://ngsba.org/excavations/tel-dan/", "consulted": "Excavation project’s account consulted directly; IEJ articles remain the original-publication trail."}, {"id": "qeiyafa", "label": "Yosef Garfinkel, Saar Ganor and Michael Hasel · Khirbet Qeiyafa", "citation": "“The Contribution of Khirbet Qeiyafa to Our Understanding of the Iron Age Period.” Strata 28 (2010): 43–52; Misgav, Garfinkel and Ganor, “The Ostracon,” in Khirbet Qeiyafa Vol. 1 (2009), pp. 243–257.", "trail": "Grisanti, JETS 56/3 (2013), pp. 490–493 and notes 104–119; OT796 appendix #94–95.", "note": "Fortifications, radiocarbon dates and a written ostracon put organized activity near the Valley of Elah around the early tenth century. Political identity and the ostracon’s exact reading are debated.", "url": "https://etsjets.org/wp-content/uploads/2013/10/files_JETS-PDFs_56_56-3_JETS_56-3_475-497_Grisanti.pdf", "consulted": "Original titles and findings traced through Grisanti’s published discussion; full excavation volumes were not obtained."}, {"id": "price", "label": "J. Randall Price and H. Wayne House · confirmation", "citation": "Zondervan Handbook of Biblical Archaeology. Grand Rapids: Zondervan, 2017, pp. 10, 194–200.", "trail": "Definition on p. 10 quoted in Grisanti, OT796 Notes, printed p. 162; discovery chart pp. 194–200 supplied by Geoff.", "note": "Their definition of confirmation is “to give new assurance of the validity of something.” The chart supplies the bullae, Gezer, Gath, En-Gedi and Lachish leads. Original reports below refine individual claims.", "url": "", "consulted": "Chart scans consulted directly; definition consulted through Grisanti. Scans and third-party images are not reproduced."}, {"id": "gezer", "label": "Lyndelle C. Webster and colleagues · dating Gezer", "citation": "“The chronology of Gezer from the end of the late bronze age to iron age II: A meeting point for radiocarbon, archaeology egyptology and the Bible.” PLOS ONE 18/11 (2023): e0293119. DOI 10.1371/journal.pone.0293119.", "trail": "Extends the Gezer lead in Price and House, p. 194 (Ortiz’s excavations).", "note": "The excavators’ radiocarbon model places major building/administrative development in the tenth century. It is evidence to weigh alongside 1 Kings 9; the building does not carry Solomon’s name.", "url": "https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0293119", "consulted": "Original open-access research article consulted directly; the study’s conclusions remain scholarly interpretations, not an inscription naming its builder."}, {"id": "gath", "label": "Aren M. Maeir · Gath’s fortifications", "citation": "“Can Material Evidence of the Arameans Be Found in Philistia? The Case of Gath of the Philistines.” In Wandering Arameans, LAOS 5, 2017.", "trail": "Price and House, p. 194, Gath gate row; compare 1 Samuel 17:4.", "note": "The 2015 gate/fortification discovery belongs to Iron IIA, in the tenth/ninth-century city. Gath is a Philistine neighbor, not evidence that David ruled that city.", "url": "https://lisa.biu.ac.il/sites/lisa/files/shared/maeir_can_material_evidence_of_arameans_be_found_berlejung_et_al_eds_wandering_arameans_laos_5_2017_0.pdf", "consulted": "Excavator’s published description of the 2015 fortification discovery consulted."}, {"id": "halpern", "label": "Baruch Halpern · what missing buildings mean", "citation": "“The United Monarchy: David between Saul and Solomon.” In The Old Testament in Archaeology and History, 2017, p. 344.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 168 (the brief listed p. 167).", "note": "Halpern’s point is asymmetrical: public buildings can support a state, while their absence need not show that there was none. Quotation is reproduced through Grisanti, not claimed as independent access to the chapter.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}]}, {"number": 16, "title": "Has the text been changed?", "text": "“The Bible has been copied so many times that we cannot know what it said.” How would you test that? Compare the copies.\n\nThe Great Isaiah Scroll was copied around 125 BC. It lets us read the same recognizable book roughly a thousand years before the great medieval Hebrew manuscripts. Chapter 53 is already there.[^isaiah]\n\nEn-Gedi adds a remarkable comparison. A burned scroll looked like charcoal until computer imaging let researchers read inside it. Work announced in 2015 was published in 2016: the recovered Leviticus text agrees with the medieval consonantal text. Brent Seales’s team could inspect the writing without pulling the fragile scroll apart.[^engedi]\n\nThe Ketef Hinnom silver amulets take us earlier still, to the late seventh or early sixth century BC. They preserve blessing language overlapping Numbers 6:24–26, among the oldest surviving biblical wording.[^ketef]\n\nCompare the variants openly; spelling and some wording do differ between manuscripts. Having the copies lets us inspect how faithfully the text was carried forward.[^isaiah]\n\n“The grass withers, the flower fades,\nBut the word of our God stands forever.” (Isaiah 40:8 LSB)\n\nThe words were carried through real hands, and we can still read them.", "sources": [{"id": "isaiah", "label": "Israel Museum · the Great Isaiah Scroll", "citation": "The Great Isaiah Scroll, 1QIsaᵃ, Shrine of the Book; exhibition guide.", "trail": "Grisanti appendix #100; compare Paul D. Wegner, A Student’s Guide to Textual Criticism of the Bible (IVP Academic, 2006).", "note": "Copied around 125 BC, this is the same recognizable book, including chapter 53, before Christianity. Its many variants are published openly; stability does not require identical spelling or wording at every point.", "url": "https://www.imj.org.il/sites/default/files/IMJ%20Great%20Isaiah%20Scroll%20Exhibition.pdf", "consulted": "Museum presentation consulted; Wegner is further reading, not a newly obtained quotation."}, {"id": "engedi", "label": "William Brent Seales and colleagues · virtual unwrapping", "citation": "“From damage to discovery via virtual unwrapping: Reading the scroll from En-Gedi.” Science Advances 2/9 (2016): e1601247. DOI 10.1126/sciadv.1601247.", "trail": "Price and House, p. 194, notes the initial 2015 decipherment; full publication followed in 2016.", "note": "The recovered Leviticus text agrees with the medieval consonantal text. It is a preserved portion, not every verse of Leviticus or later vowel signs.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5031465/", "consulted": "Original open-access research article consulted directly."}, {"id": "ketef", "label": "Gabriel Barkay, Marilyn J. Lundberg, Andrew G. Vaughn and Bruce Zuckerman · silver amulets", "citation": "“The Amulets from Ketef Hinnom: A New Edition and Evaluation.” BASOR 334 (2004): 41–71. DOI 10.2307/4150106.", "trail": "Grisanti, OT796 Notes, printed p. 52; the Investigation room has a study version.", "note": "Late-seventh/early-sixth-century BC silver amulets preserve blessing language overlapping Numbers 6:24–26, among the earliest surviving biblical wording. They are not a complete scroll of Numbers.", "url": "https://doi.org/10.2307/4150106", "consulted": "Publisher abstract consulted; full paper not obtained."}]}, {"number": 17, "title": "Written before it happened", "text": "Isaiah describes the suffering servant in words Christians recognize at the cross:\n\n“But He was pierced through for our transgressions,\nHe was crushed for our iniquities;\nThe chastening for our peace fell upon Him,\nAnd by His wounds we are healed. All of us like sheep have gone astray,\nEach of us has turned to his own way;\nBut Yahweh has caused the iniquity of us all\nTo fall on Him.” (Isaiah 53:5–6 LSB)\n\nThe Great Isaiah Scroll contains this passage in a copy made more than a century before Jesus was born. The words were already on the page. They were not added after the crucifixion.[^isaiah]\n\nIsaiah presents God’s challenge to the idols: “Declare the things that are to come afterward,\nThat we may know that you are gods” (Isaiah 41:23 LSB).\n\nThe scroll settles **when** these words existed. To see **who** fulfills them, read the servant’s suffering, death and vindication alongside the accounts of Jesus. Read Acts 8 too: Philip begins with this very passage and tells the traveler the good news about Jesus.\n\nThe dating and the fulfillment belong together. An ancient page invites us to recognize the Savior it describes.", "sources": [{"id": "isaiah", "label": "Israel Museum · the Great Isaiah Scroll", "citation": "The Great Isaiah Scroll, 1QIsaᵃ, Shrine of the Book; exhibition guide.", "trail": "Grisanti appendix #100; compare Paul D. Wegner, A Student’s Guide to Textual Criticism of the Bible (IVP Academic, 2006).", "note": "Copied around 125 BC, this is the same recognizable book, including chapter 53, before Christianity. Its many variants are published openly; stability does not require identical spelling or wording at every point.", "url": "https://www.imj.org.il/sites/default/files/IMJ%20Great%20Isaiah%20Scroll%20Exhibition.pdf", "consulted": "Museum presentation consulted; Wegner is further reading, not a newly obtained quotation."}]}, {"number": 18, "title": "The Bible does not flatter", "text": "Kings liked a glorious public image. Victory looked good on a palace wall. The Old Testament tells a far more searching history: Abraham lies, David commits adultery and murder, Solomon worships idols, and the nation is judged for its sins.\n\nIts writers put God’s holiness above their people’s reputation. That is a reason to listen when they describe failure as well as achievement.\n\nThe ground shows the religious conflict too. Price and House highlight a shrine in Lachish’s city gate. Its altar horns were cut off, and a stone latrine was placed in its inner room.[^price] Excavators Sa’ar Ganor and Igor Kreimerman interpret the desecration as connected with Hezekiah’s reforms in 2 Kings 18:4.[^lachish]\n\nHere are traces of the worship the prophets condemned, and of deliberate action against it. The biblical accounts speak into the same contested religious world.\n\nGod’s people needed correction and mercy. Scripture tells that truth about them so that we, too, can turn to the God who forgives and restores.", "sources": [{"id": "price", "label": "J. Randall Price and H. Wayne House · confirmation", "citation": "Zondervan Handbook of Biblical Archaeology. Grand Rapids: Zondervan, 2017, pp. 10, 194–200.", "trail": "Definition on p. 10 quoted in Grisanti, OT796 Notes, printed p. 162; discovery chart pp. 194–200 supplied by Geoff.", "note": "Their definition of confirmation is “to give new assurance of the validity of something.” The chart supplies the bullae, Gezer, Gath, En-Gedi and Lachish leads. Original reports below refine individual claims.", "url": "", "consulted": "Chart scans consulted directly; definition consulted through Grisanti. Scans and third-party images are not reproduced."}, {"id": "lachish", "label": "Sa’ar Ganor and Igor Kreimerman · the gate shrine", "citation": "“An Eighth-Century b.c.e. Gate Shrine at Tel Lachish, Israel.” BASOR 381 (2019): 211–236. DOI 10.1086/703343.", "trail": "Price and House, p. 194, reports the 2016 discovery; compare 2 Kings 18:4.", "note": "The excavators interpret broken altar horns and a latrine installation as desecration associated with Hezekiah’s reform. Attribute that historical connection to the excavators.", "url": "https://www.journals.uchicago.edu/doi/10.1086/703343", "consulted": "Original excavation article’s publisher abstract consulted directly."}]}, {"number": 19, "title": "Things you should not say", "text": "An exciting story can spread faster than a careful report. Before repeating a discovery, ask where it came from, who examined it and what was actually published.\n\nChariot-wheel claims from the Red Sea have not produced accepted archaeological evidence. Noah’s Ark claims remain unverified. The Cyrus Cylinder describes restorations but does not name the Jews.[^cyrus] The proposed curse inscription on the Mount Ebal lead object is contested.[^ebal] Dealer-supplied scroll fragments at Museum of the Bible proved inauthentic when examined scientifically.[^forgeries] These claims need different treatment from a securely excavated inscription.\n\nGod gives us a plain rule: “You shall not bear false witness against your neighbor.” (Exodus 20:16 LSB)\n\nGrisanti reminds evangelical readers that we are not responsible for making Scripture into God’s Word by winning an archaeological argument. We can examine discoveries honestly because we trust the God whose Word it is.[^grisanti]\n\nWhen you make a mistake, acknowledge it and put it right. A true claim someone can check is worth more than an exciting claim that collapses.\n\nSpeaking truthfully honors God and helps a friend know why you can be trusted.", "sources": [{"id": "cyrus", "label": "Mordechai Cogan · the Cyrus Cylinder", "citation": "“Cyrus Cylinder (2.124).” In The Context of Scripture, ed. William W. Hallo and K. Lawson Younger Jr., vol. 2. Brill, 2000, pp. 315–316, lines 20–36.", "trail": "Translation excerpt in Grisanti, OT796 appendix #87; Price and House, p. 198.", "note": "The text describes restoring shrines and communities in Mesopotamia. It supplies a restoration policy parallel; Ezra identifies its application to Jerusalem. It does not name the Jews.", "url": "https://www.britishmuseum.org/collection/object/W_1880-0617-1941", "consulted": "Cogan excerpt consulted through appendix #87; the museum page refused automated retrieval in this review."}, {"id": "ebal", "label": "The Mount Ebal lead object · a published dispute", "citation": "Stripling et al., “You are Cursed by the God YHW: an early Hebrew inscription from Mt. Ebal,” Heritage Science 11 (2023), DOI 10.1186/s40494-023-00920-9; Mark S. Haughwout, “Mt. Ebal curse tablet? A refutation of the claims regarding the so called Mt. Ebal curse tablet,” Heritage Science 12, article 70 (2024), DOI 10.1186/s40494-023-01130-z.", "trail": "Published proposal and response, rather than a sensational headline.", "note": "The interpretation as a very early Hebrew curse inscription is contested. The object should not be advertised as an agreed discovery of the earliest biblical text.", "url": "https://www.nature.com/articles/s40494-023-01130-z", "consulted": "Published proposal and scholarly response consulted."}, {"id": "forgeries", "label": "Museum of the Bible · scientific investigation of dealer fragments", "citation": "Dead Sea Scrolls Collection Scientific Research and Analysis, final report (2020), commissioned by Museum of the Bible; Art Fraud Insights and advisory team.", "trail": "Direct follow-up to the book’s warning about unverified antiquities claims.", "note": "The museum’s own investigation found its post-2002 textual fragments inauthentic. This concerns those dealer-supplied fragments, not the genuine Qumran Isaiah Scroll.", "url": "https://www.museumofthebible.org/dead-sea-scroll-fragments", "consulted": "Museum’s published report conclusion consulted directly."}, {"id": "grisanti", "label": "Michael A. Grisanti · archaeology and Scripture", "citation": "“Recent Archaeological Discoveries That Lend Credence to the Historicity of the Scriptures.” Journal of the Evangelical Theological Society 56/3 (2013): 475–497, especially 475–476.", "trail": "Also OT796: Old Testament Introduction, Spring 2026 course notes, printed pp. 162–168. Private notes are cited, not redistributed.", "note": "Grisanti begins with confidence in Scripture and explains how archaeology can confirm its historical setting and answer objections. This book follows that perspective without treating an individual artifact as the whole Christian case.", "url": "https://etsjets.org/wp-content/uploads/2013/10/files_JETS-PDFs_56_56-3_JETS_56-3_475-497_Grisanti.pdf", "consulted": "Published article consulted directly, along with the privately supplied notes."}]}, {"number": 20, "title": "Reasons that invite trust", "text": "Good reasons can answer a question, help someone begin to trust, or deepen faith already begun. Paul reasoned about Jesus from the Scriptures. We can do the same with care for the person listening.\n\nGrisanti also teaches that Scripture is **self-authenticating**: it is trustworthy because it is God’s Word. Calvin says, “God alone can properly bear witness to his own words.” He describes Scripture as carrying its own evidence, sealed upon our hearts by the Spirit.[^calvin] Michael Kruger develops this account of how Scripture is recognized.[^kruger]\n\nThe Westminster Confession names many good arguments for Scripture and says our full assurance comes from the Holy Spirit bearing witness by and with the Word.[^wcf] God can use evidence, Scripture, prayer and trustworthy testimony as means of his grace. Learning helps us grow; Christ is the one who makes us right with God.\n\nJesus’s parable says, “If they do not listen to Moses and the Prophets, they will not be persuaded even if someone rises from the dead.” (Luke 16:31 LSB) Hear the Word itself: “So faith comes from hearing, and hearing by the word of Christ.” (Romans 10:17 LSB)\n\nSpurgeon pictured a crowd trying to defend a lion in a cage. His advice was to “open the door, and let the lion out!”[^spurgeon] Open Scripture with your friend. Give your reasons, speak of Christ, and trust his Spirit to work through his Word.", "sources": [{"id": "calvin", "label": "John Calvin · Scripture’s own witness", "citation": "Institutes of the Christian Religion 1.7.4–5, Henry Beveridge translation.", "trail": "Grisanti, OT796 Notes, printed p. 28 (the brief listed p. 27).", "note": "Scripture is received as God’s Word; the Spirit seals its authority upon the heart. Other evidence has real value, without becoming the source of God’s authority.", "url": "https://www.ccel.org/ccel/calvin/institutes.iii.viii.html", "consulted": "Public-domain primary text consulted directly."}, {"id": "kruger", "label": "Michael J. Kruger · a self-authenticating canon", "citation": "Canon Revisited: Establishing the Origins and Authority of the New Testament Books. Crossway, 2012, p. 113.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 28.", "note": "Kruger joins Scripture’s qualities, reception, apostolic origins and the Spirit’s work. This is further reading behind the page’s Reformed account, not a direct book quotation.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, {"id": "wcf", "label": "Westminster Confession of Faith · chapter 1.5", "citation": "Westminster Confession of Faith 1.5 (1646).", "trail": "Also foundational to the museum’s Christian-hope panel.", "note": "The confession names many arguments for Scripture, then locates full assurance in the inward work of the Holy Spirit bearing witness by and with the Word.", "url": "https://www.opc.org/wcf.html", "consulted": "Confessional primary text; the book summarizes rather than replacing its teaching with an archaeology score."}, {"id": "spurgeon", "label": "Charles H. Spurgeon · let the lion out", "citation": "“Christ and His Co-workers,” sermon no. 2467, delivered June 10, 1886; published May 31, 1896, Metropolitan Tabernacle Pulpit, vol. 42.", "trail": "The familiar condensed lion saying appears, attributed, in Grisanti’s notes, printed p. 166. Here the actual sermon is cited.", "note": "The popular one-line “Scripture is like a lion” is a condensed saying. The sermon itself says “open the door, and let the lion out!” His point encourages proclaiming Christ, not abandoning truthful answers.", "url": "https://www.ccel.org/ccel/spurgeon/sermons42/sermons42.xxii.html", "consulted": "Public-domain primary sermon consulted directly."}]}, {"number": 21, "title": "How Jesus read it", "text": "Jesus treated the Old Testament as God’s true Word. When tempted, he answered, “It is written,” (Matthew 4:4 LSB) He said, “the Scripture cannot be broken” (John 10:35 LSB)\n\nAfter his resurrection, he explained the Scriptures to two travelers: “Then beginning with Moses and with all the prophets, He interpreted to them the things concerning Himself in all the Scriptures.” (Luke 24:27 LSB)\n\nThen he told his disciples, “all things which are written about Me in the Law of Moses and the Prophets and the Psalms must be fulfilled.” (Luke 24:44 LSB)\n\nThe risen Jesus gives us a way to read the whole Old Testament. The history, promises, prayers and prophets lead us toward him.\n\nThat is why the two halves of this subject belong together. The case for the Old Testament reaches its center in Jesus, and the case for Jesus includes public history. The next shelves follow those accounts and their witnesses.\n\nRead the Old Testament with the Savior who opened it for his friends."}, {"number": 22, "title": "How to say it", "text": "Greg Koukl says an ambassador needs knowledge, wisdom and character: facts worth knowing, a thoughtful way to explain them, and a manner that lets someone hear.[^koukl]\n\nPaul puts it this way: “Walk in wisdom toward outsiders, redeeming the time. Let your words always be with grace, seasoned with salt, so that you will know how you should answer each person.” (Colossians 4:5–6 LSB)\n\nPeter’s command to give a reason for our hope ends “yet with gentleness and fear,” (1 Peter 3:15 LSB)\n\nAsk a question and listen to the answer. Say “I don’t know” when you do not, and look into it. Your friend may need time, or may have a different question from the one you expected.\n\nKoukl calls this gardening. Some plant and some water. God gives the growth.[^koukl] You can offer one good reason today without forcing a whole conversation to its finish.\n\nRemember the news you are sharing: the God who rescued slaves kept his promises and came to save sinners. Let your manner fit that mercy.", "sources": [{"id": "koukl", "label": "Gregory Koukl · questions and ambassadors", "citation": "Tactics: A Game Plan for Discussing Your Christian Convictions, updated and expanded edition. Zondervan, 2019; “Ancient Words, Ever True?” Stand to Reason.", "trail": "Columbo questions, the pebble-in-the-shoe image, gardening and knowledge/wisdom/character are credited to Koukl.", "note": "Questions invite a person to explain a claim. Offer truthful reasons with patience; the aim is persuasion rather than pressure.", "url": "https://www.str.org/w/ancient-words-ever-true-", "consulted": "Stand to Reason article consulted directly; the book is the fuller method reference."}]}, {"number": 23, "title": "A short list to carry", "text": "Six things you can say and follow to their sources:\n\n1. **Enemy kings name Israel’s kings.** Omri, Ahab, Jehu and Hezekiah appear in Moabite and Assyrian records.[^mesha][^kurkh][^obelisk][^sennacherib]\n2. **David’s dynasty is on an enemy’s monument** from the ninth century BC, within roughly 150 years of his lifetime.[^tel-dan]\n3. **The 701 BC Jerusalem campaign is told by both sides.** Sennacherib names Hezekiah but claims no capture of Jerusalem.[^sennacherib]\n4. **Jerusalem’s capture in 597 BC is dated in Babylon’s records.** The chronicle names the day in its own calendar.[^chronicle]\n5. **Isaiah 53 was copied before Jesus was born.** The Great Isaiah Scroll gives us the chapter in a pre-Christian manuscript.[^isaiah]\n6. **Merneptah names Israel in Canaan by about 1208 BC.** Israel is already a people in the land.[^merneptah]\n\nThese findings are accepted by scholars who are not Christians too. They are shared historical evidence, not facts that depend on agreeing with our theology.\n\nStart with one your friend has asked about. Let them see what was found and why it matters.", "sources": [{"id": "mesha", "label": "André Lemaire · Mesha’s monument", "citation": "“House of David Restored in Moabite Inscription.” Biblical Archaeology Review 20/3 (May/June 1994): 30–37.", "trail": "Mesha and Omri: Beck chart; Grisanti’s archaeology discussion.", "note": "Mesha names Omri and Israel securely. Lemaire’s House of David restoration on the damaged Mesha line is a separate debated reading; this page does not rely on it.", "url": "https://collections.louvre.fr/en/ark:/53355/cl010120339", "consulted": "Louvre collection record consulted directly; Lemaire’s article remains the original-publication trail for the distinct proposed David reading."}, {"id": "kurkh", "label": "Ahab at Qarqar · Assyrian royal text", "citation": "Kurkh Monolith of Shalmaneser III; The Context of Scripture, vol. 2, pp. 263–264; British Museum BM 118884.", "trail": "Grisanti’s Assyrian-history discussion; Price and House discovery chart.", "note": "The annal lists Ahab of Israel among the coalition at Qarqar in 853 BC. Its troop totals are a royal claim; the named ruler is the point used here.", "url": "https://www.britishmuseum.org/collection/object/W_1863-0704-1", "consulted": "Object/text trail through the supplied sources; no claim of obtaining the full Context of Scripture volume."}, {"id": "obelisk", "label": "Shalmaneser III · Jehu’s tribute", "citation": "Black Obelisk, British Museum BM 118885; translation in Ancient Near Eastern Texts Relating to the Old Testament, ed. James B. Pritchard, 3rd ed., p. 281.", "trail": "Grisanti appendix #82, citing Alfred Hoerth, Archaeology and the Old Testament, p. 322.", "note": "The tribute register names Jehu in 841 BC. The kneeling figure may be Jehu or his envoy. Assyrian “son of Omri” identifies Israel’s royal house/land, not Jehu’s biological father.", "url": "https://oracc.museum.upenn.edu/nimrud/livesofobjects/blackobelisk/index.html", "consulted": "University of Pennsylvania’s Nimrud project account consulted; ANET/Hoerth are the publication trail."}, {"id": "sennacherib", "label": "Sennacherib · the Jerusalem campaign", "citation": "Sennacherib’s annals, third campaign (701 BC), including the Taylor Prism, British Museum BM 91032.", "trail": "Grisanti appendix #82–84; Beck’s Old Testament archaeology chart.", "note": "The annals name Hezekiah and describe confining him in Jerusalem. They report tribute, not the capture of the city. Compare 2 Kings 18–19 and Isaiah 36–37.", "url": "https://www.britishmuseum.org/collection/object/W_1855-1003-1", "consulted": "Campaign text consulted in the supplied appendix; do not turn the bird-in-a-cage illustration into a claim about every detail of the siege."}, {"id": "tel-dan", "label": "Avraham Biran and Joseph Naveh · House of David", "citation": "“An Aramaic Stele Fragment from Tel Dan.” Israel Exploration Journal 43 (1993): 81–98; “The Tel Dan Inscription: A New Fragment.” IEJ 45 (1995): 1–18.", "trail": "Grisanti appendix #96, citing Price and House p. 119; Beck, p. 130, entry 21.", "note": "The ninth-century Aramaic monument names the House of David. The enemy’s boast is evidence for a recognized dynasty. The fragment does not itself give the author’s name; attribution to Hazael is an interpretation.", "url": "https://ngsba.org/excavations/tel-dan/", "consulted": "Excavation project’s account consulted directly; IEJ articles remain the original-publication trail."}, {"id": "chronicle", "label": "D. J. Wiseman · Babylon’s Jerusalem chronicle", "citation": "Chronicles of Chaldaean Kings (626–556 B.C.) in the British Museum. British Museum, 1956, Chronicle 5, BM 21946.", "trail": "Beck’s chart and the museum’s Babylon expedition.", "note": "The Babylonian text dates Jerusalem’s capture and the king’s replacement to Nebuchadnezzar’s seventh year, 2 Adar (597 BC). This is the earlier capture, before the city’s later destruction.", "url": "https://www.britishmuseum.org/collection/object/W_1896-0409-51", "consulted": "Publication/object trail through the supplied sources and existing exhibit record."}, {"id": "isaiah", "label": "Israel Museum · the Great Isaiah Scroll", "citation": "The Great Isaiah Scroll, 1QIsaᵃ, Shrine of the Book; exhibition guide.", "trail": "Grisanti appendix #100; compare Paul D. Wegner, A Student’s Guide to Textual Criticism of the Bible (IVP Academic, 2006).", "note": "Copied around 125 BC, this is the same recognizable book, including chapter 53, before Christianity. Its many variants are published openly; stability does not require identical spelling or wording at every point.", "url": "https://www.imj.org.il/sites/default/files/IMJ%20Great%20Isaiah%20Scroll%20Exhibition.pdf", "consulted": "Museum presentation consulted; Wegner is further reading, not a newly obtained quotation."}, {"id": "merneptah", "label": "Michael G. Hasel · Israel in Canaan", "citation": "“Israel in the Merneptah Stela.” Bulletin of the American Schools of Oriental Research 296 (1994): 45–61, DOI 10.2307/1357179; also Hasel’s discussion in Critical Issues in Early Israelite History (2008), p. 52.", "trail": "Grisanti appendix #79; Beck, p. 128, entry 12; notes printed p. 151.", "note": "The text names Israel as a people in Canaan around 1208 BC. This is the widely accepted inscriptional reference used here.", "url": "https://doi.org/10.2307/1357179", "consulted": "Publisher abstract and supplied appendix consulted; the full 1994 article was not obtained."}]}, {"number": 24, "title": "The point of it all", "text": "The Old Testament brings us into the history of promises: to Abraham, to David, and to a people in exile. The stones help us see that the people, places and disasters belonged to the real world. God was at work in that world.\n\nJesus tells us where these Scriptures lead: “You search the Scriptures because you think that in them you have eternal life; it is these that bear witness about Me; and you are unwilling to come to Me so that you may have life.” (John 5:39–40 LSB)\n\nWe have all sinned and need God’s mercy. Jesus Christ, the eternal Son of God, became truly human, lived without sin, died for sinners and rose bodily from the dead. Forgiveness and new life are his gift, received by grace through faith. We turn from sin and trust him, then learn to love God and our neighbors through his Spirit’s help.\n\nEvidence gives us good reasons to trust him and speak of him with gentleness. We study history to know the God who rules it, and to worship the Savior who entered it.\n\nAt his entry into Jerusalem, Jesus answered those who wanted his disciples silenced:\n\n“I tell you, if these were silent, the stones will cry out!” (Luke 19:40 LSB)\n\n*Read together: Isaiah 55:1–3, 6–7; Psalm 19; Isaiah 41:21–24; Acts 17:2–3; 1 Peter 3:15–16.*"}], "source": "Foundation-Claude/old-testament/books/OT-R-apologetics-long.md", "sha256": "6c87b843b88f1e100be6f63e5504f5327b7b8640eb48d7c77491ea0501abb9f1", "revision": "November 20, 2026", "translationNotices": {"LSB": "Scripture quotations taken from the (LSB®) Legacy Standard Bible®, Copyright © 2021 by The Lockman Foundation. Used by permission. All rights reserved. Managed in partnership with Three Sixteen Publishing Inc. LSBible.org and 316publishing.com.", "CSB": "Scripture quotations marked CSB have been taken from the Christian Standard Bible®, Copyright © 2017, 2020 by Holman Bible Publishers. Used by permission. Christian Standard Bible® and CSB® are federally registered trademarks of Holman Bible Publishers."}}}}, {"id": "new-a", "hall": "nt", "subject": "Archaeology", "editions": {"short": {"title": "Ten More Things Found", "subtitle": "Ten real discoveries from the time of Jesus and the first Christians", "blurb": "A house, a boat, a pool, a stone step, a bone box, a nail, an old book, a broken letter, a scrap of paper and a floor. All real. All from the world Jesus lived in.", "pages": [{"number": 1, "title": "A different kind of digging", "text": "Jesus was not a king with a palace. His friends were fishermen. People like that do not leave big stone monuments.\n\nSo we look for other things. We look for the places they went and the people they met.\n\nHere are ten things that have been found."}, {"number": 2, "title": "The little house", "text": "**A house in Nazareth.** Found in 2009.\n\nSome people said the town of Nazareth was not there when Jesus was a boy. Then a small stone house from that very time was dug up.[^nazareth]\n\nNazareth was real. It was just tiny. Only a few hundred people lived there.\n\n*Read Luke 2:39–40.*", "sources": [{"id": "nazareth", "label": "Nazareth in the first century", "citation": "Yardenna Alexandre (Israel Antiquities Authority), excavation of a first-century house, 2009; Ken Dark, Roman-Period and Byzantine Nazareth and Its Hinterland (Routledge, 2020). Michael Avi-Yonah, “A List of Priestly Courses from Caesarea,” Israel Exploration Journal 12 (1962): 137–139.", "trail": "Excavations under and near the Church of the Annunciation and the Sisters of Nazareth convent → Dark 2020.", "note": "The Caesarea inscription, of the 3rd–4th century, names Nazareth as the home of a priestly course after AD 70. Claims that Nazareth did not exist in Jesus’ day (René Salm, The Myth of Nazareth, 2008) have not persuaded archaeologists. Dark has argued that a first-century house under the convent may be the one Byzantine Christians honored as Jesus’ home; that remains a proposal.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 3, "title": "The fishing boat", "text": "**The Sea of Galilee Boat.** Found in 1986, when the lake was very low.\n\nTwo brothers saw its shape in the mud. It is two thousand years old and about 27 feet long.[^galilee-boat] Thirteen people could fit in it.\n\nWe do not know who owned it. But Jesus and his friends sailed in boats just like it.\n\n*Read Mark 4:36–39.*", "sources": [{"id": "galilee-boat", "label": "The Galilee boat", "citation": "Found by Moshe and Yuval Lufan of Kibbutz Ginosar in January 1986; Yigal Allon Center, Ginosar. Shelley Wachsmann, The Sea of Galilee Boat: A 2000-Year-Old Discovery from the Sea of Legends (Plenum, 1995).", "trail": "The excavation → conservation in polyethylene glycol (wax), 1986–1997 → Wachsmann 1995.", "note": "Radiocarbon and the pottery found with it date the boat between about 100 BC and AD 70. It is about 8.2 m long and could carry about fifteen people. Josephus describes such boats on the lake in the war of AD 67.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 4, "title": "The pool with steps", "text": "**The Pool of Siloam.** Found in 2004, when workers were fixing a pipe.\n\nJesus put mud on a blind man’s eyes and told him to wash in this pool. The man came back able to see.\n\nThe steps he walked down are still there.[^siloam-pool]\n\n*Read John 9:6–7.*", "sources": [{"id": "siloam-pool", "label": "The Pool of Siloam, 2004", "citation": "Found during sewer work in 2004 and excavated by Ronny Reich and Eli Shukron (Israel Antiquities Authority); Hershel Shanks, “The Siloam Pool,” Biblical Archaeology Review 31:5 (2005).", "trail": "The excavation → Reich and Shukron’s reports → the stepped street to the temple, excavated since 2013.", "note": "Coins of Alexander Jannaeus in the plaster and of the Jewish revolt in the fill bracket its use from the 1st century BC to AD 70. Most think it served pilgrims for purification before going up to the temple (John 7:37–38; 9:7).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 5, "title": "The governor’s stone", "text": "**The Pilate Stone.** Found in 1961 by the sea.\n\nPontius Pilate was the Roman governor who sent Jesus to the cross. This stone has his name carved on it, and his job: ruler of Judea.[^pilate-stone]\n\nIt had been turned upside down and used as a step in a theater.\n\n*Read Matthew 27:1–2.*", "sources": [{"id": "pilate-stone", "label": "The Pilate Stone · Caesarea, 1961", "citation": "Limestone block from the theater at Caesarea, found by the Italian expedition under Antonio Frova in 1961; Israel Museum. Géza Alföldy, “Pontius Pilatus und das Tiberieum von Caesarea Maritima,” Scripta Classica Israelica 18 (1999): 85–108.", "trail": "The stone → Frova’s first publication (1961) → Alföldy 1999.", "note": "The text names a Tiberieum, a building honoring Tiberius, and Pilate as praefectus Iudaeae. Alföldy read the building as a lighthouse for the harbor; others suggest a temple. In 2018 a copper ring from Herodium inscribed “of Pilatus” was published; it may belong to the governor or to a member of his staff.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 6, "title": "The priest’s bone box", "text": "**The Caiaphas Ossuary.** Found in 1990 by workers building a park.\n\nIt is a beautiful stone box for bones. The name scratched on it is Caiaphas.[^caiaphas-ossuary] That was the name of the high priest who put Jesus on trial.\n\nIt is very likely his.\n\n*Read Matthew 26:57.*", "sources": [{"id": "caiaphas-ossuary", "label": "The Caiaphas ossuary", "citation": "Found in North Talpiot, Jerusalem, 1990; Israel Museum. Zvi Greenhut, “The ‘Caiaphas’ Tomb of North Talpiyot, Jerusalem,” ‘Atiqot 21 (1992): 63–71; Ronny Reich, “Caiaphas’ Name Inscribed on Bone Boxes,” Biblical Archaeology Review 18:5 (1992).", "trail": "The tomb → Greenhut and Reich 1992; an ossuary of “Miriam daughter of Yeshua son of Caiaphas” was published in 2011.", "note": "The inscription reads Yehosef bar Qayafa. A few scholars questioned the spelling and the identification; most accept that the ornate box belonged to the high priest’s family and probably to Caiaphas himself (Josephus, Antiquities 18.35).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 7, "title": "The nail", "text": "**The crucified man.** Found in 1968.\n\nThe Romans killed people on crosses. In a tomb in Jerusalem was the heel bone of a man who died that way. The nail was still in it.[^yehohanan]\n\nHis family had buried him. So a man who died on a cross could be buried in a tomb, as Jesus was.\n\n*Read John 19:40–42.*", "sources": [{"id": "yehohanan", "label": "Yehohanan · the crucified man from Giv‘at ha-Mivtar", "citation": "Vassilios Tzaferis, “Jewish Tombs at and near Giv‘at ha-Mivtar, Jerusalem,” Israel Exploration Journal 20 (1970): 18–32; Joseph Zias and Eliezer Sekeles, “The Crucified Man from Giv‘at ha-Mivtar: A Reappraisal,” IEJ 35 (1985): 22–27. Israel Museum.", "trail": "The 1968 tomb → Tzaferis 1970 → Zias and Sekeles 1985.", "note": "The nail is about 11.5 cm long, bent at the tip, with a small wooden plate under its head. The 1985 reappraisal found no clear sign of nails in the arms, which may have been tied. A second heel with a nail was reported from Gavello, Italy, in 2018. Yehohanan was buried in a family tomb, as the Gospels say of Jesus.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 8, "title": "The Roman’s history book", "text": "**Tacitus.** He was a Roman who wrote history about eighty years after Jesus.\n\nHe did not like Christians. But he wrote that their name came from Christ, who was put to death by Pontius Pilate.[^nero-tacitus]\n\nEven people who were not Christians knew what had happened.", "sources": [{"id": "nero-tacitus", "label": "Nero’s persecution · Tacitus and Suetonius", "citation": "Tacitus, Annals 15.38–44 (the fire of AD 64; Christus executed by Pontius Pilate under Tiberius); Suetonius, Nero 16.2.", "trail": "Tacitus (writing about AD 116) → Ronald Mellor, Tacitus (Routledge, 1993).", "note": "Tacitus says four of Rome’s fourteen districts were untouched, three leveled and seven badly damaged. He calls the Christians hated for their “abominations” and their faith a “deadly superstition,” and still reports the public’s pity. His statement on Christ’s execution under Pilate is accepted as genuine by nearly all historians.", "url": "https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Tacitus/Annals/15B*.html", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 9, "title": "The broken letter", "text": "**The Gallio Inscription.** Found in Greece in nine pieces.\n\nIt is a letter from the emperor. It names a governor called Gallio and tells us the year he ruled.[^gallio-inscription]\n\nThe Bible says Paul stood in front of Gallio. So now we know exactly when Paul was there.\n\n*Read Acts 18:12–16.*", "sources": [{"id": "gallio-inscription", "label": "The Gallio inscription · Delphi, AD 52", "citation": "Letter of Claudius to Delphi, nine fragments in the Delphi Archaeological Museum; published by Émile Bourguet (1905); Sylloge Inscriptionum Graecarum³ 801 D. Adolf Deissmann, Paul: A Study in Social and Religious History (2nd ed., 1926), appendix I.", "trail": "The stone → Bourguet → Deissmann → Jerome Murphy-O’Connor, St. Paul’s Corinth (3rd ed., Liturgical Press, 2002).", "note": "The letter is dated by Claudius’ 26th acclamation as imperator, which falls in the first half of AD 52. Proconsuls served for a year from early summer, so Gallio’s year was 51–52 (or possibly 52–53). Acts 18 then dates Paul’s eighteen months in Corinth to about 50–52.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 10, "title": "The scrap of paper", "text": "**P52.** It is smaller than a playing card.\n\nIt has a few words from the Gospel of John on the front and back. It is the oldest piece of the New Testament that we have.[^p52] It was copied not long after John wrote.\n\nOn it Pilate asks Jesus, “What is truth?”\n\n*Read John 18:37–38.*", "sources": [{"id": "p52", "label": "Papyrus 52 · a scrap of John", "citation": "John Rylands Library, Manchester, P. Rylands Gr. 457. C. H. Roberts, An Unpublished Fragment of the Fourth Gospel in the John Rylands Library (Manchester, 1935).", "trail": "Bought in Egypt by B. P. Grenfell in 1920 → Roberts 1935 → Brent Nongbri, “The Use and Abuse of P52,” Harvard Theological Review 98 (2005): 23–48.", "note": "Roberts dated the hand to the first half of the 2nd century. Nongbri showed comparable hands run later, so a range to about AD 200 is possible. Either way it is among the earliest New Testament manuscripts.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 11, "title": "The floor under the prison", "text": "**The Megiddo Mosaic.** Found in 2005 under a prison yard. Prisoners helped dig it up.\n\nIt is the floor of a room where Christians met, long before it was safe to be one. In the floor are the words “God Jesus Christ.”[^megiddo-mosaic]\n\nThey knew who he was.\n\n*Read John 20:28.*", "sources": [{"id": "megiddo-mosaic", "label": "The Megiddo prayer hall · “to God Jesus Christ”", "citation": "Yotam Tepper and Leah Di Segni, A Christian Prayer Hall of the Third Century CE at Kefar ‘Othnay (Legio): Excavations at the Megiddo Prison 2005 (Israel Antiquities Authority, 2006).", "trail": "The 2005 excavation → Tepper and Di Segni 2006 → Edward Adams, The Earliest Christian Meeting Places (T&T Clark, 2013).", "note": "The excavators dated the floor to about AD 230; some prefer the later 3rd century. It is before Constantine either way. The phrase “to God Jesus Christ” stands in a soldier’s building, in a province where Christianity was illegal.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 12, "title": "What the ten tell us", "text": "The places in the Gospels were real places. The rulers were real rulers. The first Christians really did worship Jesus as God.\n\nThese finds show that the story happened in our world, to real people. God can use these discoveries to help us understand the Gospels and grow in love for Jesus.\n\nAnd that means it matters for real people now. It matters for you."}], "source": "Foundation-Claude/new-testament/books/NT-A-archaeology-short.md", "sha256": "81fea6a8360b6c172635187a629f1b6d90c160fe347033b987b2e398104dc9e5"}, "long": {"title": "Stones That Remember", "subtitle": "A field guide to twenty-one discoveries from the New Testament’s world", "blurb": "A boat in the mud of a shrinking lake. A governor’s name on a step. A nail that would not come out. A mosaic floor under a prison yard. Twenty-one places where the ground has kept something the Gospels mention in passing.", "pages": [{"number": 1, "title": "Before you look", "text": "Old Testament archaeology is mostly about kings and their monuments, spread over two thousand years.\n\nThe New Testament is different. Its story covers about seventy years. Its people are fishermen, tax collectors, tent-makers and a carpenter. Such people do not put up monuments.\n\nSo here you look for other things. You look for places: a pool, a synagogue, a street. You look for the names of the officials who happened to be in charge. You look for the small details that only someone who was there would get right.\n\nThe world of the New Testament was destroyed in AD 70, when Rome burned Jerusalem. Anyone writing later would have had to describe a city that no longer existed. Keep that in mind as you go."}, {"number": 2, "title": "A village too small to mention", "text": "Nazareth is not in the Old Testament. The Jewish historian Josephus lists forty-five towns in Galilee and leaves it out. A few writers have claimed it did not exist in Jesus’s day and was invented later.\n\nIn 2009 archaeologists digging beside a church in modern Nazareth found a small house of the first century: two rooms and a courtyard, with a cistern cut in the rock.[^nazareth] In it were pieces of cups carved from soft white stone. Jews used stone cups because, under their law, stone could not become unclean.\n\nAround the old village are tombs, terraces for vines and stone watchtowers.\n\nSo Nazareth was there. It was a hamlet of a few hundred Jewish farmers, too small for anyone to mention.\n\n“Can anything good come out of Nazareth?” someone asks in John’s Gospel. Now you know why.\n\n*Grade: Secure. Read John 1:45–46.*", "sources": [{"id": "nazareth", "label": "Nazareth in the first century", "citation": "Yardenna Alexandre (Israel Antiquities Authority), excavation of a first-century house, 2009; Ken Dark, Roman-Period and Byzantine Nazareth and Its Hinterland (Routledge, 2020). Michael Avi-Yonah, “A List of Priestly Courses from Caesarea,” Israel Exploration Journal 12 (1962): 137–139.", "trail": "Excavations under and near the Church of the Annunciation and the Sisters of Nazareth convent → Dark 2020.", "note": "The Caesarea inscription, of the 3rd–4th century, names Nazareth as the home of a priestly course after AD 70. Claims that Nazareth did not exist in Jesus’ day (René Salm, The Myth of Nazareth, 2008) have not persuaded archaeologists. Dark has argued that a first-century house under the convent may be the one Byzantine Christians honored as Jesus’ home; that remains a proposal.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 3, "title": "The boat in the mud", "text": "In the winter of 1986 there had been no rain for two years, and the Sea of Galilee shrank back from its shore. Two brothers, fishermen from a nearby kibbutz, walked the newly dry ground and saw the curved outline of a boat.\n\nIt was eight meters long and two thousand years old.[^galilee-boat] The wood was as soft as wet cardboard. To move it, the team sprayed it with foam, floated it down the shore and then soaked it in wax for eleven years.\n\nIt had been built from twelve different kinds of wood and patched many times. Its owner was not rich.\n\nThere is no reason to think Jesus sat in this boat. But it is the kind the Gospels describe: big enough for thirteen men, with a deck at the stern where a tired man could lie down on a cushion and sleep through a storm.\n\n*Grade: Secure. Read Mark 4:35–41.*", "sources": [{"id": "galilee-boat", "label": "The Galilee boat", "citation": "Found by Moshe and Yuval Lufan of Kibbutz Ginosar in January 1986; Yigal Allon Center, Ginosar. Shelley Wachsmann, The Sea of Galilee Boat: A 2000-Year-Old Discovery from the Sea of Legends (Plenum, 1995).", "trail": "The excavation → conservation in polyethylene glycol (wax), 1986–1997 → Wachsmann 1995.", "note": "Radiocarbon and the pottery found with it date the boat between about 100 BC and AD 70. It is about 8.2 m long and could carry about fifteen people. Josephus describes such boats on the lake in the war of AD 67.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 4, "title": "The house by the synagogue", "text": "Capernaum was a fishing town built of black volcanic stone. Today its most striking ruin is a synagogue of white limestone, from about four hundred years after Jesus. Under its walls are the black foundations of an older one. That is where the synagogue of the Gospels stood.\n\nThirty meters away is an ordinary house of the first century. Something unusual happened to it. Within a few decades of Jesus’s time, one room was replastered, floor and walls, again and again. The cooking pots vanish from it. Visitors scratched prayers on the plaster in several languages, naming Jesus as Lord.\n\nLater a church with eight sides was built around that one room.\n\nEarly travelers were told it was the house of Peter.[^capernaum-house] We cannot be certain. But somebody thought this room worth marking, very early.\n\n*Grade: Strong. Read Mark 1:21, 29–34.*", "sources": [{"id": "capernaum-house", "label": "Capernaum · the house of Peter", "citation": "Excavations by Virgilio Corbo and Stanislao Loffreda from 1968; James F. Strange and Hershel Shanks, “Has the House Where Jesus Stayed in Capernaum Been Found?” Biblical Archaeology Review 8:6 (1982). The pilgrim Egeria (about AD 383): the house of the prince of the apostles was made into a church.", "trail": "Egeria (preserved by Peter the Deacon) → Corbo and Loffreda → Strange and Shanks.", "note": "The graffiti include prayers naming Jesus as Lord and Christ; one may name Peter. The identification rests on the early and continuous honoring of this one room. It cannot be proved, and it is one of the better-supported holy sites.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 5, "title": "Five porches", "text": "John’s Gospel says that in Jerusalem, by the Sheep Gate, there was a pool called Bethesda with five covered porches, where sick people lay.\n\nA pool normally has four sides. For centuries no such pool was known. Some scholars decided John had made it up, and that the five porches were a symbol for the five books of Moses.\n\nIn the 1880s excavators north of the Temple Mount found it.[^bethesda] There were two large pools, side by side, with a wall of rock between them. A porch on each of the four sides and one across the middle make five.\n\nJohn was not writing a riddle. He was describing a place he knew, and which was buried under rubble soon after.\n\n*Grade: Strong. Read John 5:1–9.*", "sources": [{"id": "bethesda", "label": "The Pool of Bethesda", "citation": "Excavations at St Anne’s, Jerusalem: Conrad Schick (1888) and the White Fathers; the Copper Scroll (3Q15) names “Beth Eshdathayin” with its pools. Urban C. von Wahlde, “The Pool(s) of Bethesda and the Healing in John 5,” Revue Biblique 116 (2009): 111–136.", "trail": "Schick → the White Fathers’ excavations → von Wahlde 2009.", "note": "Two pools separated by a central dam match five colonnades. Von Wahlde argues the pools served as a large ritual bath (miqveh); a later healing shrine stood nearby. The textual question over John 5:4 (the angel stirring the water) is separate; the earliest manuscripts lack it.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 6, "title": "The steps to the pool", "text": "In John 9 Jesus puts mud on a blind man’s eyes and tells him to wash in the Pool of Siloam.\n\nVisitors to Jerusalem were long shown a small pool built by Christians in the fifth century. Then in 2004 a sewer pipe needed repair at the southern end of the old city. The workmen’s digger scraped stone. Archaeologists were called and found broad steps going down.\n\nIt was one side of a pool about the size of a football field, built in steps so that pilgrims could walk down into the water. Coins in the plaster showed it was in use in Jesus’s time.[^siloam-pool] From it a paved street climbs to the temple.\n\nThe whole pool is now being uncovered. The blind man would have gone down these steps without seeing them, and come back up seeing.\n\n*Grade: Secure. Read John 9:1–11.*", "sources": [{"id": "siloam-pool", "label": "The Pool of Siloam, 2004", "citation": "Found during sewer work in 2004 and excavated by Ronny Reich and Eli Shukron (Israel Antiquities Authority); Hershel Shanks, “The Siloam Pool,” Biblical Archaeology Review 31:5 (2005).", "trail": "The excavation → Reich and Shukron’s reports → the stepped street to the temple, excavated since 2013.", "note": "Coins of Alexander Jannaeus in the plaster and of the Jewish revolt in the fill bracket its use from the 1st century BC to AD 70. Most think it served pilgrims for purification before going up to the temple (John 7:37–38; 9:7).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 7, "title": "Stones that fell", "text": "Herod the Great rebuilt the temple on a platform bigger than twenty football fields. Its retaining walls still stand. One stone in the western wall is longer than a bus and weighs hundreds of tons.\n\n“Teacher, look at these stones!” said one of the disciples. Jesus answered that not one would be left on another.\n\nIn AD 70 the Roman army took Jerusalem and burned the temple. The soldiers pushed the buildings off the platform. At the south-west corner the blocks still lie in a heap on the paved street where they landed, and the paving stones under them are cracked.\n\nAmong them was a carved block from the very top of the wall. Its inscription says it marked the place where a priest stood to blow the trumpet.[^temple-stones]\n\n*Grade: Secure. Read Mark 13:1–2.*", "sources": [{"id": "temple-stones", "label": "The temple’s fallen stones and the trumpeting place", "citation": "Excavations at the southern and western walls by Benjamin Mazar from 1968; the “place of trumpeting” inscription, Israel Museum. Josephus, Jewish War 4.582 (a priest on the roof signaled the Sabbath with a trumpet) and 6.249–266 (the burning of the temple). Mark 13:1–2.", "trail": "Josephus → Mazar’s excavation reports → Leen Ritmeyer, The Quest (Carta, 2006).", "note": "The inscription is broken; it reads “to the place of trumpeting to …”, with the end usually restored as “to announce” or “to separate.” The heaps of stones on the Herodian street were left where they fell in AD 70.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 8, "title": "The notice on the wall", "text": "Non-Jews could enter the outer court of the temple. Beyond that was a low stone fence, and on it hung notices in Greek and Latin.\n\nOne was found in 1871.[^temple-warning] It says, in effect: no foreigner is to go beyond this barrier. Whoever is caught will have himself to blame for his death.\n\nIn Acts 21 a mob nearly kills Paul because they think he has taken a Greek past that fence.\n\nPaul later wrote to Christians in Ephesus, some Jewish and some not, that Christ had “broken down the dividing wall” between them. He was not using a figure of speech he had invented. He had stood at the wall. He had nearly died at it.\n\n*Grade: Secure. The stone is in Istanbul. Read Acts 21:27–32 and Ephesians 2:13–16.*", "sources": [{"id": "temple-warning", "label": "The temple warning inscription", "citation": "Found by Charles Clermont-Ganneau in 1871 (Istanbul Archaeology Museums); a second, fragmentary copy found in 1935 (Israel Museum). Josephus, Jewish War 5.193–194 and Antiquities 15.417.", "trail": "The stones → Clermont-Ganneau 1871 → Peretz Segal, “The Penalty of the Warning Inscription from the Temple of Jerusalem,” Israel Exploration Journal 39 (1989): 79–84.", "note": "Josephus describes these notices in Greek and Latin on the barrier. Scholars debate whether the death penalty was carried out by the Jewish authorities or left to God; Acts 21:28–31 shows how seriously a crowd took it. Paul’s “dividing wall” (Ephesians 2:14) may allude to it.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 9, "title": "A step in a theater", "text": "Pontius Pilate governed Judea for ten years. He is in all four Gospels and in the creed that Christians have recited for centuries.\n\nIn 1961 Italian archaeologists were clearing the theater at Caesarea, the Roman capital on the coast. They turned over a stone that had been reused as a step. On the underside were four lines of Latin. Part of it had been chiselled away, but this was left:\n\n...TIUS PILATUS  \n...ECTUS IUDA...E\n\nPontius Pilate, Prefect of Judea.[^pilate-stone] The stone had been part of a building he dedicated to the emperor Tiberius.\n\nPilate was already known from Jewish and Roman writers.[^pilate-caiaphas-josephus] But here is his name, his title and his province, in stone, from the years when he held the office.\n\n*Grade: Secure. Israel Museum. Read Luke 3:1 and John 19:1–16.*", "sources": [{"id": "pilate-stone", "label": "The Pilate Stone · Caesarea, 1961", "citation": "Limestone block from the theater at Caesarea, found by the Italian expedition under Antonio Frova in 1961; Israel Museum. Géza Alföldy, “Pontius Pilatus und das Tiberieum von Caesarea Maritima,” Scripta Classica Israelica 18 (1999): 85–108.", "trail": "The stone → Frova’s first publication (1961) → Alföldy 1999.", "note": "The text names a Tiberieum, a building honoring Tiberius, and Pilate as praefectus Iudaeae. Alföldy read the building as a lighthouse for the harbor; others suggest a temple. In 2018 a copper ring from Herodium inscribed “of Pilatus” was published; it may belong to the governor or to a member of his staff.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "pilate-caiaphas-josephus", "label": "Pilate and Caiaphas in Josephus and Philo", "citation": "Josephus, Antiquities 18.35 (“Joseph, who was called Caiaphas” made high priest), 18.55–62 (Pilate’s standards and aqueduct), 18.89 (Pilate removed after ten years), 18.95 (Caiaphas removed); Philo, Embassy to Gaius 299–305; Tacitus, Annals 15.44.", "trail": "Josephus and Philo → E. Mary Smallwood, The Jews under Roman Rule (Brill, 1976).", "note": "Philo, a contemporary, calls Pilate inflexible and harsh; the Gospels show a governor who gives way to pressure. Both can be true of a man whose position in Rome was shaky (John 19:12). Pilate’s title was prefect; Tacitus calls him procurator, the title of his own day.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 10, "title": "The high priest’s box", "text": "Jews in Jerusalem at this time buried their dead twice. The body lay in a rock tomb for a year. Then the bones were gathered into a stone box called an ossuary.\n\nIn 1990 workmen making a park south of the city broke through the roof of a tomb. Inside were twelve ossuaries. One was far finer than the rest, carved all over with rosettes. Scratched on its side, twice, was a name: Joseph son of Caiaphas.[^caiaphas-ossuary] It held the bones of a man of about sixty.\n\nThe Gospels call the high priest at Jesus’s trial Caiaphas. Josephus gives his full name: Joseph, who was called Caiaphas.\n\nIt is very probably the same man. He said it was better for one man to die for the people.\n\n*Grade: Strong. Israel Museum. Read John 11:47–53.*", "sources": [{"id": "caiaphas-ossuary", "label": "The Caiaphas ossuary", "citation": "Found in North Talpiot, Jerusalem, 1990; Israel Museum. Zvi Greenhut, “The ‘Caiaphas’ Tomb of North Talpiyot, Jerusalem,” ‘Atiqot 21 (1992): 63–71; Ronny Reich, “Caiaphas’ Name Inscribed on Bone Boxes,” Biblical Archaeology Review 18:5 (1992).", "trail": "The tomb → Greenhut and Reich 1992; an ossuary of “Miriam daughter of Yeshua son of Caiaphas” was published in 2011.", "note": "The inscription reads Yehosef bar Qayafa. A few scholars questioned the spelling and the identification; most accept that the ornate box belonged to the high priest’s family and probably to Caiaphas himself (Josephus, Antiquities 18.35).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 11, "title": "A nail", "text": "The Romans crucified tens of thousands of people. For a long time not one of their skeletons had been found, and some historians doubted that nails were used at all. Others said that crucified men were left unburied, so the story of Jesus’s tomb must be a legend.\n\nIn 1968 a tomb was opened in north Jerusalem. In an ossuary marked “Yehohanan” was a right heel bone with an iron nail still through it.[^yehohanan] The nail is about four and a half inches long. Its point had struck a knot in the wood and bent over like a fish-hook, so it could not be pulled out. His family had buried him with it.\n\nSo a crucified Jew, near Jerusalem, in the first century, was nailed, taken down and laid in his family’s tomb.\n\n*Grade: Secure. Israel Museum. Read John 19:38–42 and 20:24–27.*", "sources": [{"id": "yehohanan", "label": "Yehohanan · the crucified man from Giv‘at ha-Mivtar", "citation": "Vassilios Tzaferis, “Jewish Tombs at and near Giv‘at ha-Mivtar, Jerusalem,” Israel Exploration Journal 20 (1970): 18–32; Joseph Zias and Eliezer Sekeles, “The Crucified Man from Giv‘at ha-Mivtar: A Reappraisal,” IEJ 35 (1985): 22–27. Israel Museum.", "trail": "The 1968 tomb → Tzaferis 1970 → Zias and Sekeles 1985.", "note": "The nail is about 11.5 cm long, bent at the tip, with a small wooden plate under its head. The 1985 reappraisal found no clear sign of nails in the arms, which may have been tied. A second heel with a nail was reported from Gavello, Italy, in 2018. Yehohanan was buried in a family tomb, as the Gospels say of Jesus.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 12, "title": "The garden under the church", "text": "The Gospels say Jesus was crucified outside the city, near a garden, and buried in a new tomb cut in rock.\n\nThe Church of the Holy Sepulchre is inside Jerusalem’s walls today, which puzzles visitors. But those walls were built later. In AD 30 the spot was outside, in an old stone quarry. Tombs of that period are cut into the quarry’s sides and can still be seen inside the church.\n\nA hundred years later a Roman emperor built a pagan temple there. It was meant to bury the place, and instead it marked it.\n\nFrom 2022 archaeologists dug beneath the church floor during repairs. In soil about two thousand years old they found pollen and remains of olive trees and grapevines.[^holy-sepulchre] The quarry had been turned into gardens.\n\n*Grade: Strong. Read John 19:41–42.*", "sources": [{"id": "holy-sepulchre", "label": "The Church of the Holy Sepulchre · quarry, tombs and gardens", "citation": "Eusebius, Life of Constantine 3.25–40 (Hadrian’s temple removed; the tomb uncovered); Dan Bahat, “Does the Holy Sepulchre Church Mark the Burial of Jesus?” Biblical Archaeology Review 12:3 (1986); excavations under the church floor by Francesca Romana Stasolla (Sapienza University of Rome), 2022–.", "trail": "Eusebius → Virgilio Corbo’s excavations (1960s–70s) → Bahat 1986 → Stasolla.", "note": "Kathleen Kenyon’s work showed the site was outside the wall in AD 30. Rock-cut tombs of the period survive inside the church. Stasolla’s team reported pollen and remains of olive and vine from the Roman period, which fits John 19:41. The Garden Tomb, a popular alternative, is an older tomb of the Iron Age.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 13, "title": "A coin", "text": "Some men tried to trap Jesus with a question about taxes. He asked for a coin. “Whose picture is this, and whose name?”\n\nThousands of these coins survive. The silver denarius of Tiberius shows his head crowned with laurel. Around it runs his title: Tiberius Caesar, son of the divine Augustus.[^tiberius-denarius] To a Jew, that made the coin a small idol.\n\nSo the men who produced one in the temple courts had already given away which side they were on.\n\nJesus said to give Caesar what was Caesar’s and God what was God’s. The coin bore Caesar’s image. His hearers knew what bears God’s image.\n\nCoins are the commonest inscriptions there are, and among the most useful. They give a ruler’s face, his claims about himself and his dates.\n\n*Grade: Secure. Read Mark 12:13–17.*", "sources": [{"id": "tiberius-denarius", "label": "The tribute penny · the denarius of Tiberius", "citation": "Silver denarius of Tiberius, AD 14–37, legend TI CAESAR DIVI AVG F AVGVSTVS (“Tiberius Caesar, son of the divine Augustus, Augustus”). Mark 12:13–17.", "trail": "Roman Imperial Coinage, vol. 1 → David Hendin, Guide to Biblical Coins (5th ed., Amphora, 2010).", "note": "This is the commonest silver coin of Tiberius, and the one usually meant by “tribute penny.” Some argue the coin in the story could be an older Augustan denarius; any denarius would have carried Caesar’s image and divine claims.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 14, "title": "The proconsul’s year", "text": "Acts 18 says that in Corinth Paul was dragged before the governor, Gallio, who threw the case out.\n\nAt Delphi, across the gulf from Corinth, nine fragments of a stone inscription were found. Put together, they are a letter from the emperor Claudius. He mentions “Gallio, my friend and proconsul,” and the letter carries a date that works out to the first half of AD 52.[^gallio-inscription]\n\nRoman proconsuls served for one year. So Gallio was in Corinth from the summer of 51 to the summer of 52, and Paul stood in front of him then.\n\nThis one inscription is the peg on which the dates of Paul’s whole life hang. Count back and forward from it using Acts and the letters, and you can say when 1 Thessalonians was written to within a year.\n\nThe platform where Gallio sat is still in the middle of Corinth.\n\n*Grade: Secure. Read Acts 18:12–17.*", "sources": [{"id": "gallio-inscription", "label": "The Gallio inscription · Delphi, AD 52", "citation": "Letter of Claudius to Delphi, nine fragments in the Delphi Archaeological Museum; published by Émile Bourguet (1905); Sylloge Inscriptionum Graecarum³ 801 D. Adolf Deissmann, Paul: A Study in Social and Religious History (2nd ed., 1926), appendix I.", "trail": "The stone → Bourguet → Deissmann → Jerome Murphy-O’Connor, St. Paul’s Corinth (3rd ed., Liturgical Press, 2002).", "note": "The letter is dated by Claudius’ 26th acclamation as imperator, which falls in the first half of AD 52. Proconsuls served for a year from early summer, so Gallio’s year was 51–52 (or possibly 52–53). Acts 18 then dates Paul’s eighteen months in Corinth to about 50–52.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 15, "title": "A word in no book", "text": "In Acts 17 a mob in Thessalonica drags some Christians before the city officials. Luke calls these officials *politarchs*.\n\nThe word does not appear in any other Greek writer. For a long time it was held against Luke: he had the title wrong, or had made it up.\n\nThen it was noticed on an arch over the city’s western gate. The inscription begins, “In the time of the politarchs…” and lists their names.[^politarchs] The arch was pulled down in 1876, and the stone is in the British Museum. Dozens more inscriptions with the word have since been found across northern Greece.\n\nLuke had used the exact local term, which was different from the term in the next city along. He does this throughout Acts, with one official after another.[^luke-accuracy]\n\n*Grade: Secure. Read Acts 17:1–9.*", "sources": [{"id": "politarchs", "label": "Politarchs at Thessalonica", "citation": "Inscription from the Vardar Gate, Thessalonica, removed in 1876; British Museum. Ernest DeWitt Burton, “The Politarchs,” American Journal of Theology 2 (1898): 598–632; G. H. R. Horsley, “The Politarchs,” in David Gill and Conrad Gempf (eds.), The Book of Acts in Its Graeco-Roman Setting (Eerdmans, 1994).", "trail": "The inscription → Burton 1898 → Horsley 1994 (more than thirty inscriptions).", "note": "The title is rare in literature and common in Macedonian inscriptions; Thessalonica had five or six politarchs at a time. Luke uses the correct local term (Acts 17:6, 8), as he does for proconsuls in Cyprus and Achaia and the Asiarchs and town clerk at Ephesus.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "luke-accuracy", "label": "Luke as a historian", "citation": "W. M. Ramsay, St. Paul the Traveller and the Roman Citizen (London, 1895); Colin J. Hemer, The Book of Acts in the Setting of Hellenistic History (Mohr Siebeck, 1989); James Smith, The Voyage and Shipwreck of St. Paul (London, 1848).", "trail": "Ramsay’s travels in Asia Minor → Hemer’s catalogue of details in Acts 13–28 → Smith, a yachtsman, on Acts 27.", "note": "Ramsay began doubting Acts and came to regard Luke as a historian of the first rank. Smith checked Acts 27 against the winds, soundings and coast of Malta. Accurate setting does not by itself prove the miracles, but it shows a writer close to the events and careful with them.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 16, "title": "The theater at Ephesus", "text": "Ephesus was one of the great cities of the Roman Empire, and its pride was the temple of Artemis, one of the seven wonders of the world. Silversmiths made a good living from little silver shrines.\n\nActs 19 tells how one of them, Demetrius, stirred up his fellow craftsmen against Paul. The crowd rushed into the theater and shouted “Great is Artemis of the Ephesians!” for two hours, until the town clerk calmed them.\n\nThe theater is still there, cut into the hillside, with seats for twenty-four thousand. Inscriptions from the city name its silversmiths’ guild, its town clerk, and its title, “keeper of the temple of Artemis.”[^ephesus-acts] All three are in Luke’s account.\n\nStand on the stage and speak. You can be heard in the top row.\n\n*Grade: Secure. Read Acts 19:23–41.*", "sources": [{"id": "ephesus-acts", "label": "Ephesus · silversmiths, the theater and the town clerk", "citation": "Acts 19:23–41; the Salutaris inscription (AD 104), on gold and silver images of Artemis carried to the theater: Guy MacLean Rogers, The Sacred Identity of Ephesos (Routledge, 1991); Paul Trebilco, The Early Christians in Ephesus from Paul to Ignatius (Mohr Siebeck, 2004).", "trail": "Austrian excavations at Ephesus since 1895 → Rogers → Trebilco.", "note": "Inscriptions name the city as neokoros (temple keeper) of Artemis (Acts 19:35), its grammateus (town clerk) and its silversmiths. The theater held about 24,000. Earlier scholars thought neokoros for Artemis was later; inscriptions now show the usage.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 17, "title": "Lukewarm", "text": "The last book of the Bible opens with letters to seven churches in what is now western Turkey. To Laodicea it says: you are neither hot nor cold, and because you are lukewarm I will spit you out.\n\nPeople often take “hot” to mean keen and “cold” to mean hostile. The ruins suggest something else.\n\nSix miles from Laodicea were the hot springs of Hierapolis, good for bathing. Ten miles the other way was Colossae, with cold, fresh water, good for drinking. Laodicea had no spring. Its water came through stone pipes, and it arrived tepid and so full of minerals that the pipes are choked with lime to this day.[^laodicea-water]\n\nHot water is useful. Cold water is useful. Laodicea’s was neither.\n\nThe letter was written by someone who knew what came out of their pipes.\n\n*Grade: Strong. Read Revelation 3:14–22.*", "sources": [{"id": "laodicea-water", "label": "Laodicea’s water · hot, cold and lukewarm", "citation": "Revelation 3:15–16; M. J. S. Rudwick and E. M. B. Green, “The Laodicean Lukewarmness,” Expository Times 69 (1958): 176–178; Colin J. Hemer, The Letters to the Seven Churches of Asia in Their Local Setting (Sheffield, 1986).", "trail": "Rudwick (a geologist) and Green → Hemer 1986; Craig R. Koester, “The Message to Laodicea and the Problem of Its Local Context,” New Testament Studies 49 (2003): 407–424.", "note": "The reading in this book (hot is useful for healing, cold for drinking, lukewarm useless) is Rudwick and Green’s. Koester argues the image is more general: lukewarm drink makes anyone spit. Both agree the rebuke is about uselessness, not about keen versus hostile.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 18, "title": "The lampstand in Rome", "text": "After Jerusalem fell in AD 70, the Roman general Titus held a victory parade. His brother later built an arch in the Forum to remember it. It still stands.\n\nOn the inside of the arch, carved in deep relief, soldiers carry the treasures of the temple through the streets on poles: the golden table, the silver trumpets, and the great seven-branched lampstand.[^arch-titus]\n\nIt was carved by people who had seen those objects with their own eyes.\n\nForty years earlier Jesus had wept over Jerusalem and said that its enemies would surround it and leave not one stone on another. The Gospels record the warning. The arch records what came of it, from the winner’s side.\n\n*Grade: Secure. Read Luke 19:41–44.*", "sources": [{"id": "arch-titus", "label": "The Arch of Titus", "citation": "Built in the Roman Forum after Titus’ death in AD 81; Josephus, Jewish War 7.148–152 (the triumph with the table, trumpets and lampstand). Steven Fine (ed.), The Arch of Titus: From Jerusalem to Rome, and Back (Brill, 2021).", "trail": "Josephus → the Arch of Titus Digital Restoration Project (Yeshiva University, 2012), which found traces of yellow ochre on the lampstand.", "note": "The relief and Josephus describe the same procession. The lampstand’s stepped base differs from some ancient descriptions, which is discussed by Fine and others.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 19, "title": "A scrap of John", "text": "In 1920 a scholar buying old papyrus in Egypt sent a batch home to Manchester. It sat in a drawer for fourteen years. In 1934 a young researcher sorting it picked up a piece the size of a playing card, with Greek on both sides, and recognized the words.\n\nOne side has part of John 18:31–33.[^p52] The other has part of verses 37 and 38. Jesus is before Pilate. On the back are the remains of Pilate’s question: “What is truth?”\n\nWriting on both sides means it comes from a book with pages, not a scroll. The style of handwriting belongs to the second century, and many would say the first half of it.\n\nJohn’s Gospel was probably written in Ephesus in the 90s. Within a few decades it was being read far up the Nile.\n\n*Grade: Secure; the exact date is Debated. Manchester. Read John 18:33–38.*", "sources": [{"id": "p52", "label": "Papyrus 52 · a scrap of John", "citation": "John Rylands Library, Manchester, P. Rylands Gr. 457. C. H. Roberts, An Unpublished Fragment of the Fourth Gospel in the John Rylands Library (Manchester, 1935).", "trail": "Bought in Egypt by B. P. Grenfell in 1920 → Roberts 1935 → Brent Nongbri, “The Use and Abuse of P52,” Harvard Theological Review 98 (2005): 23–48.", "note": "Roberts dated the hand to the first half of the 2nd century. Nongbri showed comparable hands run later, so a range to about AD 200 is possible. Either way it is among the earliest New Testament manuscripts.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 20, "title": "The mocker’s drawing", "text": "On the Palatine Hill in Rome was a school for the emperor’s page boys. About AD 200 one of them scratched a cartoon on the wall.\n\nIt shows a figure on a cross, seen from behind, with the head of a donkey. To one side a man raises his hand in worship. Underneath, in crude Greek letters: “Alexamenos worships his god.”\n\nSomebody was teasing a boy called Alexamenos for being a Christian.[^alexamenos]\n\nIt is the oldest picture of the crucifixion in existence, and it was drawn as an insult. Look at what the mocker takes for granted. Christians worship someone who was crucified. They worship him as God. And everyone knows it.\n\nIn the next room another hand has written: “Alexamenos is faithful.”\n\n*Grade: Secure. Palatine Museum, Rome. Read 1 Corinthians 1:22–24.*", "sources": [{"id": "alexamenos", "label": "The Alexamenos graffito", "citation": "Plaster from the Paedagogium on the Palatine Hill, Rome, found in 1857; Palatine Museum. Tertullian, Apology 16, and Minucius Felix, Octavius 9, record the slander that Christians worshiped a donkey’s head.", "trail": "The plaster → Tertullian and Minucius Felix → Peter Lampe, From Paul to Valentinus (Fortress, 2003).", "note": "Dates proposed range from about AD 200 to the 3rd century. “Alexamenos fidelis” in an adjacent room may be a reply by Alexamenos or a friend.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 21, "title": "The table at Megiddo", "text": "In 2005 the prison at Megiddo in northern Israel needed a new wing. The law required a dig first, and the prisoners did the digging. Under the yard they found a mosaic floor.\n\nIt belonged to a Christian prayer hall of about AD 230, in a building used by Roman soldiers. Three inscriptions are set into the floor. A centurion named Gaianus paid for it. Four women are to be remembered: Primilla, Cyriaca, Dorothea and Chreste. And a woman named Akeptous gave the table that stood in the middle, “to God Jesus Christ, as a memorial.”[^megiddo-mosaic]\n\nNotice the date. This is nearly a hundred years before the emperor Constantine, and before the Council of Nicaea. Nobody in power wanted these people to believe this. An army officer and five women wrote it in their floor anyway.\n\n*Grade: Strong. Read John 20:26–29.*", "sources": [{"id": "megiddo-mosaic", "label": "The Megiddo prayer hall · “to God Jesus Christ”", "citation": "Yotam Tepper and Leah Di Segni, A Christian Prayer Hall of the Third Century CE at Kefar ‘Othnay (Legio): Excavations at the Megiddo Prison 2005 (Israel Antiquities Authority, 2006).", "trail": "The 2005 excavation → Tepper and Di Segni 2006 → Edward Adams, The Earliest Christian Meeting Places (T&T Clark, 2013).", "note": "The excavators dated the floor to about AD 230; some prefer the later 3rd century. It is before Constantine either way. The phrase “to God Jesus Christ” stands in a soldier’s building, in a province where Christianity was illegal.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 22, "title": "A house by the wall", "text": "Dura-Europos was a Roman garrison town on the Euphrates. In AD 256 a Persian army besieged it. To strengthen the city wall, the defenders filled the nearest street of houses with earth. The city fell and was never lived in again.\n\nThe earth kept everything. When the houses were dug out in the 1930s, one turned out to have been a church.[^dura-europos] An ordinary home had been altered about AD 232: two rooms knocked into one for meeting, and a small room given a basin for baptism.\n\nIts walls were painted. A shepherd carries a sheep. A man walks off with his bed on his back. Two figures stand on water beside a boat. Women come to a tomb with torches.\n\nThese are among the oldest Christian paintings anywhere. They are the same stories you know.\n\n*Grade: Secure. Yale University Art Gallery. Read Mark 2:1–12.*", "sources": [{"id": "dura-europos", "label": "Dura-Europos · the oldest house church", "citation": "Yale University and French Academy excavations, 1928–1937; Carl H. Kraeling, The Christian Building, Excavations at Dura-Europos, Final Report VIII.2 (Yale, 1967); Michael Peppard, The World’s Oldest Church (Yale, 2016). Paintings in the Yale University Art Gallery.", "trail": "Excavation → Kraeling 1967 → Peppard 2016.", "note": "A graffito dates the house’s remodeling to AD 232/233. Peppard argues the procession of women is the virgins of the parable rather than the women at the tomb; the scene is discussed both ways. The paintings include the Good Shepherd, the healing of the paralytic and Jesus and Peter on the water.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 23, "title": "Things to be careful with", "text": "You will hear of other finds. Some need care.\n\nA bone box inscribed “James, son of Joseph, brother of Jesus” appeared in 2002.[^care-nt] It came from a dealer, not a dig, and experts still disagree about whether the last words were added.\n\nA tomb in Jerusalem was announced on television as the family tomb of Jesus. Hardly any scholar accepts it. The names in it were the commonest of the time.\n\nA marble slab with an emperor’s order against moving bodies from tombs was once linked to the resurrection. In 2020 its marble was traced to a Greek island, and it probably concerns something else.\n\nA scrap of Mark’s Gospel was announced as first-century. When published it proved to be more than a century later.\n\nThe rule is the same as ever. Ask where it came from, who accepts it, and what it actually says.", "sources": [{"id": "care-nt", "label": "Finds that need care", "citation": "James ossuary: the 2003 Israel Antiquities Authority committee; Oded Golan acquitted of forgery in 2012, the court not ruling on authenticity. Talpiot tomb: Amos Kloner, ‘Atiqot 29 (1996). Nazareth Inscription: Kyle Harper et al., Journal of Archaeological Science: Reports 30 (2020), tracing the marble to Kos. Mark fragment: P. Oxy. LXXXIII 5345 (published 2018), dated to the late 2nd or early 3rd century.", "trail": "Reports as above.", "note": "The same three questions apply here as to Old Testament finds: where it came from, whether specialists can examine it, and what it actually says.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 24, "title": "What it adds up to", "text": "Set the finds side by side.\n\nThe Gospels and Acts name small villages, pools, gates, coins, officials and their titles, and the ground keeps agreeing with them. Much of that world was destroyed in AD 70. A writer inventing the story later, in another country, would have had no way to get it right.\n\nThe people at the trial have left traces: the governor in stone, the high priest in his tomb. A man crucified in the same years was buried with the nail still in him.\n\nAnd within two centuries, in Rome, on the Euphrates and under a prison yard in Galilee, Christians were worshipping a crucified man as God.\n\nArchaeology helps us investigate the places, rulers and communities of the New Testament. For the resurrection itself, we also examine the early testimony and the reasons those witnesses give.\n\nKeep reading the Gospels and Acts, and explore those reasons in the apologetics book on this shelf. There are good grounds for the Christian hope."}], "source": "Foundation-Claude/new-testament/books/NT-A-archaeology-long.md", "sha256": "66bee4417b8ac72bce0272d3958f7f6f892b061937d70c61eaa633067f7e6919"}}}, {"id": "new-h", "hall": "nt", "subject": "History", "editions": {"short": {"title": "One Lifetime", "subtitle": "From Bethlehem to Rome in twelve steps", "blurb": "A baby in a small town. A teacher by a lake. A cross, an empty tomb, and then a message that crossed the world faster than anything before it. All of it happened in about the length of one long life.", "pages": [{"number": 1, "title": "The world was ready", "text": "When Jesus was born, Rome ruled all the lands around the great sea. There was peace. There were good roads.[^roman-world] Almost everyone could speak Greek.\n\nThat meant news could travel fast and far.\n\nGod had been getting the world ready.", "sources": [{"id": "roman-world", "label": "The Roman world · peace, roads and Greek", "citation": "Augustus, Res Gestae Divi Augusti 13 (the gates of Janus closed: peace on land and sea); Galatians 4:4; Acts 15:21. Everett Ferguson, Backgrounds of Early Christianity (3rd ed., Eerdmans, 2003).", "trail": "Augustus’ own account of his reign → Ferguson 2003.", "note": "The figure of 50,000 miles counts the main paved roads; with lesser roads the network was far larger. Josephus, Philo and inscriptions show Jewish communities and synagogues across the empire, with non-Jewish “God-fearers” attending (Acts 13:16, 26).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 2, "title": "A baby in Bethlehem", "text": "*About 5 BC.*\n\nJesus was born in Bethlehem, the town of King David. A cruel king named Herod ruled the land.[^herod-the-great] When Herod heard that a new king had been born, he tried to kill him.\n\nJesus’s family kept him safe. He grew up in Nazareth, a very small town in the hills.\n\n*Read Luke 2:4–7.*", "sources": [{"id": "herod-the-great", "label": "Herod the Great · Josephus and the stones", "citation": "Josephus, Antiquities 14–17 and Jewish War 1; Macrobius, Saturnalia 2.4.11 (Augustus’ joke that it was better to be Herod’s pig than his son). Ehud Netzer, The Architecture of Herod, the Great Builder (Mohr Siebeck, 2006).", "trail": "Josephus → Netzer’s excavations at Herodium, Masada, Jericho and Caesarea; Netzer found Herod’s tomb at Herodium in 2007.", "note": "Josephus records the executions of Herod’s wife Mariamne and his sons Alexander, Aristobulus and Antipater. No other source mentions the killing of Bethlehem’s infants (Matthew 2:16); a village of Bethlehem’s size might have lost a handful of boys, a small event by Herod’s standards.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 3, "title": "A voice in the desert", "text": "*About AD 28.*\n\nWhen Jesus was about thirty, a man named John began to preach by the Jordan River.[^john-baptist-josephus] He told people to turn back to God, because someone great was coming.\n\nJesus came to John and was baptized.\n\n*Read Mark 1:4–11.*", "sources": [{"id": "john-baptist-josephus", "label": "John the Baptist in Josephus", "citation": "Josephus, Antiquities 18.116–119: Herod Antipas imprisoned John at the fortress of Machaerus and killed him, fearing an uprising; many Jews thought Antipas’ defeat by Aretas was God’s punishment for it. Luke 3:1–2.", "trail": "Josephus → John P. Meier, A Marginal Jew, vol. 2 (Doubleday, 1994).", "note": "Nearly all historians accept this passage as genuine. Josephus explains John’s baptism as purifying the body after the soul was cleansed by righteousness; the Gospels call it a baptism of repentance for forgiveness. The fifteenth year of Tiberius is AD 28/29 counted from Augustus’ death, or AD 26/27 if counted from a joint rule.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 4, "title": "By the lake", "text": "For about three years Jesus taught in the towns around the Sea of Galilee. He healed sick people. He told stories about seeds, sheep and lost coins. He chose twelve friends to follow him. Some of them were fishermen.\n\nCrowds came from everywhere to hear him.\n\n*Read Mark 1:16–20.*"}, {"number": 5, "title": "Up to Jerusalem", "text": "At Passover Jesus went to Jerusalem, the city with God’s temple. People cheered when he rode in.\n\nBut the leaders were afraid of him. They had him arrested at night and took him to the Roman governor, Pontius Pilate.[^pilate-caiaphas-josephus]\n\n*Read Mark 11:7–10.*", "sources": [{"id": "pilate-caiaphas-josephus", "label": "Pilate and Caiaphas in Josephus and Philo", "citation": "Josephus, Antiquities 18.35 (“Joseph, who was called Caiaphas” made high priest), 18.55–62 (Pilate’s standards and aqueduct), 18.89 (Pilate removed after ten years), 18.95 (Caiaphas removed); Philo, Embassy to Gaius 299–305; Tacitus, Annals 15.44.", "trail": "Josephus and Philo → E. Mary Smallwood, The Jews under Roman Rule (Brill, 1976).", "note": "Philo, a contemporary, calls Pilate inflexible and harsh; the Gospels show a governor who gives way to pressure. Both can be true of a man whose position in Rome was shaky (John 19:12). Pilate’s title was prefect; Tacitus calls him procurator, the title of his own day.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 6, "title": "The cross", "text": "*AD 30 or 33.*\n\nPilate gave the order, and Roman soldiers nailed Jesus to a cross.[^crucifixion-date] He died that afternoon. A man named Joseph put his body in a new tomb cut in the rock, and a big stone was rolled across the door.\n\nHis friends hid. They thought it was all over.\n\n*Read Mark 15:33–39, 46.*", "sources": [{"id": "crucifixion-date", "label": "The date of the crucifixion · AD 30 or 33", "citation": "Colin J. Humphreys and W. Graeme Waddington, “Dating the Crucifixion,” Nature 306 (1983): 743–746; Harold W. Hoehner, Chronological Aspects of the Life of Christ (1977); John P. Meier, A Marginal Jew, vol. 1 (Doubleday, 1991), ch. 11.", "trail": "Astronomical tables of the new moon → Humphreys and Waddington; Hoehner (AD 33) and Meier (AD 30).", "note": "Nisan 14 fell on a Friday in AD 30 (7 April) and AD 33 (3 April). The choice depends on when Jesus’ ministry began (Luke 3:1) and how John’s Passover timing relates to the other Gospels’ Passover meal.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 7, "title": "The third day", "text": "On Sunday morning some women went to the tomb. The stone was moved. The tomb was empty.[^empty-tomb-women]\n\nThen Jesus came to them, alive. He came to Peter, to all the disciples, and to more than five hundred people.[^resurrection-creed]\n\nEverything changed that day.\n\n*Read Luke 24:1–8.*", "sources": [{"id": "empty-tomb-women", "label": "The empty tomb and the women witnesses", "citation": "Mark 16:1–8; Matthew 28:11–15; Josephus, Antiquities 4.219 (women not admitted as legal witnesses); Richard Bauckham, Gospel Women (Eerdmans, 2002).", "trail": "The Gospels and Josephus → Bauckham 2002; William Lane Craig, “The Historicity of the Empty Tomb of Jesus,” New Testament Studies 31 (1985): 39–67.", "note": "Matthew reports the opponents’ answer, that the disciples stole the body, which assumes the tomb was empty. Naming women as the first witnesses was a weakness in that culture, which is why many historians count it as a mark of authenticity.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "resurrection-creed", "label": "The early creed of 1 Corinthians 15", "citation": "1 Corinthians 15:3–8; Galatians 1:18–19. Gary R. Habermas and Michael R. Licona, The Case for the Resurrection of Jesus (Kregel, 2004); N. T. Wright, The Resurrection of the Son of God (Fortress, 2003); James D. G. Dunn, Jesus Remembered (Eerdmans, 2003).", "trail": "Paul’s letter (about AD 55) → his visit to Peter and James about three years after his conversion → Habermas, Wright and Dunn.", "note": "Paul uses the terms for receiving and handing on tradition. Most scholars date the formula to within a few years of the crucifixion; Dunn says it was formulated within months. The list includes Peter, James and more than five hundred, most still alive, inviting checking.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 8, "title": "The news gets out", "text": "Seven weeks later the disciples stood up in Jerusalem and told everyone. Thousands believed.\n\nWhen trouble came, the believers moved to other towns. Wherever they went, they told people about Jesus.\n\nIn a city called Antioch people gave them a new name: Christians.[^antioch]\n\n*Read Acts 2:32, 41.*", "sources": [{"id": "antioch", "label": "Antioch and the name “Christians”", "citation": "Acts 11:19–26; Josephus, Jewish War 3.29 (Antioch the third city of the Roman world); Tacitus, Annals 15.44; Pliny, Letters 10.96.", "trail": "Josephus → Wayne A. Meeks and Robert L. Wilken, Jews and Christians in Antioch (Scholars Press, 1978).", "note": "Christianus is a Latin-style party name, like Herodiani; outsiders coined it. Within eighty years Roman officials use it as a legal label (Pliny, Tacitus).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 9, "title": "Paul", "text": "A man named Saul hated the Christians and hunted them. Then Jesus met him on the road, and his whole life turned round. He is also called Paul.\n\nPaul traveled thousands of miles by road and by ship. He started churches in many cities and wrote letters to them. We still read those letters.\n\n*Read Acts 9:3–6.*"}, {"number": 10, "title": "All the way to Rome", "text": "*About AD 60.*\n\nPaul was arrested and sent to Rome, the biggest city in the world. On the way his ship was wrecked in a storm.[^luke-accuracy]\n\nIn Rome he kept on teaching, even as a prisoner. By now there were Christians living in the emperor’s own city.\n\n*Read Acts 28:30–31.*", "sources": [{"id": "luke-accuracy", "label": "Luke as a historian", "citation": "W. M. Ramsay, St. Paul the Traveller and the Roman Citizen (London, 1895); Colin J. Hemer, The Book of Acts in the Setting of Hellenistic History (Mohr Siebeck, 1989); James Smith, The Voyage and Shipwreck of St. Paul (London, 1848).", "trail": "Ramsay’s travels in Asia Minor → Hemer’s catalogue of details in Acts 13–28 → Smith, a yachtsman, on Acts 27.", "note": "Ramsay began doubting Acts and came to regard Luke as a historian of the first rank. Smith checked Acts 27 against the winds, soundings and coast of Malta. Accurate setting does not by itself prove the miracles, but it shows a writer close to the events and careful with them.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 11, "title": "Hard times", "text": "*AD 64.*\n\nA terrible fire burned Rome. The emperor Nero blamed the Christians and had many of them killed.[^nero-tacitus] Peter and Paul both died in Rome around this time.[^peter-paul-rome]\n\nA few years later the Roman army destroyed Jerusalem and its temple. Jesus had said that would happen.\n\n*Read 2 Timothy 4:7–8.*", "sources": [{"id": "nero-tacitus", "label": "Nero’s persecution · Tacitus and Suetonius", "citation": "Tacitus, Annals 15.38–44 (the fire of AD 64; Christus executed by Pontius Pilate under Tiberius); Suetonius, Nero 16.2.", "trail": "Tacitus (writing about AD 116) → Ronald Mellor, Tacitus (Routledge, 1993).", "note": "Tacitus says four of Rome’s fourteen districts were untouched, three leveled and seven badly damaged. He calls the Christians hated for their “abominations” and their faith a “deadly superstition,” and still reports the public’s pity. His statement on Christ’s execution under Pilate is accepted as genuine by nearly all historians.", "url": "https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Tacitus/Annals/15B*.html", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}, {"id": "peter-paul-rome", "label": "Peter and Paul in Rome", "citation": "1 Clement 5 (about AD 96); Ignatius, Romans 4; Eusebius, Church History 2.25.5–8, quoting Gaius of Rome and Dionysius of Corinth; Tertullian, Prescription against Heretics 36.", "trail": "1 Clement → Eusebius → Markus Bockmuehl, Simon Peter in Scripture and Memory (Baker, 2012).", "note": "1 Clement, written from Rome within about thirty years, recalls both apostles’ witness and suffering. The manner of death (Peter crucified, Paul beheaded) comes from later 2nd- and 3rd-century writers, consistent with John 21:18–19.", "url": "https://www.newadvent.org/fathers/1010.htm", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 12, "title": "Written down", "text": "While people who had known Jesus were still alive, his story was written down. Matthew and John had been his disciples. Mark wrote what Peter told him.[^gospel-dates] Luke asked the people who had been there.\n\nThese four books are the Gospels. Christians copied them by hand and carried them everywhere.\n\n*Read Luke 1:3–4.*", "sources": [{"id": "gospel-dates", "label": "When the Gospels were written", "citation": "Papias in Eusebius, Church History 3.39.15–16 (Mark wrote down Peter’s teaching); Irenaeus, Against Heresies 3.1.1. Early dates: Adolf von Harnack, The Date of the Acts and of the Synoptic Gospels (1911); John A. T. Robinson, Redating the New Testament (SCM, 1976). Eyewitness testimony: Richard Bauckham, Jesus and the Eyewitnesses (2nd ed., Eerdmans, 2017).", "trail": "Papias (about AD 110–130) → Irenaeus (about 180) → Harnack, Robinson and Bauckham.", "note": "The usual dating (Mark 65–70, Matthew and Luke 80–90, John 90s) is partly built on the assumption that Jesus’ prophecy of the temple’s fall was written after it. Harnack, not a conservative, dated Acts to about 62. Bauckham shows that the Gospels’ names fit the frequency of names in first-century Palestine, which later writers abroad would not have known.", "url": "https://www.newadvent.org/fathers/250103.htm", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 13, "title": "It kept growing", "text": "The last disciple, John, died as an old man around AD 100.\n\nBy then there were Christians from Spain to Syria. Nobody made them believe. It was not even allowed.[^pliny-trajan] But they kept telling people that Jesus had died for them and was alive.\n\nThey are still telling people. That is how the news came to you.\n\n*Read Matthew 28:18–20.*", "sources": [{"id": "pliny-trajan", "label": "Pliny’s letter to Trajan, about AD 112", "citation": "Pliny the Younger, Letters 10.96 and Trajan’s reply, 10.97.", "trail": "Pliny’s collected letters → A. N. Sherwin-White, The Letters of Pliny: A Historical and Social Commentary (Oxford, 1966).", "note": "Pliny writes that Christians sang “a hymn to Christ as to a god” (carmen Christo quasi deo) and calls the faith a depraved and excessive superstition. The two women were ministrae, the Latin equivalent of deaconesses. Trajan replies that Christians should not be hunted out or accused anonymously.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}], "source": "Foundation-Claude/new-testament/books/NT-H-history-short.md", "sha256": "42961c00d10bf9fb6ff7b1233d3ff8973cd30357a5a0c7cc06ab07526d265ce5"}, "long": {"title": "In the Days of Caesar", "subtitle": "The New Testament’s history, with the world around it", "blurb": "One empire, one language, straight roads and a sea without pirates. Into that world, in a province nobody in Rome cared about, a child was born. Within a lifetime his followers were in the emperor’s own household. This is how it went, and when.", "pages": [{"number": 1, "title": "The world that was ready", "text": "Paul wrote that God sent his Son “when the fullness of time had come.” Look at what that time was like.\n\n**One empire.** Rome ruled every shore of the Mediterranean. For the first time in history a man could travel from Spain to Syria without crossing a border.[^roman-world]\n\n**Peace.** The emperor Augustus had ended a century of civil war. The seas were cleared of pirates.\n\n**Roads.** Fifty thousand miles of them, paved and straight, built for armies and open to anyone.\n\n**One language.** Since Alexander the Great, Greek had been spoken in every market from Italy to India.\n\n**Synagogues.** Jews lived in every large city, and in each synagogue the Scriptures were read aloud every week. Many non-Jews came to listen.\n\nA message could now cross the world in a few years. Nothing like that had been possible before.\n\n*Read Galatians 4:4–5.*", "sources": [{"id": "roman-world", "label": "The Roman world · peace, roads and Greek", "citation": "Augustus, Res Gestae Divi Augusti 13 (the gates of Janus closed: peace on land and sea); Galatians 4:4; Acts 15:21. Everett Ferguson, Backgrounds of Early Christianity (3rd ed., Eerdmans, 2003).", "trail": "Augustus’ own account of his reign → Ferguson 2003.", "note": "The figure of 50,000 miles counts the main paved roads; with lesser roads the network was far larger. Josephus, Philo and inscriptions show Jewish communities and synagogues across the empire, with non-Jewish “God-fearers” attending (Acts 13:16, 26).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 2, "title": "Herod’s kingdom", "text": "Rome had taken Jerusalem in 63 BC. It did not rule the Jews directly at first. It gave them a king.\n\nHerod was not from an old Jewish family, and his subjects never forgot it. He held his throne from 37 to 4 BC by pleasing Rome and killing rivals, among them his wife and three of his sons.[^herod-the-great]\n\nHe was also one of the great builders of the ancient world. He made a harbor where there was only beach. He raised fortresses in the desert. And in Jerusalem he rebuilt the temple on a platform so large that its walls are still the biggest thing in the city.\n\nNear the end of his reign, wise men came from the east asking where the king of the Jews had been born. Herod was not a man to hear that calmly.\n\n*Read Matthew 2:1–18.*", "sources": [{"id": "herod-the-great", "label": "Herod the Great · Josephus and the stones", "citation": "Josephus, Antiquities 14–17 and Jewish War 1; Macrobius, Saturnalia 2.4.11 (Augustus’ joke that it was better to be Herod’s pig than his son). Ehud Netzer, The Architecture of Herod, the Great Builder (Mohr Siebeck, 2006).", "trail": "Josephus → Netzer’s excavations at Herodium, Masada, Jericho and Caesarea; Netzer found Herod’s tomb at Herodium in 2007.", "note": "Josephus records the executions of Herod’s wife Mariamne and his sons Alexander, Aristobulus and Antipater. No other source mentions the killing of Bethlehem’s infants (Matthew 2:16); a village of Bethlehem’s size might have lost a handful of boys, a small event by Herod’s standards.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 3, "title": "The birth", "text": "*About 6 to 4 BC.*\n\nJesus was born in Bethlehem, David’s town, while Herod was still alive. Herod died in 4 BC.[^birth-census] So Jesus was born a few years “before Christ.” The monk who worked out our calendar five hundred years later made a small mistake.\n\nLuke ties the birth to a census. The Romans counted people in order to tax them, and a decree from Egypt shows that people were told to return to their home districts to be counted. The exact census Luke means is still argued over by historians.[^birth-census]\n\nAfter Herod’s death his kingdom was split among his sons. Jesus grew up in Nazareth, a village in Galilee, under one of them: Herod Antipas.\n\n*Read Luke 2:1–7.*", "sources": [{"id": "birth-census", "label": "The birth of Jesus · Herod’s death and Luke’s census", "citation": "Josephus, Antiquities 17.167 and 17.191 (an eclipse before Herod’s death; his reign of 37 years from his appointment); Antiquities 18.1–2, 26 (Quirinius’ census, AD 6). British Library Papyrus 904 (AD 104): the prefect of Egypt orders people to return to their homes for a census. Harold W. Hoehner, Chronological Aspects of the Life of Christ (Zondervan, 1977), ch. 1.", "trail": "Josephus → the Egyptian census papyri → Hoehner; Andrew E. Steinmann, “When Did Herod the Great Reign?” Novum Testamentum 51 (2009): 1–29.", "note": "Most date Herod’s death to 4 BC; Steinmann and others argue for 1 BC. Dionysius Exiguus fixed the AD era in 525. Luke 2:2 is the hard question: Quirinius’ known census was AD 6. Proposed answers include reading prōtē as “before” the census under Quirinius, an earlier registration, or an earlier office held by Quirinius. None is proven; Luke elsewhere is careful with officials (Luke 3:1).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 4, "title": "The land in Jesus’s day", "text": "By the time Jesus was a man, the land was in pieces.\n\n**Galilee**, in the north, was ruled by Herod Antipas. It was green, crowded with villages and centered on a lake full of fish.\n\n**Judea**, in the south, with Jerusalem, had been taken from another of Herod’s sons and put under a Roman governor. From AD 26 to 36 that governor was Pontius Pilate.[^pilate-caiaphas-josephus]\n\n**Samaria** lay between them. Its people were despised by Jews, and returned the feeling.\n\nIn Jerusalem the temple was run by the high priest and a council of leading families. The high priest from AD 18 to 36 was Caiaphas. He kept his post by keeping the peace with Rome.\n\nTwo groups shaped Jewish life: the Pharisees, strict teachers of the Law, and the Sadducees, the priestly aristocracy.[^pharisees-sadducees]\n\n*Read Luke 3:1–2.*", "sources": [{"id": "pilate-caiaphas-josephus", "label": "Pilate and Caiaphas in Josephus and Philo", "citation": "Josephus, Antiquities 18.35 (“Joseph, who was called Caiaphas” made high priest), 18.55–62 (Pilate’s standards and aqueduct), 18.89 (Pilate removed after ten years), 18.95 (Caiaphas removed); Philo, Embassy to Gaius 299–305; Tacitus, Annals 15.44.", "trail": "Josephus and Philo → E. Mary Smallwood, The Jews under Roman Rule (Brill, 1976).", "note": "Philo, a contemporary, calls Pilate inflexible and harsh; the Gospels show a governor who gives way to pressure. Both can be true of a man whose position in Rome was shaky (John 19:12). Pilate’s title was prefect; Tacitus calls him procurator, the title of his own day.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "pharisees-sadducees", "label": "Pharisees, Sadducees and Essenes", "citation": "Josephus, Jewish War 2.119–166; Antiquities 13.171–173 and 18.11–25; Acts 23:6–8.", "trail": "Josephus → Anthony J. Saldarini, Pharisees, Scribes and Sadducees in Palestinian Society (Eerdmans, 2001).", "note": "Josephus, himself a Pharisee, says the Sadducees denied the resurrection and angels, as Acts 23:8 does. He calls these groups “philosophies” for Greek readers, which shapes how he describes them.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 5, "title": "John the Baptist", "text": "*About AD 28.*\n\nLuke dates what happened next more carefully than anything else in his book. It was the fifteenth year of the emperor Tiberius. He names the governor, three local rulers and the high priests.\n\nIn that year a man named John came out of the desert and told people to repent and be baptized, because someone greater was coming. Crowds went to him.\n\nThe Jewish historian Josephus also describes John.[^john-baptist-josephus] He says he was a good man who called the Jews to live rightly and be baptized, that crowds gathered, and that Herod Antipas had him executed for fear of a rising. The Gospels add the reason John himself gave offence: he said Antipas’s marriage was unlawful.\n\nJohn is one of the best-attested figures in the New Testament.\n\n*Read Luke 3:1–18.*", "sources": [{"id": "john-baptist-josephus", "label": "John the Baptist in Josephus", "citation": "Josephus, Antiquities 18.116–119: Herod Antipas imprisoned John at the fortress of Machaerus and killed him, fearing an uprising; many Jews thought Antipas’ defeat by Aretas was God’s punishment for it. Luke 3:1–2.", "trail": "Josephus → John P. Meier, A Marginal Jew, vol. 2 (Doubleday, 1994).", "note": "Nearly all historians accept this passage as genuine. Josephus explains John’s baptism as purifying the body after the soul was cleansed by righteousness; the Gospels call it a baptism of repentance for forgiveness. The fifteenth year of Tiberius is AD 28/29 counted from Augustus’ death, or AD 26/27 if counted from a joint rule.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 6, "title": "Three years", "text": "*About AD 28 to 30, or 30 to 33.*\n\nJesus was baptized by John and began to teach. He was about thirty.\n\nMost of his work was in Galilee, in the towns around the lake: Capernaum, Chorazin, Bethsaida, Magdala. He taught in their synagogues, healed, and gathered twelve disciples, most of them local men. He told stories about seed, sheep, debts and weddings.\n\nHe went up to Jerusalem for the great feasts, as every observant Jew did.\n\nHe never traveled more than about a hundred miles from where he was born. He wrote nothing. He held no office. By every measure the ancient world used, he should have been forgotten in a generation.\n\n*Read Mark 1:14–39.*"}, {"number": 7, "title": "The last week", "text": "Jesus came to Jerusalem for the last time at Passover. The city’s population swelled many times over at the feast, and the governor came up from the coast with extra troops.\n\nHe rode in on a donkey to cheering crowds. He drove the traders out of the temple courts. He taught there daily, and the leaders could not answer him.\n\nOn Thursday night he ate the Passover with his disciples. Afterward he was arrested in an olive grove, tried before the high priest in the night, and taken at dawn to Pilate.\n\nPilate found no crime in him and had him crucified anyway. Roman governors were not chosen for their courage.\n\n*Read Mark 14:53–15:15.*"}, {"number": 8, "title": "The date of the cross", "text": "Can we say when?\n\nIt was a Friday at Passover, with Pilate governor and Caiaphas high priest. That means between AD 26 and 36. In those years Passover fell on a Friday only twice: on 7 April AD 30 and on 3 April AD 33.[^crucifixion-date] Scholars are divided between the two.\n\nCrucifixion was Rome’s punishment for slaves and rebels.[^crucifixion-rome] It was designed to be slow, public and shameful. Roman writers avoided describing it.\n\nJesus died in about six hours. A member of the council, Joseph of Arimathea, asked for the body and laid it in his own new tomb, cut in rock, in a garden close by.[^yehohanan][^holy-sepulchre] The entrance was closed with a stone.\n\nThat was Friday evening.\n\n*Read John 19:16–42.*", "sources": [{"id": "crucifixion-date", "label": "The date of the crucifixion · AD 30 or 33", "citation": "Colin J. Humphreys and W. Graeme Waddington, “Dating the Crucifixion,” Nature 306 (1983): 743–746; Harold W. Hoehner, Chronological Aspects of the Life of Christ (1977); John P. Meier, A Marginal Jew, vol. 1 (Doubleday, 1991), ch. 11.", "trail": "Astronomical tables of the new moon → Humphreys and Waddington; Hoehner (AD 33) and Meier (AD 30).", "note": "Nisan 14 fell on a Friday in AD 30 (7 April) and AD 33 (3 April). The choice depends on when Jesus’ ministry began (Luke 3:1) and how John’s Passover timing relates to the other Gospels’ Passover meal.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "crucifixion-rome", "label": "Crucifixion in Roman writers", "citation": "Cicero, Against Verres 2.5.165 (“a most cruel and disgusting punishment”) and For Rabirius 16; Martin Hengel, Crucifixion in the Ancient World and the Folly of the Message of the Cross (Fortress, 1977).", "trail": "Cicero → Hengel 1977.", "note": "Hengel showed how seldom educated writers described crucifixion, and how shameful it was, which is why the Christian message about a crucified Lord sounded like “folly” (1 Corinthians 1:23). No one inventing a hero for that world would have chosen a cross.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "yehohanan", "label": "Yehohanan · the crucified man from Giv‘at ha-Mivtar", "citation": "Vassilios Tzaferis, “Jewish Tombs at and near Giv‘at ha-Mivtar, Jerusalem,” Israel Exploration Journal 20 (1970): 18–32; Joseph Zias and Eliezer Sekeles, “The Crucified Man from Giv‘at ha-Mivtar: A Reappraisal,” IEJ 35 (1985): 22–27. Israel Museum.", "trail": "The 1968 tomb → Tzaferis 1970 → Zias and Sekeles 1985.", "note": "The nail is about 11.5 cm long, bent at the tip, with a small wooden plate under its head. The 1985 reappraisal found no clear sign of nails in the arms, which may have been tied. A second heel with a nail was reported from Gavello, Italy, in 2018. Yehohanan was buried in a family tomb, as the Gospels say of Jesus.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "holy-sepulchre", "label": "The Church of the Holy Sepulchre · quarry, tombs and gardens", "citation": "Eusebius, Life of Constantine 3.25–40 (Hadrian’s temple removed; the tomb uncovered); Dan Bahat, “Does the Holy Sepulchre Church Mark the Burial of Jesus?” Biblical Archaeology Review 12:3 (1986); excavations under the church floor by Francesca Romana Stasolla (Sapienza University of Rome), 2022–.", "trail": "Eusebius → Virgilio Corbo’s excavations (1960s–70s) → Bahat 1986 → Stasolla.", "note": "Kathleen Kenyon’s work showed the site was outside the wall in AD 30. Rock-cut tombs of the period survive inside the church. Stasolla’s team reported pollen and remains of olive and vine from the Roman period, which fits John 19:41. The Garden Tomb, a popular alternative, is an older tomb of the Iron Age.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 9, "title": "The third day", "text": "On Sunday morning some women went to the tomb and found it open and empty.[^empty-tomb-women]\n\nOver the next forty days Jesus appeared to Mary Magdalene, to Peter, to two travelers on a road, to the disciples together, to more than five hundred people at once, and to his brother James, who had not believed in him.[^resurrection-creed]\n\nThese are the claims. A historian can at least say what happened next.\n\nSeven weeks after the crucifixion, in the city where it took place, the same disciples who had run away were announcing in public that God had raised Jesus. The authorities had every reason to stop them and could not produce a body. Thousands believed.\n\nWhatever happened that Sunday, it turned frightened men into ones who could not be silenced.\n\n*Read Luke 24 and Acts 2:22–41.*", "sources": [{"id": "empty-tomb-women", "label": "The empty tomb and the women witnesses", "citation": "Mark 16:1–8; Matthew 28:11–15; Josephus, Antiquities 4.219 (women not admitted as legal witnesses); Richard Bauckham, Gospel Women (Eerdmans, 2002).", "trail": "The Gospels and Josephus → Bauckham 2002; William Lane Craig, “The Historicity of the Empty Tomb of Jesus,” New Testament Studies 31 (1985): 39–67.", "note": "Matthew reports the opponents’ answer, that the disciples stole the body, which assumes the tomb was empty. Naming women as the first witnesses was a weakness in that culture, which is why many historians count it as a mark of authenticity.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "resurrection-creed", "label": "The early creed of 1 Corinthians 15", "citation": "1 Corinthians 15:3–8; Galatians 1:18–19. Gary R. Habermas and Michael R. Licona, The Case for the Resurrection of Jesus (Kregel, 2004); N. T. Wright, The Resurrection of the Son of God (Fortress, 2003); James D. G. Dunn, Jesus Remembered (Eerdmans, 2003).", "trail": "Paul’s letter (about AD 55) → his visit to Peter and James about three years after his conversion → Habermas, Wright and Dunn.", "note": "Paul uses the terms for receiving and handing on tradition. Most scholars date the formula to within a few years of the crucifixion; Dunn says it was formulated within months. The list includes Peter, James and more than five hundred, most still alive, inviting checking.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 10, "title": "From Jerusalem to Antioch", "text": "*AD 30s.*\n\nAt first every believer was a Jew, and they met in the temple courts.\n\nThen Stephen was stoned for saying that God was not confined to the temple. A persecution scattered the believers, and they talked wherever they went. In Samaria. On the coast. In Antioch in Syria, the third city of the empire, where for the first time large numbers of non-Jews believed.\n\nIt was in Antioch that outsiders coined a name for them: *Christians.*[^antioch]\n\nThe leader of the persecution was a young Pharisee, Saul of Tarsus. On the road to Damascus, about AD 33 to 35, he met the risen Jesus. He is better known by his Roman name, Paul.\n\n*Read Acts 8:1–4, 9:1–19, 11:19–26.*", "sources": [{"id": "antioch", "label": "Antioch and the name “Christians”", "citation": "Acts 11:19–26; Josephus, Jewish War 3.29 (Antioch the third city of the Roman world); Tacitus, Annals 15.44; Pliny, Letters 10.96.", "trail": "Josephus → Wayne A. Meeks and Robert L. Wilken, Jews and Christians in Antioch (Scholars Press, 1978).", "note": "Christianus is a Latin-style party name, like Herodiani; outsiders coined it. Within eighty years Roman officials use it as a legal label (Pliny, Tacitus).", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 11, "title": "A king dies at Caesarea", "text": "*AD 44.*\n\nFor three years the whole land was reunited under Herod Agrippa I, grandson of the old king. He had James, the brother of John, beheaded, and put Peter in prison.\n\nThen, at Caesarea, he died. Luke says he appeared in royal robes, the crowd shouted that he spoke as a god, and he was struck down.\n\nJosephus tells the same story without knowing Luke’s.[^agrippa-death] Agrippa entered the theater at dawn in a robe woven of silver, which blazed in the sunrise. The crowd hailed him as more than mortal. He did not rebuke them. He was seized with pain and died within five days.\n\nTwo writers, one Christian and one Jewish, are describing the same morning.\n\n*Read Acts 12:1–4, 20–23.*", "sources": [{"id": "agrippa-death", "label": "The death of Herod Agrippa I · Acts and Josephus", "citation": "Acts 12:19–23; Josephus, Antiquities 19.343–350.", "trail": "The two accounts, written independently.", "note": "Both place it at Caesarea, at a public occasion, with the crowd hailing the king as a god and his sudden collapse. Josephus adds the silver robe and an owl he took for an omen; Luke says the angel of the Lord struck him because he did not give God the glory. The agreement is in the facts, the difference in emphasis.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 12, "title": "Paul’s first journeys", "text": "*AD 47 to 52.*\n\nFrom Antioch the church sent Paul and Barnabas west. They sailed to Cyprus, where the Roman governor believed, and then went up into what is now central Turkey, founding churches in four towns.\n\nThat raised a question. Did a non-Jew have to become a Jew in order to follow Jesus? About AD 49 the apostles met in Jerusalem and said no. It was one of the most important decisions in history.\n\nOn his second journey Paul crossed into Europe: Philippi, Thessalonica, Athens, and then eighteen months in Corinth. A stone inscription lets us date that stay. The governor who heard his case, Gallio, held office from AD 51 to 52.[^gallio-inscription]\n\nFrom Corinth Paul wrote to the Thessalonians. Those letters are among the oldest Christian writings we have.\n\n*Read Acts 15:1–21 and 18:1–17.*", "sources": [{"id": "gallio-inscription", "label": "The Gallio inscription · Delphi, AD 52", "citation": "Letter of Claudius to Delphi, nine fragments in the Delphi Archaeological Museum; published by Émile Bourguet (1905); Sylloge Inscriptionum Graecarum³ 801 D. Adolf Deissmann, Paul: A Study in Social and Religious History (2nd ed., 1926), appendix I.", "trail": "The stone → Bourguet → Deissmann → Jerome Murphy-O’Connor, St. Paul’s Corinth (3rd ed., Liturgical Press, 2002).", "note": "The letter is dated by Claudius’ 26th acclamation as imperator, which falls in the first half of AD 52. Proconsuls served for a year from early summer, so Gallio’s year was 51–52 (or possibly 52–53). Acts 18 then dates Paul’s eighteen months in Corinth to about 50–52.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 13, "title": "Ephesus and the letters", "text": "*AD 52 to 57.*\n\nPaul’s third journey centered on Ephesus, the great port of western Turkey, where he stayed nearly three years. From there the message spread up the river valleys to towns he never visited himself.\n\nIn these years he wrote his longest letters: to the Corinthians, the Galatians and the Romans. They are real letters, to real churches with real quarrels. They mention shared friends, travel plans and a collection of money for the poor in Jerusalem.\n\nThey are also the earliest evidence for what Christians believed. Writing about AD 55, Paul reminds the Corinthians of what he had handed on to them as of first importance: that Christ died for our sins, was buried, was raised on the third day, and was seen.[^resurrection-creed]\n\nHe had received that summary himself, twenty years before.\n\n*Read 1 Corinthians 15:1–11.*", "sources": [{"id": "resurrection-creed", "label": "The early creed of 1 Corinthians 15", "citation": "1 Corinthians 15:3–8; Galatians 1:18–19. Gary R. Habermas and Michael R. Licona, The Case for the Resurrection of Jesus (Kregel, 2004); N. T. Wright, The Resurrection of the Son of God (Fortress, 2003); James D. G. Dunn, Jesus Remembered (Eerdmans, 2003).", "trail": "Paul’s letter (about AD 55) → his visit to Peter and James about three years after his conversion → Habermas, Wright and Dunn.", "note": "Paul uses the terms for receiving and handing on tradition. Most scholars date the formula to within a few years of the crucifixion; Dunn says it was formulated within months. The list includes Peter, James and more than five hundred, most still alive, inviting checking.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 14, "title": "Paul in chains", "text": "*AD 57 to 62.*\n\nPaul took the collection to Jerusalem. In the temple a mob accused him of bringing a non-Jew past the barrier, and Roman soldiers pulled him out alive.\n\nHe was held for two years at Caesarea under the governors Felix and Festus, and spoke before King Agrippa II. As a Roman citizen he appealed to the emperor and was sent to Rome by sea.\n\nThe voyage, in Acts 27, is the most detailed account of a sea journey to survive from the ancient world.[^luke-accuracy] A storm drove the ship for two weeks and wrecked it on Malta.\n\nActs ends with Paul in Rome about AD 62, under guard in a rented house, teaching anyone who came. Luke does not say what happened to him. Perhaps, when he finished writing, it had not happened yet.\n\n*Read Acts 27:13–44 and 28:16–31.*", "sources": [{"id": "luke-accuracy", "label": "Luke as a historian", "citation": "W. M. Ramsay, St. Paul the Traveller and the Roman Citizen (London, 1895); Colin J. Hemer, The Book of Acts in the Setting of Hellenistic History (Mohr Siebeck, 1989); James Smith, The Voyage and Shipwreck of St. Paul (London, 1848).", "trail": "Ramsay’s travels in Asia Minor → Hemer’s catalogue of details in Acts 13–28 → Smith, a yachtsman, on Acts 27.", "note": "Ramsay began doubting Acts and came to regard Luke as a historian of the first rank. Smith checked Acts 27 against the winds, soundings and coast of Malta. Accurate setting does not by itself prove the miracles, but it shows a writer close to the events and careful with them.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 15, "title": "Nero", "text": "*AD 64.*\n\nIn July of AD 64 Rome burned for six days. Ten of its fourteen districts were damaged or destroyed. People said the emperor Nero had started it himself to clear ground for a palace.\n\nThe Roman historian Tacitus tells what he did about the rumor.[^nero-tacitus] He blamed the Christians. They were covered in animal skins and torn by dogs, or crucified, or set alight to serve as lamps in his gardens. Tacitus despised Christians, and even he says people began to pity them.\n\nEarly Christian writers say that Peter and Paul both died at Rome in these years: Paul by the sword, as a citizen, and Peter on a cross.[^peter-paul-rome]\n\nIt was thirty years since the resurrection. The church in the capital was already large enough to be blamed for a disaster.\n\n*Read 2 Timothy 4:6–8.*", "sources": [{"id": "nero-tacitus", "label": "Nero’s persecution · Tacitus and Suetonius", "citation": "Tacitus, Annals 15.38–44 (the fire of AD 64; Christus executed by Pontius Pilate under Tiberius); Suetonius, Nero 16.2.", "trail": "Tacitus (writing about AD 116) → Ronald Mellor, Tacitus (Routledge, 1993).", "note": "Tacitus says four of Rome’s fourteen districts were untouched, three leveled and seven badly damaged. He calls the Christians hated for their “abominations” and their faith a “deadly superstition,” and still reports the public’s pity. His statement on Christ’s execution under Pilate is accepted as genuine by nearly all historians.", "url": "https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Tacitus/Annals/15B*.html", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}, {"id": "peter-paul-rome", "label": "Peter and Paul in Rome", "citation": "1 Clement 5 (about AD 96); Ignatius, Romans 4; Eusebius, Church History 2.25.5–8, quoting Gaius of Rome and Dionysius of Corinth; Tertullian, Prescription against Heretics 36.", "trail": "1 Clement → Eusebius → Markus Bockmuehl, Simon Peter in Scripture and Memory (Baker, 2012).", "note": "1 Clement, written from Rome within about thirty years, recalls both apostles’ witness and suffering. The manner of death (Peter crucified, Paul beheaded) comes from later 2nd- and 3rd-century writers, consistent with John 21:18–19.", "url": "https://www.newadvent.org/fathers/1010.htm", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 16, "title": "The fall of Jerusalem", "text": "*AD 66 to 70.*\n\nIn AD 66 Judea revolted. Rome sent its best general, Vespasian, with sixty thousand men. When he left to become emperor, his son Titus finished the war.\n\nIn the spring of AD 70 Titus surrounded Jerusalem, which was packed with Passover pilgrims. The siege lasted five months. Josephus, who was there, describes the famine.[^jerusalem-70] In August the temple was burned. The soldiers levered its buildings off the platform stone by stone.\n\nJesus had foretold it about forty years before, in tears.\n\nThe temple has never been rebuilt. From this point Judaism became a faith of synagogue and Scripture, and Christianity and Judaism went separate ways. For the historian, AD 70 is a wall: anything that accurately describes Jerusalem before that date was written by someone who had seen it or had spoken to someone who had.\n\n*Read Luke 21:5–6, 20–24.*", "sources": [{"id": "jerusalem-70", "label": "The fall of Jerusalem, AD 70", "citation": "Josephus, Jewish War, books 5–6 (the siege and burning of the temple); 3.64–69 (Vespasian’s army); Luke 19:41–44; 21:20–24.", "trail": "Josephus, an eyewitness on the Roman side → archaeological evidence: the Burnt House in the Jewish Quarter (Nahman Avigad) and the stones at the south-west corner.", "note": "Josephus inflates some numbers, as ancient historians often did; the destruction itself is plain in the ground. Whether the Gospels were written before or after AD 70 is debated, and their accurate pre-70 detail favors writers who knew the city.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 17, "title": "The writing of the Gospels", "text": "When were the four Gospels written?\n\nMost scholars put Mark first, around AD 65 to 70; Matthew and Luke in the following twenty years; and John in the 90s.[^gospel-dates] Some argue that the first three are earlier, since Acts, which is Luke’s second volume, ends about AD 62 with no word of Paul’s death, Nero’s persecution or the fall of Jerusalem.\n\nTake the later dates if you like. The gap between the events and the books is then thirty-five to sixty-five years. People who had been twenty at the crucifixion were fifty-five to eighty-five.\n\nEarly Christian writers say that Mark wrote down the preaching of Peter, that Luke traveled with Paul, and that Matthew and John were among the Twelve. Luke says he drew on those who were “eyewitnesses from the beginning.”\n\nThese were not legends handed down for centuries. They were written while people who had been there could still object.\n\n*Read Luke 1:1–4.*", "sources": [{"id": "gospel-dates", "label": "When the Gospels were written", "citation": "Papias in Eusebius, Church History 3.39.15–16 (Mark wrote down Peter’s teaching); Irenaeus, Against Heresies 3.1.1. Early dates: Adolf von Harnack, The Date of the Acts and of the Synoptic Gospels (1911); John A. T. Robinson, Redating the New Testament (SCM, 1976). Eyewitness testimony: Richard Bauckham, Jesus and the Eyewitnesses (2nd ed., Eerdmans, 2017).", "trail": "Papias (about AD 110–130) → Irenaeus (about 180) → Harnack, Robinson and Bauckham.", "note": "The usual dating (Mark 65–70, Matthew and Luke 80–90, John 90s) is partly built on the assumption that Jesus’ prophecy of the temple’s fall was written after it. Harnack, not a conservative, dated Acts to about 62. Bauckham shows that the Gospels’ names fit the frequency of names in first-century Palestine, which later writers abroad would not have known.", "url": "https://www.newadvent.org/fathers/250103.htm", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 18, "title": "John and the end of the century", "text": "*About AD 81 to 96.*\n\nThe last of the apostles was John. Early writers say he lived to a great age at Ephesus.\n\nUnder the emperor Domitian, who liked to be addressed as “lord and god,” Christians in the province of Asia came under pressure to offer incense to the emperor’s image.[^domitian] John was exiled to the island of Patmos. There he wrote Revelation, with its letters to seven churches in seven real towns.\n\nWith John’s death the generation that had seen Jesus was gone.\n\nBut they had left pupils. Polycarp of Smyrna had been taught by John. As an old man he was ordered to curse Christ, and answered that he had served him eighty-six years and been done no wrong.[^polycarp-irenaeus] As a boy, Irenaeus listened to Polycarp. He wrote about AD 180.\n\nJohn to Polycarp to Irenaeus: three lives span the first two centuries.\n\n*Read Revelation 1:9–11.*", "sources": [{"id": "domitian", "label": "Domitian, “lord and god”", "citation": "Suetonius, Domitian 13.2 (dominus et deus noster); Revelation 1:9; Irenaeus, Against Heresies 5.30.3 (Revelation seen near the end of Domitian’s reign).", "trail": "Suetonius and Irenaeus → Steven J. Friesen, Imperial Cults and the Apocalypse of John (Oxford, 2001).", "note": "Historians differ on how widespread persecution under Domitian was; the pressure in Revelation looks local and social as much as imperial. A minority dates Revelation before AD 70.", "url": "https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Suetonius/12Caesars/Domitian*.html", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}, {"id": "polycarp-irenaeus", "label": "John, Polycarp and Irenaeus", "citation": "Martyrdom of Polycarp 9.3 (“Eighty-six years I have served him”); Irenaeus, Against Heresies 3.3.4; his Letter to Florinus in Eusebius, Church History 5.20.5–7.", "trail": "The Martyrdom (shortly after AD 155) → Irenaeus → Eusebius.", "note": "Irenaeus remembers, as a boy, Polycarp describing his conversations with John and others who had seen the Lord. It is a chain of memory across three lives, with each link named.", "url": "https://www.newadvent.org/fathers/0102.htm", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 19, "title": "A governor’s question", "text": "*About AD 112.*\n\nPliny was a Roman lawyer sent to govern a province on the Black Sea. He found Christians there and did not know what to do with them, so he wrote to the emperor Trajan. His letter survives.[^pliny-trajan]\n\nHe had questioned some who had left the faith and tortured two women who were deaconesses. This is what he learned. Christians met before dawn on a fixed day. They sang a hymn to Christ as to a god. They swore an oath, not to commit crimes, but to avoid theft, adultery and lying. Later they met again for an ordinary meal.\n\nHe adds that there were so many of them, in the towns and in the countryside, that the temples had been almost empty.\n\nThis is eighty years after the crucifixion, a thousand miles away, described by a man who thought it all a “depraved superstition.”", "sources": [{"id": "pliny-trajan", "label": "Pliny’s letter to Trajan, about AD 112", "citation": "Pliny the Younger, Letters 10.96 and Trajan’s reply, 10.97.", "trail": "Pliny’s collected letters → A. N. Sherwin-White, The Letters of Pliny: A Historical and Social Commentary (Oxford, 1966).", "note": "Pliny writes that Christians sang “a hymn to Christ as to a god” (carmen Christo quasi deo) and calls the faith a depraved and excessive superstition. The two women were ministrae, the Latin equivalent of deaconesses. Trajan replies that Christians should not be hunted out or accused anonymously.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 20, "title": "Growth under pressure", "text": "*AD 100 to 300.*\n\nFor two more centuries Christianity was illegal. Persecution was usually local and brief, but it could be savage. Christians would not sacrifice to the gods or the emperor, and that looked like disloyalty.\n\nThey had no buildings. They met in homes. A house in the frontier town of Dura-Europos was converted into a church about AD 232.[^dura-europos] A prayer hall at Megiddo, paid for by a Roman centurion, is from about the same time.[^megiddo-mosaic]\n\nAnd they grew. Their neighbors noticed how they lived. They took in babies that had been left out to die. In plagues they nursed the sick instead of running away. They treated slaves as brothers at the table. They faced death without fear.\n\nBy AD 300 perhaps one person in ten in the empire was a Christian.[^church-growth]\n\n*Read 1 Peter 2:11–17.*", "sources": [{"id": "dura-europos", "label": "Dura-Europos · the oldest house church", "citation": "Yale University and French Academy excavations, 1928–1937; Carl H. Kraeling, The Christian Building, Excavations at Dura-Europos, Final Report VIII.2 (Yale, 1967); Michael Peppard, The World’s Oldest Church (Yale, 2016). Paintings in the Yale University Art Gallery.", "trail": "Excavation → Kraeling 1967 → Peppard 2016.", "note": "A graffito dates the house’s remodeling to AD 232/233. Peppard argues the procession of women is the virgins of the parable rather than the women at the tomb; the scene is discussed both ways. The paintings include the Good Shepherd, the healing of the paralytic and Jesus and Peter on the water.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "megiddo-mosaic", "label": "The Megiddo prayer hall · “to God Jesus Christ”", "citation": "Yotam Tepper and Leah Di Segni, A Christian Prayer Hall of the Third Century CE at Kefar ‘Othnay (Legio): Excavations at the Megiddo Prison 2005 (Israel Antiquities Authority, 2006).", "trail": "The 2005 excavation → Tepper and Di Segni 2006 → Edward Adams, The Earliest Christian Meeting Places (T&T Clark, 2013).", "note": "The excavators dated the floor to about AD 230; some prefer the later 3rd century. It is before Constantine either way. The phrase “to God Jesus Christ” stands in a soldier’s building, in a province where Christianity was illegal.", "url": "", "consulted": "Compiled from the published record, November 2026."}, {"id": "church-growth", "label": "How the church grew", "citation": "Rodney Stark, The Rise of Christianity (Princeton, 1996); Dionysius of Alexandria on the plague, in Eusebius, Church History 7.22; Emperor Julian, Letter to Arsacius (about AD 362); Didache 2.2 and the Epistle to Diognetus 5.6 (Christians do not expose infants).", "trail": "Eusebius and Julian → Stark 1996.", "note": "Stark estimated about 40 percent growth per decade, reaching some six million Christians, about a tenth of the empire, by AD 300. These are estimates from models. Julian, who wanted paganism restored, complained that the Christians cared for their own poor and for pagans too.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 21, "title": "Constantine", "text": "*AD 312 to 325.*\n\nIn AD 303 the emperor Diocletian launched the worst persecution of all. Churches were pulled down and copies of the Scriptures burned.\n\nIt failed. In AD 312 a new emperor, Constantine, won the throne after praying to the God of the Christians. The next year he made Christianity legal.\n\nIn AD 325 he called the bishops to a council at Nicaea.[^nicaea] You may hear that this council chose the books of the Bible and voted to make Jesus God. It did neither. The books were not on its agenda. The question was how to put into words what Christians already believed and sang: that the Son is fully God. Those who came included men with scars from the persecution.\n\nA mosaic floor a century older already reads “God Jesus Christ.”", "sources": [{"id": "nicaea", "label": "Constantine and Nicaea", "citation": "Eusebius, Life of Constantine 1.28–31 and 3.6–14; Lactantius, On the Deaths of the Persecutors 12–13, 44 and 48; Theodoret, Church History, book 1 (bishops bearing the marks of persecution). Bruce M. Metzger, The Canon of the New Testament (Oxford, 1987).", "trail": "Eusebius and Lactantius → Metzger 1987; on the popular myth, Bart D. Ehrman, Truth and Fiction in The Da Vinci Code (Oxford, 2004).", "note": "The canons and creed of Nicaea say nothing about which books belong in the Bible. The council addressed Arius’ teaching that the Son was created; it used Scripture already accepted by all sides. Even scholars who are not Christians, such as Ehrman, reject the idea that Nicaea chose the books or invented Jesus’ divinity.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 22, "title": "How the books were kept", "text": "The apostles’ writings were read aloud in churches from the start, beside the Old Testament. Paul tells one church to pass his letter to the next.\n\nThey were copied by hand, at first by ordinary Christians on cheap papyrus. Christians were early users of the book with pages, which was easier to carry and to search than a scroll.\n\nBy about AD 200 there were books holding all of Paul’s letters, or two Gospels, in one volume. A list from about that time already names most of the New Testament.[^canon-manuscripts] By AD 367 the list was exactly ours.\n\nNo council made these books Scripture. Churches from Spain to Syria were already reading them, because they came from the apostles and their companions.\n\nThousands of handwritten copies survive. A few are from within a century of the originals.\n\n*Read Colossians 4:16 and 2 Peter 3:15–16.*", "sources": [{"id": "canon-manuscripts", "label": "How the books were kept", "citation": "Colossians 4:16; Papyrus 46 (letters of Paul, about AD 200; Chester Beatty Library and University of Michigan); Papyrus 75 (Luke and John, about AD 200; Vatican Library); the Muratorian Fragment; Athanasius, Festal Letter 39 (AD 367). Larry W. Hurtado, The Earliest Christian Artifacts (Eerdmans, 2006).", "trail": "The papyri → Hurtado 2006 → Metzger, The Canon of the New Testament (1987); manuscript counts from the Institute for New Testament Textual Research (Münster).", "note": "Most date the Muratorian list to the late 2nd century; a minority argue for the 4th. The Münster register lists about 5,800 Greek manuscripts. Christians preferred the codex far more than their neighbors, which Hurtado treats as a deliberate choice for their Scriptures.", "url": "https://www.newadvent.org/fathers/2806039.htm", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}, {"number": 23, "title": "What changed", "text": "It is hard to see how much, because we live inside the result.\n\nThe ancient world took for granted that the strong mattered and the weak did not. Unwanted babies were left on trash heaps. Slaves were property. Crowds watched men kill each other for sport. Mercy was a weakness.\n\nThe people who followed a crucified man believed that every human being bore the image of God and that God himself had taken the lowest place. Slowly, and with many failures, that belief built hospitals, ended the games, and taught the world that the poor and the sick have a claim on us.\n\nHistorians who are not Christians have said that many things modern people believe about human worth came from here and nowhere else.[^what-changed]\n\n*Read Philippians 2:5–11.*", "sources": [{"id": "what-changed", "label": "What changed · historians on Christianity’s effect", "citation": "Tom Holland, Dominion: How the Christian Revolution Remade the World (Basic Books, 2019); Larry Siedentop, Inventing the Individual (Harvard, 2014); Theodoret, Church History 5.26 (the monk Telemachus and the end of the gladiatorial games); Basil of Caesarea’s hospital (about AD 369).", "trail": "Theodoret and Basil’s letters → Holland and Siedentop.", "note": "Holland wrote Dominion as a historian who was not then a believer. He argues that ideas of human dignity, the care of the weak and the equal worth of every person grew from Christian roots. Historians discuss how far and how fast; the change in direction is widely acknowledged.", "url": "", "consulted": "Compiled from the published record, November 2026."}]}, {"number": 24, "title": "One lifetime", "text": "Go back to the beginning and count.\n\nIn about AD 30 a teacher from a village is executed in an unimportant province. By AD 49 there are Christians in Rome.[^suetonius-claudius] By AD 64 there are enough to blame for a fire. By AD 112 a governor reports that the temples are empty. By AD 230 a Roman officer is paying for a church floor.\n\nNothing in the ancient world spread like this, and it spread without armies, money or permission.\n\nThe people who carried it gave one reason. They said that Jesus, who was crucified under Pontius Pilate, had been raised from the dead, and that they or their teachers had seen him.\n\nHistory can tell you that they said it, and what it cost them. Whether they were right is the question the New Testament was written to help you answer.\n\n*Read John 20:30–31.*", "sources": [{"id": "suetonius-claudius", "label": "Suetonius on Claudius · Jews expelled from Rome", "citation": "Suetonius, Claudius 25.4: Claudius expelled the Jews “constantly making disturbances at the instigation of Chrestus”; Acts 18:2. Orosius, History against the Pagans 7.6.15, dates it to AD 49.", "trail": "Suetonius → Orosius → Rainer Riesner, Paul’s Early Period (Eerdmans, 1998).", "note": "Most historians think “Chrestus” is a misunderstanding of Christus, so disputes over Jesus reached Rome’s Jewish community within twenty years. A minority think Chrestus was a local agitator. Orosius’ date is debated but widely used.", "url": "https://penelope.uchicago.edu/Thayer/E/Roman/Texts/Suetonius/12Caesars/Claudius*.html", "consulted": "Compiled from the published record, November 2026. The link was checked that day."}]}], "source": "Foundation-Claude/new-testament/books/NT-H-history-long.md", "sha256": "aa10aab09c8dad897849cb4515b27150447e910f0a613e16ee8a36de19378bbd"}}}, {"id": "new-r", "hall": "nt", "subject": "Apologetics", "editions": {"short": {"title": "How Do We Know?", "subtitle": "Eight questions about Jesus and the New Testament, and how to answer them kindly", "blurb": "Was Jesus real? Who wrote down his story? Did someone change it? Did he really come back to life? These are fair questions. Here are honest answers you can understand and pass on.", "pages": [{"number": 1, "title": "Ask first", "text": "When a friend says something about Jesus that you think is wrong, start with a question.\n\n**“What do you mean?”**\n\n**“How do you know?”**\n\nThen listen. Your friend may have a question you have not thought of. After that you can share one thing you know. Paul gave people reasons to believe in Jesus, and we can too. Be kind when you do.\n\n*Read Acts 17:2–4.*"}, {"number": 2, "title": "“Was Jesus a real person?”", "text": "Yes. Even people who did not like Christians wrote about him.\n\nA Roman named Tacitus wrote that Christ was put to death by Pontius Pilate. A Jewish writer named Josephus wrote about Jesus’s brother James.\n\nNobody back then said, “There was no such man.”"}, {"number": 3, "title": "“Who wrote the Gospels?”", "text": "People who were there, or who talked with people who were there.\n\nMatthew and John were Jesus’s disciples. Mark wrote down what Peter remembered. Luke asked the eyewitnesses.\n\nThey wrote while many people who had seen Jesus were still alive. If they had got it wrong, someone would have said so.\n\n*Read Luke 1:1–4.*"}, {"number": 4, "title": "“Did they just make it up?”", "text": "Think about this. If you made up a story about yourself, would you put in the times you were scared and ran away?\n\nThe disciples did. The Gospels say Peter told people he did not even know Jesus.\n\nPeople telling the truth include the parts that make them look bad."}, {"number": 5, "title": "“Hasn’t it been changed, like the telephone game?”", "text": "In the telephone game one person whispers to the next, and nobody can check.\n\nThe Gospels were written down and copied in many places at once. We still have thousands of those copies. Some are very old.\n\nWhen we compare them, we can see what the first one said."}, {"number": 6, "title": "“Did a king pick the books?”", "text": "No. Christians were reading the four Gospels and Paul’s letters long before any king became a Christian.\n\nThey kept the books that came from Jesus’s own disciples and their friends."}, {"number": 7, "title": "“Did people always think Jesus was God?”", "text": "Yes, from the start.\n\nUnder a prison yard in Israel there is an old church floor. It was made when being a Christian was against the law. In it are the words “God Jesus Christ.”\n\n*Read John 20:28.*"}, {"number": 8, "title": "“Did Jesus really come alive again?”", "text": "Here is what we know. Jesus died on a cross. He was buried. On the third day the tomb was empty.\n\nThen his friends said they saw him. So did more than five hundred others. They kept saying it even when it got them killed.\n\nPeople do not die for something they know is a trick.\n\n*Read 1 Corinthians 15:3–6.*"}, {"number": 9, "title": "“What if someone still doesn’t believe?”", "text": "Give your friend room and time. Listen to what they are asking. You can offer good reasons, as Paul did, without putting pressure on them.\n\nTell the truth kindly and pray for your friend. God opens hearts and gives growth. Keep sharing the hope you have in Jesus.\n\n*Read 1 Corinthians 3:6.*"}, {"number": 10, "title": "“What if I don’t know the answer?”", "text": "Say, “Good question. I don’t know. Let’s find out.”\n\nThen ask someone who knows, or look it up together. It is fine not to know. It is not fine to make something up."}, {"number": 11, "title": "Why it matters", "text": "If Jesus is alive, then everything he said is true.\n\nHe said God loves the world. He said he came to rescue people who had turned away from God. He died to take away their sins, and he rose so they could live for ever.\n\nThat is the best news there is. It is true, and it is for you.\n\n*Read John 3:16 and John 11:25.*"}], "source": "Foundation-Claude/new-testament/books/NT-R-apologetics-short.md", "sha256": "2a918f3687b7b2c74103d508beb5c5abed95b3a608e081640ee5be5443f3bda0"}, "long": {"title": "The Case File", "subtitle": "How to think about Jesus, the Gospels and the evidence", "blurb": "Did Jesus exist? Were the Gospels written too late to trust? Has the Bible been changed? Did a Roman emperor decide which books went in? These questions deserve a careful hearing. Here is the evidence, with its strengths and limits in view.", "pages": [{"number": 1, "title": "The claim on the table", "text": "Christianity makes a claim that can be checked, and it stakes everything on it.\n\nPaul wrote to the Christians in Corinth that if Christ has not been raised, their faith is worthless and he himself is a liar. He did not say that the resurrection is a beautiful idea, or true for those who believe it. He said it happened, and that if it did not, they should all go home.\n\nThat is unusual. Most religions rest on teachings that would be just as wise whoever said them. Christianity rests on an event, in a known place, under a governor whose name we have.\n\nSo the right way to examine it is the way you would examine any event you did not see yourself. You look at the witnesses and the evidence.\n\n*Read 1 Corinthians 15:12–20.*"}, {"number": 2, "title": "How to ask", "text": "Before the evidence, a word about method.\n\nWhen someone tells you the Gospels are myths, do not start by arguing. Ask two questions. They come from Greg Koukl, who teaches Christians to be good ambassadors.\n\n**“What do you mean by that?”** A myth like Hercules? A true story that grew in the telling? A deliberate lie? These are different claims and need different answers.\n\n**“How did you come to that conclusion?”** The person who makes a claim has the job of supporting it. Give your friend time to explain their reasons, and be ready to consider them.\n\nAfter listening, offer something worth considering. You might ask, “Have you thought about how early the sources are?” If your friend wants to explore further, look at the evidence together.\n\nYou are not trying to corner anyone. You are trying to leave a pebble in a shoe.\n\nThe same rule applies to you. If you make a claim, be ready to say how you know."}, {"number": 3, "title": "Did Jesus exist?", "text": "You will meet this online. You will hardly ever meet it in a university. Historians of every belief, including atheists, agree that Jesus of Nazareth lived and was crucified.\n\nHere is why. Leave the Bible aside.\n\nThe Roman historian Tacitus, who despised Christians, says their founder was executed by Pontius Pilate in the reign of Tiberius. The Jewish historian Josephus mentions the death of “James, the brother of Jesus who was called Christ.” A Roman governor, Pliny, reports that Christians sing to Christ “as to a god.” A Greek satirist mocks them for worshipping a man crucified in Palestine. Jewish tradition remembered him as a sorcerer who was hanged at Passover.\n\nNone of these writers was a friend. Not one of them says, “He never lived.”\n\nBart Ehrman, a well-known skeptic of Christianity, wrote a whole book to make this point."}, {"number": 4, "title": "What the outsiders tell us", "text": "Suppose every Christian book had been lost. From Roman and Jewish writers alone we would still know this:\n\n1. Jesus lived in Judea in the early first century.\n2. He was known as a teacher and for deeds his enemies called sorcery.\n3. He had a brother named James.\n4. He was crucified under Pontius Pilate, when Tiberius was emperor.\n5. His movement did not die with him. It broke out again.\n6. His followers believed he was alive and worshipped him as God.\n7. Within a generation they were in Rome, and were willing to die.\n\nThat is the outline of the Gospels, from people who thought Christianity was a disease.\n\nIt does not prove the resurrection. It shows that the story is anchored in public events that nobody at the time disputed."}, {"number": 5, "title": "“Written long afterward”", "text": "A common picture: the Gospels were written centuries later, after the stories had grown.\n\nAsk how the person came to that conclusion. Then give the dates.\n\nJesus was crucified in AD 30 or 33. Paul’s letters begin about AD 48 and already assume the whole story. Most scholars, including skeptical ones, date Mark to about AD 70 and John to the 90s. Many Christians argue for earlier.\n\nUse the later dates. That is forty to sixty years. Think of something that happened forty years ago. Are there people alive who remember it? Could you publish a false account of it in the town where it happened?\n\nNow compare. Our best lives of Alexander the Great were written four hundred years after he died. Nobody calls them myths.\n\nThe Gospels are early. By the standards of ancient history they are very early."}, {"number": 6, "title": "The oldest sentence", "text": "There is something earlier than any Gospel.\n\nAbout AD 55 Paul reminds the Corinthians of what he taught them first. He uses the special words a rabbi used for passing on a fixed tradition: “I delivered to you what I also received.”\n\nThen comes a short, rhythmic summary. Christ died for our sins, according to the Scriptures. He was buried. He was raised on the third day. He appeared to Peter, then to the Twelve, then to more than five hundred at once, then to James.\n\nPaul received this. When? Most likely when he visited Peter and James in Jerusalem, about three years after his conversion. That puts the summary within about five years of the cross. Scholars who do not believe in the resurrection agree with that dating.\n\nSo the claim that Jesus rose was not a legend that built up slowly. It was there at the start.\n\n*Read 1 Corinthians 15:3–8 and Galatians 1:18–19.*"}, {"number": 7, "title": "Do they sound like eyewitnesses?", "text": "A detective named J. Warner Wallace spent his career on old unsolved murders. He was an atheist. He decided to test the Gospels as he would test any witness statement, and it changed his mind.\n\nOne thing he looked for was whether the witnesses knew what they should know.\n\nTake names. An Israeli scholar listed every Jewish name known from the land in that period. The commonest men’s names were Simon, Joseph, Judas and John. The commonest women’s was Mary. The Gospels have the same names in the same proportions. And where a name was common, they add a tag, as people did at the time: Simon *Peter*, Simon *the Zealot*, Mary *Magdalene*.\n\nJews living in Egypt or Rome used different names. A writer making up the story abroad, a century later, would have got them wrong."}, {"number": 8, "title": "Details nobody planned", "text": "Real witnesses fit together in ways they did not arrange.\n\nIn Matthew the guards hit Jesus and say, “Prophesy! Who hit you?” That is odd. He could see them. Luke, telling the same scene, mentions something Matthew left out: they had blindfolded him.\n\nIn John, Jesus is about to feed a crowd and asks Philip where they can buy bread. Why Philip? John does not say. Luke mentions that this happened near Bethsaida. And John, in a different chapter, mentions that Philip came from Bethsaida. He was the local.\n\nNeither writer is trying to explain the other. The pieces lock because both are describing something that happened.\n\nThere are dozens of these. They are very hard to fake, because the forger would have to plant half a clue in one book and half in another and hope someone noticed."}, {"number": 9, "title": "Things you would not invent", "text": "If you were making up a religion, there are things you would leave out.\n\nYou would not make your leaders look like cowards. In the Gospels the disciples misunderstand, argue about who is greatest, fall asleep and run. Peter, the chief of them, swears he has never met Jesus.\n\nYou would not have the founder’s own family think he had gone mad.\n\nYou would not have him die by crucifixion, the death of a slave, which Jews saw as God’s curse and Romans thought disgusting.\n\nAnd you would not make women the first to find the empty tomb. In that world a woman’s word counted for little in court. A storyteller wanting to be believed would have sent Peter.\n\nThe Gospel writers put all of this in. The simplest reason is that it was true and they felt bound to say so."}, {"number": 10, "title": "“They contradict each other”", "text": "The four Gospels do not tell every story the same way. One has one angel at the tomb and another has two. Does that sink them?\n\nAsk a detective. Wallace says that when witnesses agree word for word, he suspects they have been coached. Real witnesses stand in different places and notice different things. Their accounts need to be put together.\n\nOne writer mentions the angel who spoke. Another mentions that there were two. That is a difference. It is not a contradiction. A contradiction would be “there were two” against “there was only one.”\n\nMost of the famous problems are of this kind. A few are harder, and honest scholars say so.\n\nBut notice what all four agree on, without exception: he was crucified under Pilate, buried in Joseph’s tomb, the tomb was found empty by women on the first day of the week, and he was seen alive."}, {"number": 11, "title": "“It’s been copied too many times”", "text": "“The Bible has been copied and translated so often that nobody knows what it said.”\n\nThis is the telephone game objection. Somebody whispers a sentence, it goes round a circle, and it comes out as nonsense.\n\nBut think about what makes that game work. There is one line. Each person hears once. Nobody may check. And it is only a whisper.\n\nThe New Testament was copied in writing, in many lines at the same time, in many countries. And we do not have just the end of the line. We have copies from all along it: about 5,700 in Greek alone, some from within a century or so of the originals.\n\nImagine the telephone game with paper, a dozen separate circles, and the right to walk back and read what the third person wrote. You would recover the sentence easily.\n\nThat is the real situation."}, {"number": 12, "title": "What about all the differences?", "text": "You may hear that there are hundreds of thousands of differences among the manuscripts. That is true. It sounds terrible until you ask what they are.\n\nIf you copy a book by hand five thousand times, there will be slips. Nearly all are spellings, word order, or a skipped line that the next copy does not skip. “Jesus Christ” in one, “Christ Jesus” in another.\n\nScholars who have spent their lives on this say that less than one in a hundred affects the meaning and is uncertain, and that no Christian teaching depends on any of those.\n\nTwo longer passages are missing from the oldest copies: the last twelve verses of Mark, and the story of the woman caught in adultery in John. Your Bible tells you so in a note.\n\nNotice that. The evidence is not hidden. It is printed at the bottom of the page."}, {"number": 13, "title": "Be careful with numbers", "text": "Christians like to say that the New Testament has far more manuscripts than any other ancient book. It does. But some of the figures passed around are out of date, and it matters to get them right.\n\nIt is not true that Caesar’s *Gallic War* survives in only ten copies. There are about two hundred and fifty. Homer has about seventeen hundred and fifty, not six hundred.\n\nIt is not true that we could rebuild all but eleven verses of the New Testament from quotations in early writers. Nobody has shown that.\n\nAnd most of our Greek manuscripts are from the Middle Ages. The important ones are the early ones.\n\nThe honest comparison is still strong. Our earliest good copy of Tacitus is from about seven hundred years after he wrote, and no one doubts Tacitus. For the New Testament the gap is a century or two for whole books, and less for fragments.\n\nSay that. It is true, and it is enough."}, {"number": 14, "title": "Who chose the books?", "text": "A popular novel claimed that the emperor Constantine picked the books of the New Testament in AD 325, threw out eighty other gospels, and had Jesus voted God.\n\nAsk the two questions. What do you mean? How do you know?\n\nThe Council of Nicaea left records. They do not mention any list of books. The subject was how to state what Christians already believed about the Son.\n\nThe four Gospels were in use everywhere long before. About AD 180 Irenaeus wrote that there are four and can only be four. A list from about the same time has most of the New Testament. Churches read these books because they came from the apostles and those close to them.\n\nThe “other gospels,” such as Thomas and Judas, were written in the second century or later, by groups with quite different beliefs. They were not suppressed. They were late."}, {"number": 15, "title": "Was Jesus made God later?", "text": "The same novel says that until Constantine, Jesus was thought of as a human teacher.\n\nLook at the dates.\n\nAbout AD 55, Paul quotes what seems to be a hymn older than his letter. It says Christ was in the form of God, took the form of a servant, died on a cross, and that every knee will bow to him.\n\nAbout AD 110, Ignatius, on his way to be killed in Rome, calls Jesus “our God.”\n\nAbout AD 112, a Roman governor reports that Christians sing to Christ “as to a god.”\n\nAbout AD 200, a schoolboy in Rome scratches a cartoon mocking a Christian for worshipping a crucified god.\n\nAbout AD 230, a woman named Akeptous has “God Jesus Christ” set into a church floor at Megiddo.\n\nAll of this is before Constantine was born. He did not invent the belief. He inherited it.\n\n*Read Philippians 2:5–11.*"}, {"number": 16, "title": "“Copied from pagan myths”", "text": "You may hear that the story of Jesus was borrowed from older gods: Horus, Mithras, Osiris. It is said that they too were born of virgins on December 25, had twelve disciples, and rose after three days.\n\nAsk where that comes from. It will not be from the ancient sources. When you read the actual myths, the likenesses disappear. Mithras was born from a rock. Osiris was cut in pieces and became lord of the underworld. Neither rose in a body, in history, in front of witnesses.\n\nAnd think about who the first Christians were. They were Jews, who loathed pagan religion and would rather die than borrow from it.\n\nThe long lists of supposed parallels go back to writers of the nineteenth century, not to the ancient texts.\n\nThe Bible, in any case, does not say Jesus was born on December 25."}, {"number": 17, "title": "Can miracles happen?", "text": "Some people do not get as far as the evidence. They say dead men do not rise, so the reports must be wrong, whatever they say.\n\nAsk: how do you know dead men do not rise? The answer will be that we never see it happen. That is true. Left to itself, nature does not raise the dead. Christians agree. That is why they call it a miracle.\n\nThe real question is whether nature is always left to itself. If there is no God, then miracles are impossible. If there is a God who made the world, he can act in it, and a resurrection is no harder for him than a creation.\n\nSo this is a question about God, not about evidence. It should not be settled before the evidence is looked at.\n\nA fair mind does not say “it cannot have happened” before asking “did it?”"}, {"number": 18, "title": "The facts to explain", "text": "Now the center of the case. Here are five things that nearly all historians who study the period accept, whatever they believe. Gary Habermas, who has cataloged their writings, calls this the minimal facts approach.\n\n1. **Jesus died by crucifixion.**\n2. **His disciples believed he appeared to them alive.** They may have been wrong, but they were sincere. They suffered for it.\n3. **Paul, who had hunted the church, came to believe he had seen the risen Jesus.**\n4. **James, Jesus’s brother, who had not believed in him, did the same.**\n5. **The tomb was empty.** This one has slightly less support than the others, but most accept it. The preaching began in Jerusalem, where a body could have been produced.\n\nEach of these is a fact about the first century. Any account of what happened has to explain all five."}, {"number": 19, "title": "The other explanations", "text": "People have tried.\n\n**The disciples stole the body.** Then they knew it was a lie, and went to prison and death for it. People die for things they wrongly think are true. They do not die for what they know they made up. And it leaves out Paul and James.\n\n**They saw visions.** Hallucinations happen to single persons, not to groups, and they do not empty a tomb. And Paul was not grieving for Jesus. He was hunting his followers.\n\n**Jesus did not really die.** Roman soldiers knew their trade. A half-dead man crawling out of a tomb would not convince anyone he had conquered death.\n\n**They went to the wrong tomb.** Then the authorities had only to point to the right one.\n\n**It is a legend.** The creed in 1 Corinthians 15 is too early.\n\nEach explains one or two of the facts. None explains all five."}, {"number": 20, "title": "The explanation that fits", "text": "There is one account that covers all five without strain. God raised Jesus from the dead.\n\nIt explains the empty tomb. It explains why the disciples were sure, and why they changed from men in hiding to men who could not be shut up. It explains Paul and James, who had no wish to believe. It explains why the church began in Jerusalem, and why it worshipped a crucified man as God from the first.\n\nIt is the explanation the witnesses themselves gave.\n\nIs it the simplest? Only if God exists. If he does not, something else must have happened, though nobody can say what. If he does, this is exactly the kind of thing he might do.\n\nThe evidence gives us good grounds to trust that Jesus rose. It invites us to consider his promise and put our trust in him."}, {"number": 21, "title": "Reasons, prayer and grace", "text": "People may need time to consider a question. Some may also carry hurt from people they once trusted. A patient conversation makes room for both evidence and personal concerns.\n\nWe should ask and listen rather than guess why someone hesitates. A person may first trust the testimony of someone who has cared for them, then explore its reasons more fully. That can be a reasonable beginning. The evidence helps us consider who Jesus is, what he has done and why we can trust him.\n\nReformed Christians have always said that there are many strong arguments for the Bible, and that full assurance comes when the Holy Spirit opens a person’s heart to the word.\n\nGod uses faithful reasoning and prayer in his gracious work. We cannot earn his favor or change another person’s heart by the strength of our case. We can offer good reasons with patience, pray for our friends and trust God with the growth.\n\nKoukl calls it gardening: plant good seeds and care for them. God gives the growth, and someone else may see the fruit. Keep speaking truth with gentleness and hope.\n\n*Read Acts 17:2–4, John 6:44 and 1 Corinthians 3:6–9.*"}, {"number": 22, "title": "Why it matters that it happened", "text": "Does it matter whether this is history? Could it not be a beautiful story that helps people?\n\nNo. If Jesus did not rise, then death won, as it always does. Sins are not forgiven. Those who have died are gone. Christians are fools who gave up their lives for a mistake. Paul says exactly this.\n\nBut if he rose, then everything he said is confirmed. God has entered the world. Sin has been dealt with. Death has been beaten once, in a tomb outside Jerusalem, and will be beaten for everyone who belongs to him.\n\nKoukl says Christianity is not a private comfort. It is a picture of reality, an account of how things actually are.\n\nThat is why the stones and the papyri matter. They belong to the same world as the tomb.\n\n*Read 1 Corinthians 15:17–22.*"}, {"number": 23, "title": "A short list to carry", "text": "Five things you can say to anyone and defend:\n\n1. **Non-Christian writers confirm that Jesus lived and was crucified under Pilate.** Tacitus and Josephus are the main ones.\n2. **The earliest statement of the resurrection dates from within a few years of the cross.** It is in 1 Corinthians 15.\n3. **The Gospels were written while eyewitnesses were alive,** and they get names, places and titles right.\n4. **We have so many early copies that the text can be recovered,** and the doubtful places are printed in the footnotes.\n5. **Christians worshipped Jesus as God long before Constantine.** Pliny’s letter and the Megiddo floor show it.\n\nAnd three questions to ask, kindly:\n\n- What do you mean by that?\n- How did you come to that conclusion?\n- What do you think happened that Sunday morning?"}, {"number": 24, "title": "The reason for the hope", "text": "Peter tells Christians to be ready to give a reason for the hope they have, with gentleness and respect.\n\nNotice that the thing to be explained is hope. The reasons serve it.\n\nHere is the hope. God made the world good. We turned from him, and everything broke. He did not leave it broken. He came himself, in Jesus, lived the life we have not lived, and died the death we had earned. On the third day God raised him. Everyone who turns and trusts him is forgiven, and will be raised as he was.\n\nThat is either true or it is not. It is not the kind of thing that can be true for some people and not for others.\n\nYou have seen the evidence. It is strong. Paul used reasoning and evidence to persuade, and we can share our reasons with gentleness and respect. God can use these as means of his grace; our right standing with him is his gift through faith in Christ. Jesus invites us to trust him and follow him.\n\n*Read Acts 17:2–4, 1 Peter 3:15 and John 11:25–26.*"}], "source": "Foundation-Claude/new-testament/books/NT-R-apologetics-long.md", "sha256": "17df46b29ebe9f4be1ea6c6b44358002ca5467610d383d88eafae413b3937010"}}}];
window.BD_BOOK_SOURCES = {"faith": {"id": "faith", "label": "Augustine, Lombard and Berkhof · knowing, assent and trust", "citation": "Peter Lombard, Sentences 3.23.4, receiving Augustine’s distinction; Louis Berkhof, Systematic Theology, Part IV, “Faith,” section D, “The Elements of Faith.”", "trail": "Classical Reformed account; compare Grisanti, OT796 Notes, printed pp. 27–28.", "note": "Knowledge and agreement belong with personal reliance on Christ. The bridge is this book’s illustration, not a quotation from these authors.", "url": "https://www.ccel.org/ccel/berkhof/systematictheology.vi.viii.html", "consulted": "Berkhof’s elements-of-faith section consulted directly; Lombard’s section is a bibliographic trail, not a verified page quotation."}, "grisanti": {"id": "grisanti", "label": "Michael A. Grisanti · archaeology and Scripture", "citation": "“Recent Archaeological Discoveries That Lend Credence to the Historicity of the Scriptures.” Journal of the Evangelical Theological Society 56/3 (2013): 475–497, especially 475–476.", "trail": "Also OT796: Old Testament Introduction, Spring 2026 course notes, printed pp. 162–168. Private notes are cited, not redistributed.", "note": "Grisanti begins with confidence in Scripture and explains how archaeology can confirm its historical setting and answer objections. This book follows that perspective without treating an individual artifact as the whole Christian case.", "url": "https://etsjets.org/wp-content/uploads/2013/10/files_JETS-PDFs_56_56-3_JETS_56-3_475-497_Grisanti.pdf", "consulted": "Published article consulted directly, along with the privately supplied notes."}, "price": {"id": "price", "label": "J. Randall Price and H. Wayne House · confirmation", "citation": "Zondervan Handbook of Biblical Archaeology. Grand Rapids: Zondervan, 2017, pp. 10, 194–200.", "trail": "Definition on p. 10 quoted in Grisanti, OT796 Notes, printed p. 162; discovery chart pp. 194–200 supplied by Geoff.", "note": "Their definition of confirmation is “to give new assurance of the validity of something.” The chart supplies the bullae, Gezer, Gath, En-Gedi and Lachish leads. Original reports below refine individual claims.", "url": "", "consulted": "Chart scans consulted directly; definition consulted through Grisanti. Scans and third-party images are not reproduced."}, "dillard": {"id": "dillard", "label": "Raymond B. Dillard and Tremper Longman III · interpreting remains", "citation": "An Introduction to the Old Testament. Grand Rapids: Zondervan, 1994, p. 25.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 163.", "note": "Objects need interpretation, while a written narrative tells how its author understands events. Read material evidence and Scripture together rather than pretending either interpreter has no starting assumptions.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, "yamauchi": {"id": "yamauchi", "label": "Edwin M. Yamauchi · the fraction of surviving evidence", "citation": "The Stones and the Scriptures. J. B. Lippincott, 1972, pp. 146–157; calculation p. 156.", "trail": "Quoted in Grisanti, OT796 Notes, printed pp. 166–167 (PDF pp. 167–168).", "note": "This is a historical teaching estimate, not a measured percentage of today’s archaeological knowledge. Its five factors are 1/10 × 6/10 × 1/50 × 1/10 × 1/2 = 6/100,000 = 0.006%. Different questions have different survival and detection rates.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, "currid": {"id": "currid", "label": "John D. Currid · the incomplete record", "citation": "The Case for Biblical Archaeology: Uncovering the Historical Record of God’s Old Testament People. Phillipsburg, NJ: P&R, 2020, p. 6.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 166.", "note": "Currid describes archaeological evidence as fragmentary, piecemeal and incomplete. The four examples on the page summarize why traces can be lost; ancient rulers sometimes did record setbacks, so “never” would be too strong.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, "hittites": {"id": "hittites", "label": "Jared L. Miller · the archives at Hattusa", "citation": "“The Tablet Finds of Temple I from the Early Excavations at Boğazköy-Hattusa (1906–1912).” In The Discovery of an Anatolian Empire, 2017.", "trail": "Hittite example also in Grisanti, OT796 Notes, printed pp. 150, 163.", "note": "The excavations began in 1906 and uncovered major archives. Distinguish evidence for the Hittite empire from the separate question of every biblical use of the name Hittite.", "url": "https://www.assyriologie.uni-muenchen.de/personen/professoren/miller/publ_miller/early_excavation_bogazkoy_2017.pdf", "consulted": "Original study’s archive overview consulted."}, "belshazzar": {"id": "belshazzar", "label": "Nabonidus texts · Belshazzar’s place", "citation": "Nabonidus Cylinder from Ur (British Museum BM 91128); Verse Account of Nabonidus, column II, on authority entrusted to his eldest son.", "trail": "Grisanti, OT796 Notes, printed p. 150; appendix #76; Price and House, pp. 194–200.", "note": "The Ur cylinder names Belshazzar; the Verse Account describes delegated royal authority. This helps explain Daniel’s third place. Belshazzar’s precise legal title is a separate historical question. The Nabonidus Chronicle refers to the crown prince but is not the text that supplies his name.", "url": "https://www.britishmuseum.org/collection/object/W_1882-0714-1025", "consulted": "Text identifications checked through the supplied notes/appendix; museum collection link is for further reading."}, "confidence": {"id": "confidence", "label": "Iain Provan, V. Philips Long and Tremper Longman III · hearing the text", "citation": "A Biblical History of Israel, 2nd ed. Louisville: Westminster John Knox, 2015, p. 250.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 167.", "note": "They question making external corroboration a condition before a biblical text may be taken seriously. Ask what evidence actually counts against a claim, as well as what confirms it.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, "millard": {"id": "millard", "label": "Alan Millard · details that survive scrutiny", "citation": "“Did the Patriarchs Meet Philistines?” In An Excellent Fortress for His Armies, a Refuge for the People: Egyptological, Archaeological, and Biblical Studies in Honor of James K. Hoffmeier. Eisenbrauns, 2020, p. 230.", "trail": "Quoted in Grisanti, OT796 Notes, printed pp. 167–168.", "note": "Millard writes that “discovery after discovery points to the accuracy of biblical narrators.” This is quoted through the notes, not presented as a newly inspected book page.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, "koukl": {"id": "koukl", "label": "Gregory Koukl · questions and ambassadors", "citation": "Tactics: A Game Plan for Discussing Your Christian Convictions, updated and expanded edition. Zondervan, 2019; “Ancient Words, Ever True?” Stand to Reason.", "trail": "Columbo questions, the pebble-in-the-shoe image, gardening and knowledge/wisdom/character are credited to Koukl.", "note": "Questions invite a person to explain a claim. Offer truthful reasons with patience; the aim is persuasion rather than pressure.", "url": "https://www.str.org/w/ancient-words-ever-true-", "consulted": "Stand to Reason article consulted directly; the book is the fuller method reference."}, "cyrus": {"id": "cyrus", "label": "Mordechai Cogan · the Cyrus Cylinder", "citation": "“Cyrus Cylinder (2.124).” In The Context of Scripture, ed. William W. Hallo and K. Lawson Younger Jr., vol. 2. Brill, 2000, pp. 315–316, lines 20–36.", "trail": "Translation excerpt in Grisanti, OT796 appendix #87; Price and House, p. 198.", "note": "The text describes restoring shrines and communities in Mesopotamia. It supplies a restoration policy parallel; Ezra identifies its application to Jerusalem. It does not name the Jews.", "url": "https://www.britishmuseum.org/collection/object/W_1880-0617-1941", "consulted": "Cogan excerpt consulted through appendix #87; the museum page refused automated retrieval in this review."}, "tel-dan": {"id": "tel-dan", "label": "Avraham Biran and Joseph Naveh · House of David", "citation": "“An Aramaic Stele Fragment from Tel Dan.” Israel Exploration Journal 43 (1993): 81–98; “The Tel Dan Inscription: A New Fragment.” IEJ 45 (1995): 1–18.", "trail": "Grisanti appendix #96, citing Price and House p. 119; Beck, p. 130, entry 21.", "note": "The ninth-century Aramaic monument names the House of David. The enemy’s boast is evidence for a recognized dynasty. The fragment does not itself give the author’s name; attribution to Hazael is an interpretation.", "url": "https://ngsba.org/excavations/tel-dan/", "consulted": "Excavation project’s account consulted directly; IEJ articles remain the original-publication trail."}, "mesha": {"id": "mesha", "label": "André Lemaire · Mesha’s monument", "citation": "“House of David Restored in Moabite Inscription.” Biblical Archaeology Review 20/3 (May/June 1994): 30–37.", "trail": "Mesha and Omri: Beck chart; Grisanti’s archaeology discussion.", "note": "Mesha names Omri and Israel securely. Lemaire’s House of David restoration on the damaged Mesha line is a separate debated reading; this page does not rely on it.", "url": "https://collections.louvre.fr/en/ark:/53355/cl010120339", "consulted": "Louvre collection record consulted directly; Lemaire’s article remains the original-publication trail for the distinct proposed David reading."}, "kurkh": {"id": "kurkh", "label": "Ahab at Qarqar · Assyrian royal text", "citation": "Kurkh Monolith of Shalmaneser III; The Context of Scripture, vol. 2, pp. 263–264; British Museum BM 118884.", "trail": "Grisanti’s Assyrian-history discussion; Price and House discovery chart.", "note": "The annal lists Ahab of Israel among the coalition at Qarqar in 853 BC. Its troop totals are a royal claim; the named ruler is the point used here.", "url": "https://www.britishmuseum.org/collection/object/W_1863-0704-1", "consulted": "Object/text trail through the supplied sources; no claim of obtaining the full Context of Scripture volume."}, "obelisk": {"id": "obelisk", "label": "Shalmaneser III · Jehu’s tribute", "citation": "Black Obelisk, British Museum BM 118885; translation in Ancient Near Eastern Texts Relating to the Old Testament, ed. James B. Pritchard, 3rd ed., p. 281.", "trail": "Grisanti appendix #82, citing Alfred Hoerth, Archaeology and the Old Testament, p. 322.", "note": "The tribute register names Jehu in 841 BC. The kneeling figure may be Jehu or his envoy. Assyrian “son of Omri” identifies Israel’s royal house/land, not Jehu’s biological father.", "url": "https://oracc.museum.upenn.edu/nimrud/livesofobjects/blackobelisk/index.html", "consulted": "University of Pennsylvania’s Nimrud project account consulted; ANET/Hoerth are the publication trail."}, "sennacherib": {"id": "sennacherib", "label": "Sennacherib · the Jerusalem campaign", "citation": "Sennacherib’s annals, third campaign (701 BC), including the Taylor Prism, British Museum BM 91032.", "trail": "Grisanti appendix #82–84; Beck’s Old Testament archaeology chart.", "note": "The annals name Hezekiah and describe confining him in Jerusalem. They report tribute, not the capture of the city. Compare 2 Kings 18–19 and Isaiah 36–37.", "url": "https://www.britishmuseum.org/collection/object/W_1855-1003-1", "consulted": "Campaign text consulted in the supplied appendix; do not turn the bird-in-a-cage illustration into a claim about every detail of the siege."}, "beck": {"id": "beck", "label": "John A. Beck · the historical setting", "citation": "The Baker Book of Bible Charts, Maps, and Time Lines. Grand Rapids: Baker Books, 2016, “Archaeology of the Old Testament,” pp. 126–135.", "trail": "Privately supplied excerpt from Geoff.", "note": "Entry 4, p. 126, is the Beni Hasan painting; entry 12, p. 128, is Merneptah; entry 21, p. 130, is Tel Dan. The chart is a doorway to the object records, not a set of images reused in the game.", "url": "", "consulted": "Supplied chart consulted directly; pages and photographs are not reproduced."}, "kitchen": {"id": "kitchen", "label": "Kenneth A. Kitchen · prices and literary setting", "citation": "On the Reliability of the Old Testament. Grand Rapids: Eerdmans, 2003, pp. 344–345 (slave prices), and the treaty/covenant discussion.", "trail": "Kitchen is a recommended source in Grisanti’s notes; the specific price discussion is a publication trail.", "note": "Kitchen compares Joseph’s twenty shekels with early-second-millennium prices. Use it as contextual agreement, rather than a claim that no other price or later knowledge was possible.", "url": "", "consulted": "Kitchen’s original pp. 344–345 were not obtained; the page locator is supplied as further reading, not a direct quotation."}, "writing": {"id": "writing", "label": "Kenneth A. Kitchen · writing in the ancient world", "citation": "Ancient Orient and Old Testament. London: Tyndale Press, 1966, p. 136.", "trail": "Cited in Grisanti, OT796 Notes, printed p. 114; Ebla is also discussed in the notes.", "note": "Writing was used to preserve legal, administrative and literary material long before Israel’s monarchy. This rebuts the claim that early recording was impossible; particular books and passages require their own evidence.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, "bullae": {"id": "bullae", "label": "Eilat Mazar and Reut Livyatan Ben-Arie · Jeremiah’s officials", "citation": "“Hebrew and Non-Indicative Bullae.” In The Summit of the City of David Excavations 2005–2008: Final Reports, vol. I: Area G, ed. Eilat Mazar. Jerusalem: Old City Press, 2015, pp. 299–362.", "trail": "Price and House, p. 194, supplies the two named seals; Jeremiah 38:1 supplies the comparison.", "note": "Jehucal son of Shelemiah was found in 2005; Gedaliah son of Pashhur in 2008. Their names and fathers match the officials in Jeremiah. Those are the excavation dates, rather than the chart’s 2010/2017 entries.", "url": "https://www.academia.edu/19515093/Hebrew_and_Non_Indicative_Bullae_from_The_Summit_of_the_City_of_David", "consulted": "Authors’ posted report introduction consulted; chapter title, pages and 2005/2008 context checked against excavation-project records."}, "nebo": {"id": "nebo", "label": "Michael Jursa · Nabû-šarrussu-ukīn", "citation": "“Nabû-šarrussu-ukīn, rab ša-rēši, und ‘Nebusarsekim’ (Jer. 39,3).” Nouvelles Assyriologiques Brèves et Utilitaires 2008/1, no. 5, pp. 9–10; tablet BM 114789.", "trail": "Grisanti, OT796 Notes, printed p. 150; appendix #75.", "note": "The tablet names an official with a matching title, commonly identified with Jeremiah’s Nebo-Sarsekim. It records a temple payment; it is not a Babylonian copy of the siege narrative.", "url": "https://sepoa.fr/wp/wp-content/uploads/2012/06/2008-1.pdf", "consulted": "Original NABU issue and scholarly publication record checked; Jursa’s no. 5 appears on pp. 9–10. The supplied notes provide the biblical connection."}, "treaties": {"id": "treaties", "label": "Kenneth A. Kitchen · ancient treaty forms", "citation": "On the Reliability of the Old Testament (2003), discussion of second-millennium treaty/covenant structures.", "trail": "Grisanti, OT796 Notes, printed p. 150.", "note": "Historical prologue, obligations, witnesses and sanctions have second-millennium parallels. These are positive setting comparisons, not a stand-alone timestamp for a whole biblical book.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, "gilgamesh": {"id": "gilgamesh", "label": "The flood tablet · Nineveh", "citation": "Epic of Gilgamesh, Tablet XI; British Museum BM 120054 (K.3375).", "trail": "Beck, p. 126, entry 1; Grisanti, OT796 Notes, printed p. 149.", "note": "A shared flood, vessel and birds invite comparison. Distinguish Gilgamesh XI from Atrahasis, where human noise is especially explicit; this book does not merge those accounts.", "url": "https://www.britishmuseum.org/collection/object/W_K-3375", "consulted": "Object and story comparison checked through the supplied sources."}, "merneptah": {"id": "merneptah", "label": "Michael G. Hasel · Israel in Canaan", "citation": "“Israel in the Merneptah Stela.” Bulletin of the American Schools of Oriental Research 296 (1994): 45–61, DOI 10.2307/1357179; also Hasel’s discussion in Critical Issues in Early Israelite History (2008), p. 52.", "trail": "Grisanti appendix #79; Beck, p. 128, entry 12; notes printed p. 151.", "note": "The text names Israel as a people in Canaan around 1208 BC. This is the widely accepted inscriptional reference used here.", "url": "https://doi.org/10.2307/1357179", "consulted": "Publisher abstract and supplied appendix consulted; the full 1994 article was not obtained."}, "exodus-date": {"id": "exodus-date", "label": "Bruce K. Waltke and Eugene H. Merrill · Exodus/conquest dating", "citation": "Waltke, “Palestinian Artifactual Evidence Supporting the Early Date of the Exodus,” Bibliotheca Sacra 129 (1972): 33–47. Merrill, “Palestinian Archaeology and the Date of the Conquest: Do Tells Tell Tales?,” Grace Theological Journal 3/1 (1982): 107–121.", "trail": "Grisanti, OT796 Notes, printed pp. 139, 154–155; appendix #60.", "note": "Grisanti favors the early date and calls the chronology an intramural evangelical debate. The revised Egyptian timeline is a minority proposal; it should be compared with the full set of chronological anchors.", "url": "https://www.galaxie.com/article/gtj03-1-07", "consulted": "Merrill’s published opening argument and both bibliographic records consulted; Grisanti’s discussion consulted directly."}, "kuhn": {"id": "kuhn", "label": "Thomas S. Kuhn · paradigms", "citation": "The Structure of Scientific Revolutions. University of Chicago Press, 1962; later editions.", "trail": "Used as an analogy for historical interpretation, alongside Grisanti’s discussion of scholarly assumptions.", "note": "A paradigm is a framework for questions and evidence. Kuhn is not evidence that experts never change their minds or that a disliked theory is therefore right.", "url": "", "consulted": "Bibliographic method reference; no direct quotation from Kuhn is used."}, "hendel": {"id": "hendel", "label": "Ronald S. Hendel · a historical claim to test", "citation": "“Is There a Biblical Archaeology?” Biblical Archaeology Review 32/4 (July/August 2006): 20.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 164, and in Grisanti, JETS 56/3 (2013), p. 475.", "note": "The quotation gives the conclusion some scholars reach. Grisanti argues against it with particular finds; he also distinguishes different non-evangelical positions rather than calling all of them minimalists.", "url": "https://etsjets.org/wp-content/uploads/2013/10/files_JETS-PDFs_56_56-3_JETS_56-3_475-497_Grisanti.pdf", "consulted": "Hendel’s passage consulted through Grisanti’s published quotation, not the full BAR issue."}, "jericho": {"id": "jericho", "label": "Bryant G. Wood; Hendrik J. Bruins and Johannes van der Plicht · Jericho’s destruction", "citation": "“Did the Israelites Conquer Jericho? A New Look at the Archaeological Evidence.” Biblical Archaeology Review 16/2 (March/April 1990): 44–58. Bruins and van der Plicht, “Tell es-Sultan (Jericho): Radiocarbon results of short-lived cereal and multiyear charcoal samples from the end of the Middle Bronze Age,” Radiocarbon 37/2 (1995): 213–220, DOI 10.1017/S0033822200030666.", "trail": "Grisanti, OT796 Notes, printed pp. 154, 164; his JETS article pp. 477–480 surveys Kenyon, Wood and the dating disagreement.", "note": "Wood argues for an early-conquest date; Kathleen Kenyon dated the major destruction to around 1550 BC, and most radiocarbon work favors the earlier destruction. Compare the dating arguments as well as the dramatic visible match.", "url": "https://biblearchaeology.org/research-articles/did-the-israelites-conquer-jericho-a-new-look-at-the-archaeological-evidence/", "consulted": "Wood’s published argument, the radiocarbon study’s published abstract/record and Grisanti’s discussion consulted. This remains a debated identification."}, "gezer": {"id": "gezer", "label": "Lyndelle C. Webster and colleagues · dating Gezer", "citation": "“The chronology of Gezer from the end of the late bronze age to iron age II: A meeting point for radiocarbon, archaeology egyptology and the Bible.” PLOS ONE 18/11 (2023): e0293119. DOI 10.1371/journal.pone.0293119.", "trail": "Extends the Gezer lead in Price and House, p. 194 (Ortiz’s excavations).", "note": "The excavators’ radiocarbon model places major building/administrative development in the tenth century. It is evidence to weigh alongside 1 Kings 9; the building does not carry Solomon’s name.", "url": "https://journals.plos.org/plosone/article?id=10.1371/journal.pone.0293119", "consulted": "Original open-access research article consulted directly; the study’s conclusions remain scholarly interpretations, not an inscription naming its builder."}, "gath": {"id": "gath", "label": "Aren M. Maeir · Gath’s fortifications", "citation": "“Can Material Evidence of the Arameans Be Found in Philistia? The Case of Gath of the Philistines.” In Wandering Arameans, LAOS 5, 2017.", "trail": "Price and House, p. 194, Gath gate row; compare 1 Samuel 17:4.", "note": "The 2015 gate/fortification discovery belongs to Iron IIA, in the tenth/ninth-century city. Gath is a Philistine neighbor, not evidence that David ruled that city.", "url": "https://lisa.biu.ac.il/sites/lisa/files/shared/maeir_can_material_evidence_of_arameans_be_found_berlejung_et_al_eds_wandering_arameans_laos_5_2017_0.pdf", "consulted": "Excavator’s published description of the 2015 fortification discovery consulted."}, "qeiyafa": {"id": "qeiyafa", "label": "Yosef Garfinkel, Saar Ganor and Michael Hasel · Khirbet Qeiyafa", "citation": "“The Contribution of Khirbet Qeiyafa to Our Understanding of the Iron Age Period.” Strata 28 (2010): 43–52; Misgav, Garfinkel and Ganor, “The Ostracon,” in Khirbet Qeiyafa Vol. 1 (2009), pp. 243–257.", "trail": "Grisanti, JETS 56/3 (2013), pp. 490–493 and notes 104–119; OT796 appendix #94–95.", "note": "Fortifications, radiocarbon dates and a written ostracon put organized activity near the Valley of Elah around the early tenth century. Political identity and the ostracon’s exact reading are debated.", "url": "https://etsjets.org/wp-content/uploads/2013/10/files_JETS-PDFs_56_56-3_JETS_56-3_475-497_Grisanti.pdf", "consulted": "Original titles and findings traced through Grisanti’s published discussion; full excavation volumes were not obtained."}, "halpern": {"id": "halpern", "label": "Baruch Halpern · what missing buildings mean", "citation": "“The United Monarchy: David between Saul and Solomon.” In The Old Testament in Archaeology and History, 2017, p. 344.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 168 (the brief listed p. 167).", "note": "Halpern’s point is asymmetrical: public buildings can support a state, while their absence need not show that there was none. Quotation is reproduced through Grisanti, not claimed as independent access to the chapter.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, "isaiah": {"id": "isaiah", "label": "Israel Museum · the Great Isaiah Scroll", "citation": "The Great Isaiah Scroll, 1QIsaᵃ, Shrine of the Book; exhibition guide.", "trail": "Grisanti appendix #100; compare Paul D. Wegner, A Student’s Guide to Textual Criticism of the Bible (IVP Academic, 2006).", "note": "Copied around 125 BC, this is the same recognizable book, including chapter 53, before Christianity. Its many variants are published openly; stability does not require identical spelling or wording at every point.", "url": "https://www.imj.org.il/sites/default/files/IMJ%20Great%20Isaiah%20Scroll%20Exhibition.pdf", "consulted": "Museum presentation consulted; Wegner is further reading, not a newly obtained quotation."}, "engedi": {"id": "engedi", "label": "William Brent Seales and colleagues · virtual unwrapping", "citation": "“From damage to discovery via virtual unwrapping: Reading the scroll from En-Gedi.” Science Advances 2/9 (2016): e1601247. DOI 10.1126/sciadv.1601247.", "trail": "Price and House, p. 194, notes the initial 2015 decipherment; full publication followed in 2016.", "note": "The recovered Leviticus text agrees with the medieval consonantal text. It is a preserved portion, not every verse of Leviticus or later vowel signs.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC5031465/", "consulted": "Original open-access research article consulted directly."}, "ketef": {"id": "ketef", "label": "Gabriel Barkay, Marilyn J. Lundberg, Andrew G. Vaughn and Bruce Zuckerman · silver amulets", "citation": "“The Amulets from Ketef Hinnom: A New Edition and Evaluation.” BASOR 334 (2004): 41–71. DOI 10.2307/4150106.", "trail": "Grisanti, OT796 Notes, printed p. 52; the Investigation room has a study version.", "note": "Late-seventh/early-sixth-century BC silver amulets preserve blessing language overlapping Numbers 6:24–26, among the earliest surviving biblical wording. They are not a complete scroll of Numbers.", "url": "https://doi.org/10.2307/4150106", "consulted": "Publisher abstract consulted; full paper not obtained."}, "lachish": {"id": "lachish", "label": "Sa’ar Ganor and Igor Kreimerman · the gate shrine", "citation": "“An Eighth-Century b.c.e. Gate Shrine at Tel Lachish, Israel.” BASOR 381 (2019): 211–236. DOI 10.1086/703343.", "trail": "Price and House, p. 194, reports the 2016 discovery; compare 2 Kings 18:4.", "note": "The excavators interpret broken altar horns and a latrine installation as desecration associated with Hezekiah’s reform. Attribute that historical connection to the excavators.", "url": "https://www.journals.uchicago.edu/doi/10.1086/703343", "consulted": "Original excavation article’s publisher abstract consulted directly."}, "calvin": {"id": "calvin", "label": "John Calvin · Scripture’s own witness", "citation": "Institutes of the Christian Religion 1.7.4–5, Henry Beveridge translation.", "trail": "Grisanti, OT796 Notes, printed p. 28 (the brief listed p. 27).", "note": "Scripture is received as God’s Word; the Spirit seals its authority upon the heart. Other evidence has real value, without becoming the source of God’s authority.", "url": "https://www.ccel.org/ccel/calvin/institutes.iii.viii.html", "consulted": "Public-domain primary text consulted directly."}, "wcf": {"id": "wcf", "label": "Westminster Confession of Faith · chapter 1.5", "citation": "Westminster Confession of Faith 1.5 (1646).", "trail": "Also foundational to the museum’s Christian-hope panel.", "note": "The confession names many arguments for Scripture, then locates full assurance in the inward work of the Holy Spirit bearing witness by and with the Word.", "url": "https://www.opc.org/wcf.html", "consulted": "Confessional primary text; the book summarizes rather than replacing its teaching with an archaeology score."}, "kruger": {"id": "kruger", "label": "Michael J. Kruger · a self-authenticating canon", "citation": "Canon Revisited: Establishing the Origins and Authority of the New Testament Books. Crossway, 2012, p. 113.", "trail": "Quoted in Grisanti, OT796 Notes, printed p. 28.", "note": "Kruger joins Scripture’s qualities, reception, apostolic origins and the Spirit’s work. This is further reading behind the page’s Reformed account, not a direct book quotation.", "url": "", "consulted": "Course-note citation checked; original publication not obtained."}, "spurgeon": {"id": "spurgeon", "label": "Charles H. Spurgeon · let the lion out", "citation": "“Christ and His Co-workers,” sermon no. 2467, delivered June 10, 1886; published May 31, 1896, Metropolitan Tabernacle Pulpit, vol. 42.", "trail": "The familiar condensed lion saying appears, attributed, in Grisanti’s notes, printed p. 166. Here the actual sermon is cited.", "note": "The popular one-line “Scripture is like a lion” is a condensed saying. The sermon itself says “open the door, and let the lion out!” His point encourages proclaiming Christ, not abandoning truthful answers.", "url": "https://www.ccel.org/ccel/spurgeon/sermons42/sermons42.xxii.html", "consulted": "Public-domain primary sermon consulted directly."}, "chronicle": {"id": "chronicle", "label": "D. J. Wiseman · Babylon’s Jerusalem chronicle", "citation": "Chronicles of Chaldaean Kings (626–556 B.C.) in the British Museum. British Museum, 1956, Chronicle 5, BM 21946.", "trail": "Beck’s chart and the museum’s Babylon expedition.", "note": "The Babylonian text dates Jerusalem’s capture and the king’s replacement to Nebuchadnezzar’s seventh year, 2 Adar (597 BC). This is the earlier capture, before the city’s later destruction.", "url": "https://www.britishmuseum.org/collection/object/W_1896-0409-51", "consulted": "Publication/object trail through the supplied sources and existing exhibit record."}, "siloam": {"id": "siloam", "label": "Amos Frumkin, Aryeh Shimron and Jeff Rosenbaum · Hezekiah’s tunnel", "citation": "“Radiometric dating of the Siloam Tunnel, Jerusalem.” Nature 425 (2003): 169–171. DOI 10.1038/nature01875.", "trail": "The tunnel/Siloam inscription example in Grisanti’s archaeology discussion; compare 2 Kings 20:20 and 2 Chronicles 32:30.", "note": "Radiocarbon and uranium-thorium dating place the waterwork in the Iron Age II period. The surviving inscription describes the meeting of the cutting teams, without naming the king.", "url": "https://pubmed.ncbi.nlm.nih.gov/12968177/", "consulted": "Original research abstract consulted directly; no scanned course illustrations are reused."}, "forgeries": {"id": "forgeries", "label": "Museum of the Bible · scientific investigation of dealer fragments", "citation": "Dead Sea Scrolls Collection Scientific Research and Analysis, final report (2020), commissioned by Museum of the Bible; Art Fraud Insights and advisory team.", "trail": "Direct follow-up to the book’s warning about unverified antiquities claims.", "note": "The museum’s own investigation found its post-2002 textual fragments inauthentic. This concerns those dealer-supplied fragments, not the genuine Qumran Isaiah Scroll.", "url": "https://www.museumofthebible.org/dead-sea-scroll-fragments", "consulted": "Museum’s published report conclusion consulted directly."}, "ebal": {"id": "ebal", "label": "The Mount Ebal lead object · a published dispute", "citation": "Stripling et al., “You are Cursed by the God YHW: an early Hebrew inscription from Mt. Ebal,” Heritage Science 11 (2023), DOI 10.1186/s40494-023-00920-9; Mark S. Haughwout, “Mt. Ebal curse tablet? A refutation of the claims regarding the so called Mt. Ebal curse tablet,” Heritage Science 12, article 70 (2024), DOI 10.1186/s40494-023-01130-z.", "trail": "Published proposal and response, rather than a sensational headline.", "note": "The interpretation as a very early Hebrew curse inscription is contested. The object should not be advertised as an agreed discovery of the earliest biblical text.", "url": "https://www.nature.com/articles/s40494-023-01130-z", "consulted": "Published proposal and scholarly response consulted."}, "delta": {"id": "delta", "label": "Austrian Archaeological Institute · Avaris and Pi-Ramesse", "citation": "Tell el-Dabʿa / Avaris, excavation-project history, Austrian Archaeological Institute, Austrian Academy of Sciences; Manfred Bietak, Avaris: The Capital of the Hyksos (British Museum Press, 1996).", "trail": "The Egyptian-setting discussion in Grisanti and the original-concept Avaris study.", "note": "The excavated eastern Delta sites show Levantine settlement and the later Ramesside capital around Tell el-Dabʿa/Qantir. These identify a historical setting for Exodus, while the biblical account supplies the named deliverance.", "url": "https://www.oeaw.ac.at/en/oeai/institute/branches/cairo/excavations-projects/tell-el-dab%CA%BFa", "consulted": "Excavation institution’s published project history consulted directly; Bietak’s book is the fuller publication trail."}};
window.BD_BOOK_NOTICES = {"LSB": "Scripture quotations taken from the (LSB®) Legacy Standard Bible®, Copyright © 2021 by The Lockman Foundation. Used by permission. All rights reserved. Managed in partnership with Three Sixteen Publishing Inc. LSBible.org and 316publishing.com.", "CSB": "Scripture quotations marked CSB have been taken from the Christian Standard Bible®, Copyright © 2017, 2020 by Holman Bible Publishers. Used by permission. Christian Standard Bible® and CSB® are federally registered trademarks of Holman Bible Publishers."};
